W_EXTRA.push({"id":"KHK","title":"김희경전","unit":"회","persons":{"장설빙":{"name":"장설빙","alias":["설빙","장수정","수정","장 소저","장생","장 학사","장 원수","청주후","장 부인","상원 부인"],"sex":"F","note":"여성 영웅. 문창성 예언 속에 태어나 남장하고 장수정으로 개명, 과거 급제 후 병부상서·대원수가 됨. 정체를 스스로 밝힌 뒤 김희경의 정실이 됨."},"김희경":{"name":"김희경","alias":["희경","창성","김생","김 공자","김 한림","김 상서","도독","부마"],"sex":"M","note":"남주인공. 선동 적강. 장설빙과 정혼, 최씨·공주·이 소저와도 혼인. 출정 때는 장수정 아래 부도독."},"김평":{"name":"김평","alias":["김평장","평장","평장사"],"sex":"M","note":"김희경의 부친. 벼슬을 버리고 하람에 은거, 뒤에 승상으로 오름."},"석 부인":{"name":"석 부인","alias":["부인 석씨"],"sex":"F","note":"김희경의 모친."},"석 태위":{"name":"석 태위","alias":["석 대위","석 참정","석공","태위"],"sex":"M","note":"김희경의 외숙. 김희경을 여장 명창 초운으로 꾸며 최 승상 잔치에 들여보냄."},"장자영":{"name":"장자영","alias":["장 상서","장후","장공","장영"],"sex":"M","note":"장설빙의 부친. 이부상서. 소인의 참소로 북해에 귀양 가 죽음. 청주후, 위국왕으로 추증."},"정부인":{"name":"정부인","alias":[],"sex":"F","note":"장설빙의 모친. 태몽과 선녀의 예언을 받음. 설빙이 어릴 때 죽음."},"장원":{"name":"장원","alias":["승상 익주후"],"sex":"M","note":"장설빙의 조부."},"설낭":{"name":"설낭","alias":["유모"],"sex":"F","note":"장설빙의 유모. 투신까지 함께함."},"영춘":{"name":"영춘","alias":["춘랑"],"sex":"F","note":"장설빙의 시비. 혼약을 주선하고 남장 동행, 정체 공개를 간함."},"정 시랑":{"name":"정 시랑","alias":["정청축","정 아저씨"],"sex":"M","note":"정부인의 외사촌. 설빙이 의탁하러 갔으나 이미 죽음."},"소씨":{"name":"소씨","alias":["정 시랑 부인"],"sex":"F","note":"정 시랑의 부인. 외조카 유영을 찾아 떠남."},"소세필":{"name":"소세필","alias":["북해 노인","소공","참지"],"sex":"M","note":"장자영의 죽마고우. 북해에서 장자영을 장사 지내고 남장한 설빙을 알아봄. 뒤에 장수정의 상소로 사면되나 이미 죽음."},"북해 태수":{"name":"북해 태수","alias":["태수"],"sex":"M","note":"장자영에게 은혜를 입은 관원. 영구 호송을 도움."},"이영찬":{"name":"이영찬","alias":["이 참정","참정"],"sex":"M","note":"전 참지정사. 투신한 설빙을 건져 양육하고 딸과의 혼약을 청함."},"이 참정 부인":{"name":"이 참정 부인","alias":["참정 부인"],"sex":"F","note":"이영찬의 부인. 뒤에 김씨 집안에서 여생을 보냄."},"이 소저":{"name":"이 소저","alias":["이 부인"],"sex":"F","note":"이영찬의 딸. 남장한 장수정과 정혼했다가 김희경의 넷째 부인이 됨."},"최후":{"name":"최후","alias":["최 승상","좌승상"],"sex":"M","note":"좌승상. 김희경의 장인."},"최씨":{"name":"최씨","alias":["최 소저","최 부인","정렬부인"],"sex":"F","note":"김희경의 첫 아내. 봉구황곡으로 여장한 김희경을 알아봄. 장씨 신위를 세우자고 권함."},"춘빙":{"name":"춘빙","alias":[],"sex":"F","note":"최씨의 시비."},"황제":{"name":"황제","alias":["황상","천자","원제"],"sex":"M","note":"처음에는 송나라 문제 때로 시작하나 중반 이후 '원제', 나라는 '원나라'로 불림. 장수정과 김희경을 중용하고 혼인을 주선함."},"연왕":{"name":"연왕","alias":["왕윤"],"sex":"M","note":"황후 소생 황자. 장수정·김희경이 스승이 됨."},"일월공주":{"name":"일월공주","alias":["공주"],"sex":"F","note":"황제의 맏딸. 김희경과 혼인, 서열은 끝자리."},"명월공주":{"name":"명월공주","alias":[],"sex":"F","note":"황제의 둘째 딸. 장수정에게 시집보내려던 공주."},"정씨":{"name":"정씨","alias":["공주 유모"],"sex":"F","note":"일월공주의 유모. 장씨를 폐하자고 했다가 공주에게 꾸중을 들음."},"유협":{"name":"유협","alias":["위왕","왕숙 위왕"],"sex":"M","note":"황제의 숙부로 위국 왕. 사신을 베고 반란."},"남경왕":{"name":"남경왕","alias":["남왕"],"sex":"M","note":"위왕과 동맹한 반란 왕. 황성을 습격했다가 장수정에게 베임."},"방후열":{"name":"방후열","alias":[],"sex":"M","note":"위국 명장. 석호준을 베었으나 김희경에게 죽음."},"석호준":{"name":"석호준","alias":["호준"],"sex":"M","note":"원나라 장수. 방후열에게 전사."},"위영":{"name":"위영","alias":[],"sex":"M","note":"위나라 장수. 장수정에게 베임."},"마철":{"name":"마철","alias":[],"sex":"M","note":"남경 수성장. 항복 후 남경을 지킴."},"도인":{"name":"도인","alias":["유생","천신"],"sex":"M","note":"장수정에게 보검과 병서를 주고 사라진 이인."},"노승":{"name":"노승","alias":["화주승"],"sex":"M","note":"김평장에게 시주를 받고 발원을 권한 뒤 사라짐. 부처로 여겨짐."},"용궁 시녀":{"name":"용궁 시녀","alias":["여동"],"sex":"F","note":"남해 용궁 시녀. 환혼주로 설빙을 살림."},"선관":{"name":"선관","alias":[],"sex":"M","note":"결말에 내려와 김희경과 네 부인을 삼청으로 데려감."},"접숙공":{"name":"접숙공","alias":[],"sex":"M","note":"간신. 김평장과 혐의가 있어 김가가 영천으로 옮김(원문 뜻 불분명)."}},"places":{},"paras":[{"c":1,"sub":"김희경젼(金喜慶傳)","t":"이야기는 이렇다. 송(宋)나라 문제(文帝) 때 하람(河南) 벽도촌에 이름난 선비가 한 사람 있었으니, 성은 김(金)이요 이름은 평이었다. 대대로 공후(公侯)의 후예로, 젊은 나이에 과거에 급제하여 벼슬이 평장사(平章事)에 이르렀고 명망이 조정과 민간에 떨쳤다. 그러나 법도와 기강이 해이해지고 정령이 문란해져 군자의 무리는 물러나고 소인의 무리가 나서는 까닭에, 벼슬길에 뜻이 없어졌다. 이윤이 신야(莘野)에서 밭을 갈고 강태공이 위수(渭水)에서 낚시질하던 자취를 본받고자 상소를 지어 임금께 올려 벼슬을 사양하고, 고향에 돌아와 고기잡이 늙은이처럼 세월을 보내고 있었다[?]. 이때는 마침 봄 삼월 좋은 시절이었다. 후원에는 온갖 꽃이 만발하여 가지가지 붉디붉어 짙은 향기를 뿜고, 밭둑의 버들은 하늘하늘하여 잎잎마다 푸르디푸르러 연한 초록 휘장을 드리운 듯 봄빛을 자랑하였다. 꽃 사이에 춤추는 나비는 어지러이 날리는 눈송이 같고, 버들 사이 꾀꼬리는 나부끼는 금조각 같았다. 경치가 이러하니 즐거운 사람이 보면 흥취가 한층 더하겠고, 슬픈 사람이 보면 서글픈 마음이 한층 더할 만하였다. [?]","sp":[[114,117,"P","김평"]]},{"c":1,"sub":"","t":"하루는 평장이 첩첩이 쌓인 시름을 풀고자 부인 석씨와 함께 망월루에 올라 달빛을 감상하다가, 문득 마음이 더욱 처량해졌다. 평장이 부인에게 말하였다. \"우리가 세상에 살면서 모든 일에 부족함이 없으나, 다만 슬하에 핏줄 하나 없어 조상의 오랜 제사를 끊게 되었으니 어찌 슬프지 않겠소?\" 부인이 서글피 탄식하며 말하였다. \"이는 다 첩의 죄이옵니다. 법도 있는 가문에서 어진 숙녀를 구하여 자식을 보시면 첩도 죄를 면할까 하옵니다.\" 평장이 웃으며 대답하였다. \"부인에게 없는 자식이 다른 여자를 들인다고 어찌 생기겠소? 이는 다 내 팔자 탓이니 부인은 마음 편히 가지시오.\" 하며 부부가 서로 위로하였다.","sp":[[4,6,"P","김평"],[23,28,"P","석 부인"],[69,71,"P","김평"],[71,75,"P","이 소저"],[243,245,"P","김평"]]},{"c":1,"sub":"","t":"이때 갑자기 시비가 아뢰었다. \"문 앞에 웬 노승이 와서 상공 뵙기를 청하옵니다.\" 평장이 곧 바깥채로 나와 그 중을 들어오게 하니, 노승이 손에 육환장을 짚고 천천히 들어와 섬돌 아래에서 읍하였다. 평장이 답례하고 노승의 모습을 잠깐 살펴보니, 몸에 칠보 가사를 입었고 나이는 팔십이 넘은 듯한데 조금도 늙고 초라한 기색이 없었다. 과연 평범한 중이 아닌 줄 알고 일어나 물었다. \"노사는 어디 계시며 무슨 일로 누추한 곳에 수고로이 오셨소?\" 노승이 합장하고 두 번 절하며 말하였다. \"소승은 서천 원녕산 청룡사의 화주승이온데, 해가 오래되어 불상이 퇴락하였기에 상공 댁 소문을 듣고 천 리를 멀다 않고 왔사오니 시주해 주시기를 간절히 바라옵니다.\"","sp":[[25,27,"P","노승"],[47,49,"P","김평"],[75,77,"P","노승"],[112,114,"P","김평"],[121,123,"P","노승"],[250,252,"P","노승"],[290,293,"P","노승"]]},{"c":1,"sub":"","t":"평장이 대답하였다. \"절을 중수하려면 재물이 많이 들겠구려.\" 노승이 답하였다. \"재물은 많고 적음이 없사오니 상공 처분대로 하옵소서.\" 평장이 말하였다. \"그러면 황금 사만 냥과 백미 삼천 석을 줄 터이니, 적으나마 보태어 쓰시오.\" 노승이 사례하였다. \"황금 사만 냥도 많사온데 백미 삼천 석을 더 주시니 황공하고 감사하옵니다.\" 평장이 말하였다. \"대사는 지나치게 사례하지 마시오. 이 김평장이 나이 오십이 되도록 슬하에 핏줄 하나 없으니 재물을 어디에 쓰겠소? 불상께 시주나 하고 혹시 자식을 볼까 바랄 뿐이오.\" 노승이 답하였다. \"재물을 주고 자식을 보려 한다면 세상에 자식 없는 사람이 있겠사옵니까? 그러하오나 지극한 정성이면 하늘도 감동한다 하였사오니, 절에 와서 발원이나 해 보옵소서.\" 그러고는 하직하고 대청 아래로 내려가 두어 걸음에 간 곳이 없었다. 평장은 그제야 부처인 줄 알고 공중을 향하여 무수히 절하고, 안채로 들어가 이 이야기를 부인에게 하였다.","sp":[[0,2,"P","김평"],[35,37,"P","노승"],[77,79,"P","김평"],[132,134,"P","노승"],[187,189,"P","김평"],[219,222,"P","김평"],[292,294,"P","노승"],[432,434,"P","김평"]]},{"c":1,"sub":"","t":"이때는 봄 삼월 보름께였다. 칠 일 동안 재계하고 황룡사를 찾아가 동구에 다다르니, 산수가 빼어난 곳이었다. 풍경을 살펴보니 수많은 봉우리와 큰 산들이 푸른 하늘을 둘러 있고, 큰 소나무와 푸른 대나무, 잔잔한 푸른 시냇물이 굽이굽이 둘러 흐르며, 기이한 꽃과 풀은 봄빛을 자랑하고 난새와 봉황, 공작이 쌍쌍이 오갔다. 점점 들어가니 층층의 꽃 섬돌 위 백옥 탑상에 황금 불상이 앉아 있는데, 기상이 엄숙하여 사람의 정신을 놀라게 하였다. 평장이 부인과 함께 분향하고 축원하였다. \"김평장이 나이 오십이 넘도록 핏줄 하나 없어 조상의 제사를 전할 곳이 없사오니, 병신 자식이라도 점지하여 주옵소서.\" 하고 돌아왔다.","sp":[[246,248,"P","김평"],[248,252,"P","이 소저"],[270,273,"P","김평"]]},{"c":1,"sub":"","t":"과연 그날 밤 꿈을 꾸니, 한 선동(仙童)이 들어와 말하였다. \"소동은 천상에서 죄를 짓고 갈 곳을 모르고 있었는데, 황룡사 부처님이 가르쳐 주시어 왔사오니 어여삐 여기소서.\" 다시 물어보려 하는데 닭 우는 소리에 놀라 깨니 한바탕 꿈이었다. 매우 신기하게 여겨 부인을 불러 꿈 이야기를 하니, 부인이 말하였다. \"첩의 꿈도 그러하였습니다.\" 부부가 더욱 신기하게 여겨 기쁨을 이기지 못하였다. 곧 그달부터 태기가 있어 열 달이 차자 옥 같은 아들을 낳으니, 기상이 옥으로 깎은 듯하고 생김이 맑고 밝아 전날 꿈에 본 선동과 같았다. 평장 부부가 크게 기뻐하여 이름을 희경이라 하고 자(字)는 창성이라 하였다.","sp":[[299,301,"P","김평"],[318,320,"P","김희경"],[332,334,"P","김희경"]]},{"c":1,"sub":"","t":"점점 자라자 기상이 더욱 엄정하고 씩씩하며 골격이 비범하여, 이태백의 풍채와 반악의 고운 모습을 갖추고, 초패왕의 힘과 왕희지의 필법을 지녔다. 부모가 사랑하여 말하였다. \"우리가 늦도록 자식이 없어 서러워하니 하늘이 감동하시어 이러한 영특한 아들을 점지하셨으니, 비록 오늘 죽더라도 외로운 혼이 되는 것은 면하겠구나. 어찌 즐겁지 않으리오.\" 하고 날마다 기뻐하였다. 이럭저럭 희경의 나이 열다섯이 되니, 빼어난 거동과 건장함이 사람들 가운데 뛰어났다.","sp":[[212,214,"P","김희경"]]},{"c":1,"sub":"","t":"이에 평장 부부가 희경을 불러 말하였다. \"네가 이미 장성하였는데 혼인이 늦어 가니 우리 근심이 적지 않다. 하람은 본래 작은 땅이라 인물이 드물어 참으로 봉황 같은 짝이 없을 것이다. 서울에 너의 외숙 석 대위가 있으니, 네가 찾아가 우리의 외로운 처지를 말하고 네 배필을 구하여라. 장안은 번화한 곳이니 너의 재주를 결코 버리지 않을 것이다. 명문대가에서 요조숙녀를 구하여 우리 마음을 위로하고, 과거에 급제하여 조상을 영화롭게 하면 그것이 우리의 소원이다. 네 뜻은 어떠하냐?\" 생은 본래 사람됨이 화려하고 뜻이 시원스러워 일편단심에 천지의 기운과 만고의 영기를 품었으니, 참으로 옛사람의 풍도를 지니고 있었다. 늘 탄식하며 말하기를 \"어느 때에 과거에 급제하여 이름을 떨치고, 규방의 숙녀를 구하여 원앙 같은 짝을 이루어 부모를 봉양할까 하는 것이 소원인데, 이곳이 좁아 숙녀와 가인이 없을까 걱정하였더니, 이제 부모님 분부가 이러하시니 참으로 내 진심을 이룰 때로다.\" 하고는 기꺼이 대답하였다. \"소자의 용렬한 재주로 어떤 숙녀가 달가워하겠사옵니까? 그러나 아내를 구하느라 공명을 잃지 않는 것이 옳사오니 부모님 분부대로 받들어 행하겠사옵니다.\"","sp":[[3,5,"P","김평"],[10,12,"P","김희경"],[114,118,"P","석 태위"]]},{"c":1,"sub":"","t":"평장이 크게 기뻐하여 편지 한 통을 써 주니, 생이 행장을 꾸려 부모께 하직하고 서울로 향하였다. 형초 땅에 이르니 날씨가 무척 더워 몸이 고단하므로 한 주막을 찾아 잠깐 쉬었다. 그런데 문득 한 줄기 향기로운 바람이 맑은 옥경(玉鏡)을 이끌고 가다가 침상에 떨어뜨렸다. 생이 매우 이상하게 여겨 몸을 일으켜 문밖에 나서 두루 살펴보니, 동편 화원 가운데 초가 몇 칸이 있는데 인적이 고요하였다. 그 서편에 대나무 창을 반쯤 열고 한 미인이 눈길을 흘려 먼 산을 바라보고 있는데, 마음속에 시름이 있는 빛을 띠었다. 그 모습과 처연한 기색은 참으로 가을 달도 빛을 잃고 복숭아꽃도 무색할 만하였고, 흰 이와 붉은 입술, 달 같은 자태와 꽃 같은 얼굴이 사람을 놀라게 하였다. 아리따운 자태와 윤택한 거동은 진실로 만고의 절색이요 참된 요조숙녀였다. 어찌 마음이 황홀하지 않겠는가. 생이 한번 보자 마음이 흔들리고 정신이 아득해지는 것을 깨닫지 못하였다.","sp":[[0,2,"P","김평"]]},{"c":1,"sub":"","t":"이윽고 기운을 수습하고 크게 탄식하며 말하였다. \"예로부터 어떤 사람이 저런 미인을 얻어 짝을 이루었던가. 어찌 저런 미색이 세상에 있단 말인가. 푸른 하늘의 해와 달도 한쪽만 비추지 않는다는데, 어찌 해와 달의 정기를 저 한 사람에게만 맡겼는고. 모르겠구나, 하늘이 감동하시어 저러한 가인을 세상에 내신 것은 반드시 뜻이 있는 일이겠으나, 하늘과 땅처럼 처지가 동떨어져 인연이 막혔으니 슬프도다. 은하수에 어느 때에 오작교가 놓이며, 초왕의 높은 누대에서 언제 향기로운 꿈을 이루리오. 애석하다, 월하노인이 맺어 준 인연이 내게는 늦었구나. 이 일로 마음에 병이 들겠도다.\" 다시 생각하니 날은 점점 길어 가고 때는 이미 늦었으니 참으로 서글펐다. \"계집아이 하나를 구하여 근본을 물어보리라.\" 하였다.","sp":[]},{"c":1,"sub":"","t":"이에 몸을 돌려 주막으로 가려 하는데, 문득 밖에서 한 차환(시중드는 계집종)이 들어오다가 생을 보고 크게 놀라 물었다. \"어떤 공자이시기에 예법의 경계를 잊고 공후 댁 규수의 처소를 엿보십니까?\" 생도 놀라 멍하니 몸을 돌리며 말하였다. \"나는 시골의 미천한 선비인데, 과거를 보러 황도로 가다가 날씨가 너무 무더워 더위를 피하려고 그늘을 찾아다니던 중이오. 그대는 어찌 사람을 붙들고 가지 못하게 하오? 나는 객지의 울적함 때문에 시름을 풀고자 술 두어 잔을 마셨는데, 주량이 넓지 못하여 기운이 희미하고 정신이 아득하여 봄바람이 몸을 흔들어 부치는 줄도 깨닫지 못하고 여기에 이르러 그대의 꾸짖음을 받았으니, 달게 받겠으며 부끄럽소. 감히 묻노니, 공후 댁 규수의 처소라 하니 무슨 일로 어디를 향하시며, 그대는 누구이기에 나그네의 실례를 꾸짖는 것이오? 청컨대 밝혀 말하여 죄를 용서받게 하오.\"","sp":[]},{"c":1,"sub":"","t":"그 차환이 앵두 같은 입술을 열어 낭랑하게 대답하였다. \"우리 소저는 승상 익주후 장원의 직계 손녀요, 참지정사 이부상서 장자영의 따님이시니, 소첩의 주인이십니다. 마침 고향으로 가시다가 날씨가 무척 더워 잠깐 더위를 피하여 쉬고 계십니다.\" 생이 다시 물으려 하는데, 문득 안에서 부르는 소리를 듣고 차환이 급히 가 버렸다. 생이 보니 대나무 창을 굳게 닫아 꽃 같은 얼굴이 가려졌다. 애처로움을 이기지 못하여 꽃을 두고 시 한 수를 지어 스스로 마음을 위로하고, 두루 서성이다가 주점으로 돌아오니 이미 해가 기울었다. 노복을 불러 말하였다. \"내 몸이 피곤하고 날이 이미 저물었으니 하룻밤 묵어 가고자 한다.\" 노복이 감히 거스르지 못하였으나, 마음속으로 그가 머무는 뜻은 알지 못하였다. 이때 그 차환은 생을 한번 보고 마음속으로 감탄해 마지않아 속으로 눈여겨 두었다.","sp":[[39,45,"P","장원"],[46,48,"P","장원"],[58,60,"P","소세필"],[68,71,"P","장자영"]]},{"c":1,"sub":"","t":"이때 그 여자는 이부상서 장자영의 딸이었다. 그 모친 정부인이 꿈에 눈이 쌓인 곳에 복숭아꽃 한 가지가 피었는데, 겨울철에 봄빛이 드문 것이라 그 꽃을 꺾어 손에 쥐고 구경하였다. 그러다 문득 광풍이 일어나 크게 불자 부인이 그 꽃을 놓쳐 버리니, 꽃이 바람에 날려 공중 높이 떠서 제멋대로 오가다가 문득 간 곳이 없어졌다. 몹시 서운하여 놀라 깨니 한바탕 꿈이었다. 마음에 이상히 여겼는데, 과연 그달부터 태기가 있어 열 달이 찼다. 하루는 기이한 향내가 집안에 진동하며 오색구름이 사방에 자욱하였다. 부인이 고단하여 침석에 기대어 있었더니 구름 속에서 한 선녀가 내려와 절하고 말하였다. \"첩은 월궁 선녀이온데 항아의 명을 받아 아기 낳으시는 것을 도우러 왔사오니 의심하지 마소서.\" 말을 마치고 부인을 붙들어 침석에 누이니, 부인은 아무 정신 없이 누워 있었다. 이윽고 순산하자 선녀가 옥합의 향수를 기울여 아기를 씻겨 누이고 부인께 하직하며 말하였다. \"천상의 문창성이 방랑을 따라와, 푸른 복숭아꽃이 쇠와 돌 사이에 떨어졌사오니 하늘의 명을 어기지 마소서.\" 부인이 한참 뒤에야 정신을 차려 보니 딸이었다.","sp":[[14,17,"P","장자영"],[30,33,"P","정부인"],[487,489,"P","김희경"]]},{"c":1,"sub":"","t":"기상이 비범하고 목소리가 맑아 선녀의 태가 있으니, 비록 아들은 아니나 그 속되지 않음을 기뻐하였다. 상서 또한 용모가 화려함을 사랑하여 이름을 설빙이라 하고 자(字)는 영이라 하였다. 점점 자라자 얼굴이 풍성하고 고와 모란꽃이 봄바람에 나부끼는 듯, 가을 달이 채색 구름 위로 솟는 듯하였다. 타고난 바탕이 영민하여 다섯 살에 이르러서는 가르치지 않은 글을 통달하고, 시서와 백가의 글을 모르는 것이 없으며, 필법은 용이 날고 뱀이 오르는 듯하였다. 상서가 더욱 사랑하여 칭찬하였다. \"문창성이 인간에 내려오지 않았다면 내 딸의 재주를 당할 이가 없겠구나.\" 그러자 부인이 문득 선녀의 말을 깨닫고, 해산할 때 선녀가 하던 말을 모두 전하였다. 상서가 크게 놀라 말하였다. \"이 말이 과연 참말이 되겠구려. 그러나 푸른 복숭아꽃이 쇠와 돌 사이에 떨어졌다는 말은 무슨 뜻인고? 나중에 저절로 알게 되겠으나 지금은 참으로 깨닫기 어렵도다.\" 하고 기뻐하였다. [?]","sp":[[81,83,"P","장설빙"],[274,276,"P","김희경"]]},{"c":1,"sub":"","t":"한편, 고운 얼굴에 운명이 박하다는 말이 예로부터 있으니, 소저처럼 세상에 다시없는 경국지색이 어찌 박명을 면하겠는가. 나이 열 살을 넘기지 못하여 모친 정부인이 갑자기 병을 얻어 온갖 약이 효험이 없어 끝내 일어나지 못하였다. 상서와 소저가 망극하여 통곡으로 지내다가 선산에 장사 지냈다. 그 뒤 소저는 상서를 모시고 세월을 보냈는데, 세월이 빨라 삼 년이 지나니 소저의 나이 열셋이었다. 상서가 지극히 아껴 널리 군자를 구하여 소저의 배필을 정하려 하였으나 얻지 못하여 날마다 근심하였다.","sp":[[86,89,"P","정부인"]]},{"c":1,"sub":"","t":"그런데 집안 운수가 불행하여 액운이 겹쳤다. 상서가 소인의 참소를 입어 북해의 먼 변방으로 귀양 가게 되었다. 소저의 일생을 근심하여 유모 설낭과 시비 영춘을 불러 말하였다. \"내 이제 운수가 불길하여 만 리 밖으로 귀양을 가니 다시 돌아올 기약을 정할 수 없다. 죽어도 한은 없으나, 다만 딸의 혼사를 정하지 못하고 이별을 당하니 어찌 슬프지 않으리오. 다시 만날 날을 알 수 없으니 저승에 가서도 눈을 감지 못하겠구나. 설낭은 빙아의 어미 같은 사람이라, 이름은 비록 종이나 형제 같은 정이 있으니 빙아의 평생을 너희에게 부탁한다. 내가 돌아오기를 기다리지 말고 널리 군자를 구하여 빙아의 혼인이 늦어지지 않게 하여라. 내가 비록 저승에 가더라도 외로운 혼이 오히려 즐거우리니, 삼가 명을 어기지 마라.\" 하고 당부하였다. [?]","sp":[[75,77,"P","설낭"],[78,80,"P","설낭"],[85,87,"P","영춘"],[237,239,"P","설낭"]]},{"c":1,"sub":"","t":"또 소저의 손을 잡고 눈물을 줄줄 흘리며 말하였다. \"나는 이미 버린 사람이 되었으나, 네 일생은 아직 손안에 있다. 여자의 부끄러움 때문에 백년대사를 허술히 생각하지 마라.\" 상서의 이 말에 설낭과 영춘 등이 망극하여 통곡을 그치지 않고, 소저 또한 상서를 붙들고 애통하게 우니, 그 슬픔이 정부인 상사 때보다 더하였다. 누군들 슬프지 않겠는가. 이럭저럭 날이 늦어 가자 사령이 길 떠나기를 재촉하였다. 상서가 다시 소저를 잘 보살피라 하며 말하였다. \"만일 의지할 곳이 없거든, 정부인의 외사촌 정 시랑 청축이 탁주 땅에 살고 있으니 그 사람을 찾아가면 자연히 구해 줄 것이다.\" 말을 마치고 차마 떨치기 어려운 소매를 떨쳐 북해로 향하니, 온 집안의 주인과 종이 모두 슬퍼 통곡하여 풀과 나무, 새와 짐승까지도 다 슬퍼하는 듯하였다. 소저는 혼절하여 아무것도 몰랐으나 설낭과 영춘이 서로 위로하며 보호하였다.","sp":[[108,110,"P","설낭"],[112,114,"P","영춘"],[164,167,"P","정부인"],[270,273,"P","정부인"],[279,283,"P","정 시랑"],[433,435,"P","설낭"],[437,439,"P","영춘"]]},{"c":1,"sub":"","t":"어느덧 세월이 오래되자 가산이 점점 탕진되고 노복들은 다 흩어져 달아났으며, 친척 또한 돌보아 주는 이가 없었다. 혈혈단신으로 외로움을 견디지 못하여, 소저가 설낭, 영춘과 의논하였다. \"우리가 이같이 외롭고 인심이 험하니 참으로 형세가 위태롭다. 아버님 분부대로 탁주의 정 아저씨를 찾아가고자 하니, 남은 가산을 팔아 가지고 그리로 가 의탁하여 아버님 돌아오시기를 기다리는 것이 좋은 방책이라. 너희 생각은 어떠하냐?\" 영춘 등이 말하였다. \"소저의 말씀이 금옥 같으시니 소비들이 어찌 따르지 않겠사옵니까?\" 하고 마침내 가산을 정리하여 돈으로 바꾸고 행장을 꾸려 탁주로 향하였다.","sp":[[89,91,"P","설낭"],[93,95,"P","영춘"],[152,157,"P","정 시랑"],[236,238,"P","영춘"]]},{"c":1,"sub":"","t":"형초 땅에 이르러서는 날이 더워 더위를 피하려고 여관을 빌려 쉬었다. 영춘을 시켜 주루에 차를 사러 보내고, 창에 기대어 조용히 기다리고 있었다. 문득 눈을 들어 보니 서편 작은 길가에 한 소년이 서성이고 있었다. 골격이 비상하고 풍채가 빼어나 이태백의 화려함과 반악의 고움을 겸하였으니, 가을 물결 같은 두 눈은 강산의 정기를 띤 듯하고, 가는 버들이 봄바람에 나부끼는 듯하며, 옥 같은 얼굴에 술기운이 반쯤 어려 있었다. 진실로 물속의 기린이요 천고의 기이한 남자였다. 한번 보자 스스로 탄복해 마지않아 한참을 바라보다가 창을 닫았다.","sp":[[39,41,"P","영춘"]]},{"c":1,"sub":"","t":"속으로 생각하였다. '가인이 군자를 만나고 군자가 숙녀를 만나면 자연히 서로 알아보는 법이다.' 스스로 탄복함을 그치지 못하며 다시 생각하였다. '내 비록 어머니의 가르침을 듣지 못하였으나 아버님의 경계를 힘입어 옛 글을 꽤 널리 읽었다. 예로부터 지금까지 어진 군자와 풍류호사의 행적을 본받은 일이 많으나 아직 마음으로 굴복한 적이 없었는데, 이 사람은 참으로 고금에 처음이로다.' 규수의 처신으로 괴이하나 그 거동을 다시 보려고 창을 열고 보니, 영춘이 그 소년과 수작하고 있었다. 행여 자기 기색이 드러날까 두려워 유모를 시켜 급히 부르니, 영춘이 들어왔다. 소저가 물었다. \"주점이 얼마나 멀기에 이리 더디었느냐?\" 영춘이 대답하였다. \"주점은 멀지 않으나 찾아가 보니 마땅치 않기에 다른 차를 구하느라 자연히 늦었사옵니다.\" 하고 옥 찻잔에 차를 부어 드리니, 소저가 받아 마신 뒤 저녁을 먹고 이부자리를 내려 조용히 자려 하였다.","sp":[[252,254,"P","영춘"],[291,293,"P","설낭"],[306,308,"P","영춘"],[349,351,"P","영춘"]]},{"c":1,"sub":"","t":"영춘이 문득 이야기를 꺼내 묻고 답하는데, 갑자기 달빛이 서쪽 창에 가득하여 환히 비추었다. 영춘이 소저를 위로하며 함께 밝은 달을 구경하고 거닐었다. 밤이 깊은 뒤 영춘이 다른 사람이 없는 틈을 타 꿇어앉아 말하였다. \"소첩이 소저를 모신 지 이미 열두 해가 되었습니다. 이름은 비록 종과 주인이오나 소저를 우러르는 마음은 임금과 신하의 의리를 겸하였사오니, 소저의 일생은 첩이 염려할 바입니다. 이제 마님께서는 황천의 손님이 되시고 대감께서는 또한 멀리 귀양 간 나그네가 되셨으니, 소저의 일생은 물결 위의 부평초요 광풍에 떠도는 구름 같습니다. 부모가 혼인을 주관하는 사람과는 다르옵니다. 이제 탁주로 가시나 정 시랑은 본디 도량이 넓지 못하시고, 게다가 땅이 좁고 사람이 적사오니 어찌 소저의 배필이 있겠사옵니까? 낙엽은 가을바람을 따라가게 마련이지만, 제 한 가지 마음에 맺힌 근심은 이것밖에 없사오니 소저의 생각은 어떠하시옵니까?\" [?]","sp":[[0,2,"P","영춘"],[52,54,"P","영춘"],[54,58,"P","이 소저"],[93,95,"P","영춘"],[126,130,"P","이 소저"],[344,348,"P","정 시랑"]]},{"c":1,"sub":"","t":"소저가 다 듣고 발끈 낯빛을 바꾸며 말하였다. \"혼인은 인륜의 큰일이라 그 부모에게 달려 있다. 내 비록 불행하여 어머님은 아니 계시나, 머지않아 사면의 조서가 내리면 아버님이 돌아오실 것이다. 내 나이 이제 겨우 꽃다운 때가 되었는데 어찌 일생을 이리 근심하겠느냐. 네 말로 나의 일생을 이끌 바가 아니다.\" 말을 마치자 옥 같은 얼굴에 온화한 빛이 사라지고 가을 서리 같은 기운이 일어나 동짓달 차가운 달과 같으니, 사람으로 하여금 오싹하고 움츠러들어 말을 붙이지 못하게 하였다.","sp":[]},{"c":1,"sub":"","t":"영춘이 머뭇거리다가 서글프게 대답하였다. \"소저의 밝은 말씀은 그러하오나, 소저께서는 하나만 알고 둘은 모르십니다. 대감께서 천은을 입어 돌아오시면 다행이지만, 만일 임금의 명이 없으면 소저의 꽃다운 때가 덧없이 지나갈 것이요 남는 것은 다만 홀몸뿐입니다. 소저께서는 어찌 깊이 생각하지 않으시고 하찮은 여자의 부끄러움만 품어 천지간에 용납되지 못할 죄인이 되고자 하십니까? 소첩의 얕은 소견으로는 도리어 소저의 밝은 생각에 따를 수 없사옵니다.\" 말을 마치자 근심스러운 기색이 얼굴에 가득하여 그 애달픈 모습을 차마 볼 수 없었다.","sp":[[0,2,"P","영춘"]]},{"c":1,"sub":"","t":"소저가 이에 마음속으로 생각하였다. '영춘이 나와 십 년을 함께 살아 서로 속마음을 비추어 정의가 자못 깊으나, 아직 이런 말을 입 밖에 낸 적이 없었다. 이곳이 비록 조용하나 객점이라 이런 이야기는 하지 않을 듯한데, 이제 까닭 없이 이런 말을 하여 내 속을 떠보려 하니, 이상하기는 하나 그 뜻을 들어 보리라.' 소저가 낯빛을 누그러뜨리고 웃으며 말하였다. \"모르겠구나. 내가 너와 비록 종과 주인 사이이나 일찍이 서로 마음을 허락하여 조금도 숨기는 것이 없었다. 오늘에 이르러 나의 평생을 염려하니 정의로는 가깝지만, 남은 날이 많은데 굳이 구차한 일을 생각하지 않고 갑자기 기이한 말을 늘어놓아 나를 곤란하게 하니 참으로 그 뜻을 알 수 없다. 이제 이 말을 꺼낸 데에는 반드시 까닭이 있을 것이다. 내 굳이 구구히 물을 일은 아니나 네 속뜻을 알고자 하니 밝혀 말하여라.\"","sp":[[21,23,"P","영춘"]]},{"c":1,"sub":"","t":"영춘이 소저의 얼굴빛이 태연한 것을 보고 숨기지 못하여 옷깃을 여미고 대답하였다. \"소첩의 속뜻을 들으려 하시니 어찌 간담을 쏟아 마음을 아뢰지 않겠사옵니까. 이제 소저께서 탁주로 가시면 혈혈단신으로 정 시랑의 손아래가 되어 백 년의 고락이 그분께 달리게 됩니다. 시랑은 보건대 너그럽고 큰 인물이 아니요 사람을 알아보는 눈이 없사오니, 동상(東床)의 사위가 재주와 덕을 겸하였는지 알지 못할 것입니다. 만일 이두(李杜) 같은 풍채를 버리고 장영 같은 경박한 자를 골라 소저의 일생을 괴롭게 한다면 어찌 애석하지 않겠사옵니까. 그러므로 첩의 얕은 생각에는, 소저께서 죽더라도 스스로 부탁할 곳이 있어야 하겠습니다. 남의 집 문하에 의탁하기 전에 스스로 찾아보아 영웅호걸이 아니면 어진 군자를 골라 인연을 맺은 뒤에 정씨 문중에 들어가신다면, 시랑도 마음대로 처리하지 못할 것입니다. 그분께 의탁해 있다가 대감께서 돌아오시거든 의리로써 아뢰고 예를 이루면, 반드시 옛사람의 덕행을 본받는 일이 될 것입니다. 이는 들뜬 행실이 아니라 밝은 여자가 스스로 혼처를 고르는 일이옵니다. 소저의 높으신 소견을 소첩이 알 바는 아니오나, 스스로 혼인을 고른다는 두 글자를 꺼리시어 인륜의 큰일을 살피지 않으시니 소첩이 속으로 한심하게 여기옵니다.\" [?]","sp":[[0,2,"P","영춘"],[2,6,"P","이 소저"],[112,116,"P","정 시랑"],[247,249,"P","장자영"],[400,402,"P","정씨"]]},{"c":1,"sub":"","t":"소저가 이 말을 듣고 놀랐으나 곰곰이 생각해 보니 비록 예법은 아니나 또한 음란한 여자의 천한 행실도 아니었다. 한참 생각하다가 말하였다. \"네 말이 진실로 나를 위한 것이니 지극히 고맙다. 그러나 나는 흠 없는 백옥 같은 몸이니, 어디서 눈을 들어 군자를 고르며 언제 입을 열어 스스로 혼인을 말하겠느냐. 일생의 괴로움을 면하려다가 후세의 웃음거리가 되지 않을까 하노라.\" [?]","sp":[]},{"c":1,"sub":"","t":"영춘이 또 말하였다. \"옛날 농옥은 진(秦)나라 공주였으나 소사(蕭史)를 따라갔는데도 지금껏 음란하다는 말이 없고, 오히려 지음(知音)을 만나 갔다고 합니다. 이제 소저께서는 농옥의 부귀에 미치지 못하시고, 대감의 세력도 진왕을 당하지 못합니다. 농옥 같은 일을 하셔도 오히려 비웃음이 없을 터인데, 소저께서는 이제 혼약만 정하고 뒷날 예를 이루시는 것이 어찌 비웃음거리가 되겠사옵니까. 온 천하를 돌며 인걸을 구해도 얻지 못할 터인데, 옥 같은 군자를 눈앞에 두고 기회를 잃으시겠사옵니까. 바라건대 소저께서는 깊이 살피소서.\"","sp":[[0,2,"P","영춘"],[27,29,"P","일월공주"]]},{"c":1,"sub":"","t":"소저는 눈앞에 군자가 있다는 말을 이상히 여겨 생각하다가 깨달았다. '영춘이 그 소년과 이야기하더니 그에게 뜻이 있는가. 그렇다면 영춘이 생각하는 마음이 가볍지 않구나.' 그리고 다시 물었다. \"너의 말이 비록 이상하나 가문의 덕에 누를 끼칠 일은 없겠다. 그런데 눈앞에 군자가 있다는 말은 그 속을 알 수 없구나. 어쨌든 너의 소견을 듣고 싶다.\"","sp":[[39,41,"P","영춘"],[73,75,"P","영춘"]]},{"c":1,"sub":"","t":"영춘이 기쁘게 대답하였다. \"소비가 오늘 차를 사러 갔다가 우연히 한 소년을 만났습니다. 그 소년의 옥 같은 얼굴과 영웅다운 풍채는 사람들 가운데 제일이요, 헌헌장부의 태도였습니다. 가슴속에는 온 천하를 품을 도량을 지녔고 어진 군자의 도를 품었으니, 머지않아 용안을 받들고 이름을 역사에 올릴 것입니다. 소첩이 비록 사람을 비추는 거울은 없사오나 사람의 속을 비추는 두 눈이 있사오니, 한번 보고 장래의 길흉을 어찌 모르겠습니까. 참으로 말하자면 소저가 아니면 그 짝이 없을 것이요, 그 소년이 아니면 소저의 짝이 없을 것입니다. 그래서 마음을 기울여 그 소년의 사는 곳과 이름을 물으니, 하람 벽도촌 김평장의 아드님이요 서울 석 참정의 외조카라 하였습니다. 가문이 서로 걸맞아 서로 욕될 것이 없기에 소비가 뒷일을 생각하여 그 주인을 알고 왔사오니, 참으로 이 기회를 버리지 못할 것입니다. 바라건대 소저께서는 깊이 생각하소서.\"","sp":[[0,2,"P","영춘"],[338,341,"P","김평"],[352,356,"P","석 태위"]]},{"c":1,"sub":"","t":"소저가 이 말을 듣고 영춘의 사람 보는 눈에 탄복하면서도 참으로 대답하기 어려워 한참 잠자코 있다가, 문득 깨달아 생각하였다. '어머님 살아 계실 때, 문창성이 푸른 복숭아꽃 나무가 되어 쇠와 돌 사이에 떨어졌다는 말이 있었으나 끝내 풀지 못하여 늘 아버님과 의논하셨다. 오늘 영춘의 말을 들으니 그 소년의 성이 김(金)씨요 외가의 성이 석(石)씨라 하니 쇠와 돌 사이라는 말이 맞고, 또 벽도(碧桃)촌에 산다 하니 징험이 분명하다. 참으로 이것을 이른 말이로다. 정말 이러하면 이는 반드시 하늘이 정한 연분이라 사람의 힘으로는 어쩔 수 없으니 어찌하리오.' 마침내 탄식하며 말하였다. \"영춘아, 네 말을 들으니 환히 깨닫는 바가 있기에 세속의 부끄러움을 잊고 나의 백년가약을 네 말대로 정하노라. 부디 예사로 여기지 마라.\"","sp":[[12,14,"P","영춘"],[86,88,"P","김희경"],[155,157,"P","영춘"],[329,331,"P","영춘"]]},{"c":1,"sub":"","t":"영춘이 기쁨을 이기지 못하여 사례하였다. \"옛날 한 고조도 남의 말을 듣고 깨달은 바가 있었다 하고, 옛글에 미친 사람의 말도 성인이 가려 쓴다 하였는데, 이제 소비의 한마디로 환히 깨달으시니 소비가 비록 여자이오나 마음이 매우 상쾌하옵니다. 참으로 옛사람에게 뒤질 것이 없사오니, 소비들이 소저의 수하인 것이 부끄럽지 않사옵니다.\" 소저는 묵묵히 대답하지 않았다. 설낭이 웃으며 말하였다. \"제 자랑은 예부터 하지 않는 법인데, 춘랑이 너무 제 몸을 칭찬하는가 싶구나. 그렇기는 하나 인륜의 큰일이니 지나치게 실없는 말은 하지 마라.\" 영춘이 웃음을 참으며 말하였다. \"유모는 걱정 마오. 내 비록 말재주가 둔하나 소진이 육국을 달래던 것도 오히려 우습게 여기는데, 어찌 군자와 숙녀의 짝 맺는 일을 걱정하리오.\" 말을 마치자 훌쩍 일어나 김 공자의 숙소를 찾아갔다.","sp":[[0,2,"P","영춘"],[161,165,"P","이 소저"],[205,207,"P","설낭"],[241,243,"P","영춘"],[301,303,"P","영춘"],[320,322,"P","설낭"],[415,419,"P","김희경"]]},{"c":1,"sub":"","t":"이때 김 공자는 소저를 본 뒤로 모든 일에 마음이 없어, 홀로 책상에 기대어 지은 꽃 시 한 수를 읊으며 오수(午睡)에 잠겨 마음을 달래려 하였으나, 눈에 보이는 것은 소저의 아리따운 용모뿐이었다. 문득 아이 종이 들어와 아뢰었다. \"밖에 웬 차환이 와서 상공을 뵙고자 하옵니다.\" 들어오라 하니 영춘이 나아가 절하고 말하였다. \"두 밤 사이에 객지에서 평안하셨사옵니까?\" 이는 바로 장 소저의 시비였다. 생이 크게 놀라고 기뻐하여 멍하니 말하였다. \"전날 술에 취하여 실례를 저질러 그대의 꾸짖음을 받았으니 지금도 부끄럽소. 그런데 그대가 이 누추한 곳에 왔으니 반드시 까닭이 있을 터라 궁금하오. 밝혀 말하여 내 의심을 풀어 주오.\" 영춘이 살짝 웃으며 말하였다. \"타고난 성품이 경솔하여 우연히 실언한 것인데, 오히려 상공께서 이렇게 겸손하시니 황송함을 이기지 못하겠습니다. 그러나 소비가 당돌하게 높으신 분 앞에 나선 것은 속에 품은 바를 아뢰고자 해서이오니, 상공께서는 기꺼이 받아 주시겠사옵니까?\" 생이 기쁘게 말하였다. \"타향의 나그네를 위하여 마음을 쓰고자 하니, 이 또한 우연한 일이 아니오.\" [?]","sp":[[3,7,"P","김희경"],[166,168,"P","영춘"],[215,219,"P","장설빙"],[357,359,"P","영춘"]]},{"c":1,"sub":"","t":"영춘이 한참 머뭇거리다가 말하였다. \"소비 주인의 존함은 이미 아시겠지만 그 집안 사정은 모르실 것이니 이제 자세히 아뢰겠습니다. 바라건대 허투루 여기지 마시고 소비의 말을 외람되다 하지 마소서. 우리 상서께서는 전생에 죄가 무거웠던지 나이 서른이 넘도록 슬하에 아들딸 하나 없으시더니, 하늘이 돕고 신령이 도와 늘그막에 딸 하나를 얻으셨습니다. 장강(莊姜)의 미색과 반희의 윤택함을 겸하였고, 사마천의 문장과 왕희지의 필법을 겸하였으니, 대감과 마님께서 지극히 사랑하시어 손안의 보옥처럼 여기셨습니다. 소저가 여덟 살 때 마님이 세상을 떠나시니, 하늘에 사무치는 슬픔을 누르고 상서를 모시고 세월을 보냈습니다. 그런데 남은 액운이 다하지 않아 지난해 봄 대감께서 소인의 참소를 입어 북해의 먼 변방으로 귀양 가시니 소저의 일생이 외롭게 되었습니다. 탁주 땅의 정 시랑은 소비 마님의 외사촌이시니 소저에게는 외숙이 됩니다. 대감께서 귀양 가실 때 그곳에 의탁하라 하시고, 소저의 일생을 유모 설낭과 소비에게 부탁하시며, 소비에게 좋은 사윗감을 골라 때를 놓치지 말라 경계하셨습니다. 소비가 천한 몸으로 무거운 부탁을 맡아 밤낮으로 근심하며 이제 탁주로 가던 길인데, 하늘이 살피시고 귀신이 도우시어 뜻밖에 상공을 만나니 평생의 소망이 이루어진 것입니다. 참으로 하늘이 정하신 바를 사람의 힘으로는 어쩔 수 없습니다. 상공께서 소비의 말을 더럽다 아니하시면 소저와 유모에게 전하고 소비가 스스로 월하노인의 소임을 맡겠사오니, 높으신 뜻은 어떠하시옵니까?\" [?]","sp":[[0,2,"P","영춘"],[426,430,"P","정 시랑"],[496,498,"P","설낭"],[499,501,"P","설낭"],[707,709,"P","설낭"]]},{"c":1,"sub":"","t":"생이 이 말을 듣고 한편으로 기쁘고 한편으로 슬퍼 한참 말이 없다가 천천히 대답하였다. \"소생이 미천한 선비인데 더럽다 하지 않고 규중의 옥 같은 처녀를 천거하니 지극히 고맙소. 어찌 사양하겠소. 그러나 그대는 상서의 분부를 받았으니 스스로 결단할 수 있겠지만, 나는 부모님이 계시니 마음대로 할 수 없소. 그렇지만 그대의 금옥 같은 말을 저버리지 않을 터이니 세상의 임시방편을 따르겠소.\"","sp":[]},{"c":1,"sub":"","t":"영춘이 또 말하였다. \"상공의 말씀이 우리 소저의 마음과 같습니다. 대감께서 비록 분부를 내리셨으나 소저께서 늘 하시는 말씀이, 대감께서 돌아오시기를 기다려 사람을 따르는 것이 소원이요, 그렇지 않으면 탁주의 정 시랑이 외숙이라 친아버지 못지않으니 그분의 처분을 기다리겠다 하십니다. 상공께서 이렇게 말씀하지 않으셔도 혼례는 서둘러 치를 수 없습니다. 굳게 약속을 정하고 서울에 올라가 어서 뜻을 이루시어 이름을 금방에 올리신 뒤, 고향에 돌아가 이 뜻을 부모님께 아뢰고 탁주로 통하시면 일이 분명해질 것입니다. 상공의 생각을 듣고 싶사옵니다.\" [?]","sp":[[0,2,"P","영춘"],[117,121,"P","정 시랑"]]},{"c":1,"sub":"","t":"생이 속으로 과연 옳다고 여겨 대답하였다. \"그대 말이 참으로 마땅하오. 그러나 세상일은 뒤집히는 일이 많고, 서로 길 가는 나그네로서 길에서 한때 한 말을 굳게 믿는 일도 드물지요. 매우 외람되나 그대가 나를 위한다면, 소저의 얼굴을 직접 대하여 약속을 완전히 정하고 싶소. 그러면 상공의 뜻을 어기는 일도 없고, 마주한 말로 맺어 평생의 신의를 지킬 수 있을 것이니, 바라건대 그대는 널리 생각하여 소저께 이 말을 전해 주오.\" 영춘이 한참 머뭇거리다가 대답하였다. \"상공의 말씀이 어찌 외람되겠습니까. 뒷날의 기약을 완전히 하려 하시니 그 신의에 속으로 탄복하옵니다. 우리 소저는 타고난 성품이 활달하시어 생각이 좁지 않으시니, 하늘이 정한 큰일을 정하려 하시면 구구히 사양하지는 않으실 것입니다. 소비가 돌아가 이 뜻을 전한 뒤 다시 기쁜 소식을 알려 드리겠습니다.\" 하고 마침내 하직하고 돌아왔다.","sp":[[242,244,"P","영춘"]]},{"c":1,"sub":"","t":"이때 소저와 설낭이 서로 의논하고 있는데, 영춘이 웃음을 머금고 들어와 앉았다. 설낭이 웃으며 말하였다. \"양대(陽臺)의 소식이 어떠하기에 춘랑의 얼굴빛이 그리 바쁜고?\" 영춘이 낭랑하게 웃으며 말하였다. \"소식은 기쁘지만, 양왕의 그림자가 무산을 구경하고자 하니 소저께서 기꺼이 허락하시겠습니까?\" 소저가 듣고 눈썹을 찡그리며 발끈 낯빛을 바꾸어 말하였다. \"선녀가 아침 구름이 되는 것은 음란한 행실이요, 양왕을 찾는 것은 방탕한 짓이다. 네가 어찌 한마디 실없는 말로 내 마음을 허락받으려 하느냐?\"","sp":[[7,9,"P","설낭"],[24,26,"P","영춘"],[45,47,"P","설낭"],[78,80,"P","영춘"],[96,98,"P","영춘"]]},{"c":1,"sub":"","t":"영춘이 문득 깨닫고 사죄하였다. \"이는 진심이 아니라 유모가 묻는 말에 가볍게 대답하다가 소저의 마음을 놀라게 하였으니 황공하기 그지없사옵니다.\" 그리고 공자의 말을 전하며, 또 얼굴을 마주하여 굳게 맹세하고자 하는 뜻을 갖추어 아뢰고 낭랑하게 웃으며 말하였다. \"제가 이 말을 마음에 두고 있다가 말을 바꾸어 소저의 얼음 같은 마음을 움직였으니 황공함을 이기지 못하겠사옵니다.\" 소저가 살짝 노한 빛을 띠며 말하였다. \"이 또한 예가 아니다. 내 몸이 규수인데 어찌 바깥사람을 대하여 눈을 들어 마주 본단 말이냐. 그러면 어찌 남의 웃음거리가 되지 않겠느냐.\" 영춘이 정색하고 말하였다. \"이 말씀은 소저께서 참으로 사리에 통하지 못하신 것이옵니다. 이제 소저의 마음을 그분께 허락하여 인륜을 이루려 하신다면, 비록 청하는 일이 없더라도 우리가 먼저 스스로 구하여 크게 약속을 이루는 것이 옳사온데, 어찌 큰일은 등한히 생각하시고 작은 일에 얽매이시옵니까?\"","sp":[[0,2,"P","영춘"],[30,32,"P","설낭"],[315,317,"P","영춘"]]},{"c":1,"sub":"","t":"설낭도 의리로 타이르니 소저가 곰곰이 생각하다가 말하였다. \"일이 이미 이러하니 피하는 것도 옳지 않고 하지 않는 것도 옳지 않다. 그러나 이렇게 사사로이 몸을 구차하게 맡기는 것을 생각하면 마음이 편치 않구나. 언약을 맺으려면 굳이 밤을 틈타 청하는 것은 몹시 이상하니, 내일 아침에 떳떳이 청하여 남의 의심이 없게 하여라.\" 영춘이 감탄하며 말하였다. \"소저의 밝으신 소견은 다른 사람은 따르지 못하겠사옵니다.\" 이럭저럭 밤이 이미 깊어 세 사람은 이불에 기대어 잠깐 졸았다.","sp":[[0,2,"P","설낭"],[184,186,"P","영춘"]]},{"c":1,"sub":"","t":"동녘이 밝아 오자 영춘이 곧 공자의 숙소에 가서 생에게 밤사이 안부를 묻고, 소저의 앞뒤 말을 전하며 오시기를 청하였다. 생도 그 사리 밝음에 탄복하며 영춘을 따라 함께 소저의 처소에 이르렀다. 객실에 자리를 깔아 놓고 설낭이 공자를 맞아 중당에 자리를 정하였다. 설낭이 눈을 들어 공자를 보니, 옥 같은 모습과 영웅다운 풍채가 원근에 빛나고, 시원스러운 골격이 훨훨 나는 학이요 빼어난 용과 같으니 어찌 속된 사람이라 하겠는가. 한번 보자 설낭이 속으로 크게 놀라, 영춘의 사람 보는 눈에 탄복해 마지않았다.","sp":[[10,12,"P","영춘"],[85,87,"P","영춘"],[123,125,"P","설낭"],[148,150,"P","설낭"],[247,249,"P","설낭"],[262,264,"P","영춘"]]},{"c":1,"sub":"","t":"이윽고 영춘이 소저를 이끌어 중헌에 이르자, 생이 엉겁결에 몸을 일으켜 맞이하였다. 예를 마친 뒤 동서로 나누어 자리를 정하였다. 생이 살짝 눈을 들어 소저를 보니, 구름 같은 쪽 찐 머리에 옥비녀를 꽂았고 빛깔 없는 옷에 단장을 하지 않은 채 겨우 영춘에게 의지하여 앉아 있었다. 밝은 달이 검은 구름에 가린 듯, 모란꽃이 향내 속에 잠긴 듯, 온갖 시름 띤 기색이 은은하여 봄빛을 띠었으니 그 애처로운 모습을 차마 볼 수 없었다. 생은 이미 영춘의 말을 들었으므로 구차하게 근심하는 처지를 짐작하고 마음속 슬픔을 이기지 못하였다.","sp":[[4,6,"P","영춘"],[6,10,"P","이 소저"],[140,142,"P","영춘"],[249,251,"P","영춘"]]},{"c":1,"sub":"","t":"이윽고 푸른 소매를 들어 읍하고 나직이 말하였다. \"소생은 시골의 필부로, 부모의 명을 받들어 서울의 외숙을 뵈러 가던 길이었습니다. 하늘이 무심치 않으시어 우연히 소저의 행차를 만났으나 서로 길 가는 나그네라 인연을 맺을 길이 없었는데, 마침 영춘 낭자의 어진 마음을 힘입어 여기에 이르렀으니 감사함을 이기지 못하겠습니다. 평생의 큰일을 소홀히 정할 길이 없어 뜻을 전하였더니, 소저께서 옛 자취를 본받으시어 저의 외람됨을 꺼리지 않으시니 소저의 높은 절의에 속으로 탄복합니다. 시비를 통해 소저의 뜻을 전하신 것은 들었사오나, 외로우신 처지를 생각하니 참으로 애석한 마음을 인정상 금할 수 없습니다. 그러나 이렇게 만난 것도 하늘의 뜻이오니 소저께서 이제 사양하려 하셔도 그리 되지 않을 것입니다. 스스로 혼인을 정한다는 혐의를 꺼리지 마시고 백년가약을 한마디로 정해 주시면, 제가 이제 서울에 가서 외숙을 뵌 뒤 집에 돌아가더라도 오늘 들은 신의를 저버리고 신의 없고 의롭지 못한 일을 하지는 않겠습니다. 소저께서는 저의 용렬함을 허물하지 마시고 한 말씀으로 허락해 주시면, 제가 부끄러움을 면할까 하옵니다.\" 하고 눈을 들어 숙연히 바라보았다.","sp":[[137,139,"P","영춘"]]},{"c":1,"sub":"","t":"소저가 눈썹을 숙이고 다 듣고 나자 부끄러운 빛이 옥 같은 얼굴에 가득하여, 흰 눈 같은 귀밑에 붉은빛이 솟고 먼 산 같은 눈썹에 시름이 쌓였다. 생이 자주 눈을 들어 보았으나 소저는 태연히 대답이 없었다. 영춘이 나아가 소저의 구름 같은 머리를 어루만지며 말하였다. \"소저께서는 어찌 이리 졸렬하십니까? 끝내 대답이 없으시면 공자께서 몹시 무안해하실 것입니다. 평소 세속의 태도를 하찮다 하시더니 소저께서 어찌 스스로 그렇게 하십니까?\"","sp":[[116,118,"P","영춘"]]},{"c":1,"sub":"","t":"소저가 마지못하여 옥 같은 손으로 붉은 입술을 가리고 영춘을 통해 말을 전하였다. \"첩은 본래 외로운 인생입니다. 죄악이 지중하여 어린 나이에 어머님을 여의었고, 이제 와서는 남은 액운이 다하지 않아 아버님마저 만 리 밖으로 귀양을 가셨습니다. 닥치는 일마다 망극하여 구곡간장이 맺히니 마땅히 아버님 뒤를 좇아야 할 것이나, 여자의 몸이라 마음대로 하지 못합니다. 혈혈단신으로 의탁할 곳이 없어 남은 목숨을 부지하려고 탁주 땅의 외숙을 찾아가던 중, 천만뜻밖에 군자께서 마음 써 주시니 감사합니다. 얼굴을 들고 말을 나누는 것이 가문의 가르침이 아닌 줄 아오나, 세상일을 헤아릴 수 없기에 부끄러움을 무릅쓰고 아룁니다. 박하게 여기지 않으시고 평생을 염려해 주신다면 첩 또한 결초보은을 본받겠사오니, 바라옵건대 길이 생각하시어 오늘의 기약을 저버리지 마소서.\" 말을 마치자 애처로운 붉은빛에 해도 빛을 잃는 듯하니, 푸른 하늘이 감응하실 만하였다. 어찌 무심할 수 있겠는가.","sp":[[30,32,"P","영춘"]]},{"c":1,"sub":"","t":"생이 다 듣고 몸을 굽혀 사례하였다. \"소저의 지극한 고생은 하늘도 감동하실 것입니다. 제가 비록 어리석으나 아버님의 가르침을 듣고 옛글을 살펴 예의를 조금 알기에 의롭지 못한 일은 배우지 않았습니다. 소저께서는 저를 염려하지 마시고 한때의 고생을 참으시어 천금 같은 몸을 보중하시고, 제가 바라는 바를 버리지 마소서.\" 말을 마치고 비단 주머니를 열어 백옥 서진(書鎭)을 꺼내 소저께 전하며 말하였다. \"이 물건이 비록 귀중하지는 않으나 저희 집안에 대대로 전하는 물건입니다. 제가 금옥보다 더 소중히 여겨 한시도 손에서 놓지 않았는데, 오늘 소저와 이별을 당하니 간절함을 누를 길 없어 이것으로 신표를 삼고자 합니다. 원컨대 소저께서는 일편단심을 열어 다시 생각하시어 더럽다 마시고, 아끼시는 보배를 바꾸어 주시면 뒷날 서로 신표로 삼을까 하옵니다.\" [?]","sp":[]},{"c":1,"sub":"","t":"영춘이 받아서 소저께 전하니, 소저는 사양하는 것이 옳지 않아 받아 간수하였다. 그리고 순금 가락지를 빼어 한 짝을 생에게 전하며 말하였다. \"첩의 팔자가 기박하여 떠돌며 이리저리 흩어지는 운명이라 다만 죽기를 바랐는데, 오늘 군자의 두터운 뜻을 받으니 감사함을 이기지 못하겠습니다. 이것이 비록 하찮으나 어머님께서 영영 이별하시던 날 이것으로 모녀의 정을 표하신 것이라 한시도 손에서 놓은 적이 없습니다. 군자의 신물을 받고 달리 표할 것이 없어 가락지 한 짝으로 신표를 삼으니, 이로부터 풀잎의 이슬 같은 남은 목숨을 군자께 맡깁니다. 바라건대 첩의 들뜬 행동을 비루하다 하지 마소서.\" [?]","sp":[[0,2,"P","영춘"]]},{"c":1,"sub":"","t":"생이 기꺼이 받아 주머니에 간수하고 길이 사례하였다. \"소저의 은혜가 여기까지 미치니 제 복이 줄어들까 두렵습니다. 제가 비록 옛사람에게는 미치지 못하나 경박한 사람은 되지 않을 것이니, 조금도 염려하지 마시고 천금 같은 귀한 몸을 보중하시어 제 단심을 잊지 마소서. 요행히 과거에 급제하게 된다면 그것은 소저의 덕이요 저의 복입니다. 고향에 돌아가 부모님께 아뢰고 곧 혼례를 이룰 것이니, 소저께서는 한때의 곤고함을 괴롭다 마시고 귀한 몸을 보중하시어 탁주에 가서 머무르소서.\" 말을 마치고 영춘을 돌아보며 말하였다. \"너희의 충심을 아니 반드시 잘 보호하겠지만 다시 조심하여라.\" 또 설낭을 돌아보며 말하였다. \"믿는 바는 너희뿐이다. 가는 길에 한시도 방심하지 말고 소저를 보중하여 나의 부탁을 잊지 마라.\" 하고 신신당부하였다.","sp":[[276,278,"P","영춘"],[329,331,"P","설낭"]]},{"c":1,"sub":"","t":"이럭저럭 날이 늦자 생이 하는 수 없이 몸을 일으켜 소저에게 하직하며 몸 보중하기를 당부하였다. \"떠나기 아쉬우나 소저께서 불편하실 것을 헤아리는 것입니다.\" 하며 못내 아쉬워하다가 소매를 떨치고 천천히 나가니, 소저는 잠잠하였으나 영춘 등은 그 정대함을 감탄하였다. 생은 객점에 돌아와 행장을 꾸려 서울로 향하는데, 소저의 신세를 생각하니 무엇을 잃은 듯 허전하고 섭섭함을 누를 수 없어 스스로 시를 읊어 시름을 달랬다.","sp":[[130,132,"P","영춘"]]},{"c":1,"sub":"","t":"이때 장 소저는 김 공자와 이별하고 길을 떠나 멀고 험한 길을 걸어 여러 날 만에 탁주에 닿아 정 시랑의 집을 찾았다. 애석하게도 소저의 액운은 갈수록 심하였다. 시랑은 이미 세상을 떠났고 자손이 없어, 그 부인 소씨가 외로움을 견디지 못하여 가산을 팔아 가지고 외조카 유영을 찾아 양주로 갔다는 것이었다. 소저가 천신만고 끝에 이르렀다가 이 말을 들으니 바라던 것이 끊어지고 천지가 아득하여 정신을 잃었다가, 목 놓아 울며 말하였다. \"이 지경에 이르렀으니 내가 세상에 살아 무엇이 이롭겠는가. 차라리 어서 죽어 모든 일을 잊는 것만 못하구나.\" 말을 마치고 기절하여 인사불성이 되니, 설낭과 영춘이 급히 구하여 한참 뒤에야 겨우 정신을 차리고 숨을 쉬었다. 그러나 끝내 슬픔을 진정하지 못하여 말을 하지 못하고 다만 눈물만 흘렸다.","sp":[[3,7,"P","장설빙"],[9,13,"P","김희경"],[53,57,"P","정 시랑"],[119,121,"P","소씨"],[176,178,"P","도인"],[329,331,"P","설낭"],[333,335,"P","영춘"]]},{"c":1,"sub":"","t":"화살같이 빠르고 꿈과 같은 한세상에 근심 걱정과 괴로움 없는 사람이 어디 있으리오마는, 소저의 애처로운 모습은 차마 볼 수 없었다. 영춘 등이 위로하였다. \"소저께서는 너무 서러워 마소서. 예부터 홍안박명이요 고진감래라는 말이 있습니다. 우리가 지금은 고생이 이러하나 머지않아 대감께서 돌아오시고, 김 낭군도 뒷날을 기약하였으니 뜻을 이루면 오늘의 고생은 한바탕 봄꿈이 될 것입니다. 사람의 운수는 하늘이 정하시는 법이 있으니, 소저께서는 어찌 한때의 고생을 괴롭다 하시어 귀한 몸을 버리고 나중을 생각하지 않으십니까? 소비들이 막중한 부탁을 두 곳에서 받았사오니 천한 마음을 헤아리시어 너무 상심하지 마소서.\"","sp":[[74,76,"P","영춘"]]},{"c":1,"sub":"","t":"소저가 이 말에 겨우 정신을 차리고 길게 탄식하였다. \"네 말이 그러하나, 짐승도 길들여 사는 곳이 있어 전처럼 바람과 습기를 막는데 하물며 사람이 몸 둘 곳이 어찌 중하지 않겠느냐. 그런데 우리 고생은 갈수록 심해져 몸 붙일 곳이 없으니 누구에게 의탁하겠느냐. 일편단심에 온갖 시름을 싣고 광풍에 낙엽처럼 동서로 분주하며 구차히 머무르니, 차라리 세상을 모르는 것만 못하다. 그래도 세상에 남아 있는 것은 아버님의 얼굴을 다시 뵐까 바라서요, 또 김 공자와 굳게 약속한 뒷날을 생각해서이다. 장차 이를 어찌하리오. 외숙모님은 외조카를 찾아가셨다 하니 바로 남이나 다름없는 사람이라 바랄 바가 아니요, 갈 곳이 없으니 천만 가지로 헤아려도 불효와 신의 없음을 무릅쓰는 것만 같지 못하구나.\" [?]","sp":[[251,255,"P","김희경"]]},{"c":1,"sub":"","t":"영춘이 민망하여 말하였다. \"소저께서는 어찌 이런 말씀을 하십니까? 신의 없음과 의롭지 못함을 겸하고 죽으면 외로운 혼이 저승에 가서도 용납되지 못할 것입니다. 소비의 얕은 소견으로는 이제 형세가 그릇되었으니 작은 부끄러움을 버리고 김 낭군을 찾아가는 것이 제일 몸을 의지하는 길이요, 그러면서 대감께서 돌아오시기를 기다리면 이는 효와 신의를 둘 다 온전히 하는 것입니다. 원컨대 소저께서는 깊이 살피소서.\"","sp":[[0,2,"P","영춘"]]},{"c":1,"sub":"","t":"소저가 말하였다. \"네 말은 옳지 않다. 김 공자는 서울에 가서 돌아올 기약이 없으니, 알지 못하는 집에 누구를 찾아 의지하겠느냐. 또 서울로 가려 해도 이름이 조정에 걸린 바가 없으니 누가 찾겠느냐. 차라리 신의를 저버릴지언정 효를 지극히 하는 것이 사람이 어버이를 위하는 도리다. 내 이제 북해를 찾아가 아버님의 안부를 알고자 하니, 너희는 나를 위해 길을 인도하여라.\"","sp":[[23,27,"P","김희경"]]},{"c":1,"sub":"","t":"영춘이 눈물을 흘리며 말하였다. \"북해는 만 리 밖이요 큰 강이 가로막혀 있어 장부의 길이라도 오히려 어렵거늘, 하물며 규중의 약한 몸으로 어찌 다다를 수 있겠사옵니까. 또 북방은 변방이라 인심이 극악하니 사나운 자들의 욕을 당하면 어찌 막겠사옵니까. 애초에 가지 않느니만 못하옵니다. 소저께서는 외람된 뜻을 두지 마소서.\" 소저가 말하였다. \"옛날 목란은 절벽에서도 오히려 죽지 않았다. 이제 목란의 일을 본받아 옷을 바꾸어 입고 말 한 필에 몸을 실어 북해로 향하면, 누가 여자가 남자로 변한 줄 알겠느냐. 내 뜻을 이미 정하였으니 너희는 괴로이 막지 마라.\" 영춘 등이 이미 결정한 줄 알고 말하였다. \"소저께서 이렇게 고집하시니 하늘도 감동하실 것입니다. 소비들이 어찌 죽기로 뒤를 따르지 않겠사옵니까.\" 소저가 크게 기뻐하여 곧 머리 장식을 꺼내 팔아 영춘과 함께 남복으로 갈아입고, 말 한 필에 의지하여 북해로 향하였다. [?]","sp":[[0,2,"P","영춘"],[316,318,"P","영춘"],[426,428,"P","영춘"]]},{"c":1,"sub":"","t":"먼 길을 걷고 걸어 열 달 만에 겨우 다다르니, 기운이 다하고 정신이 흐릿한데 앞길은 아직 수십 리나 남았으나 걸을 길이 없었다. 세 사람이 겨우 마음을 진정하고 집을 빌려 잠깐 쉬며 두루 물어 찾았으나 아는 사람이 없었다. 낙망을 견디지 못하여 두루 [□]황하는데, 푸른 숲 향기로운 풀 가운데 한 노인이 청려장을 짚고 갈건에 도복 차림으로 풍경을 구경하고 있었다. 소저가 나아가 절하고 공손히 물었다. \"소생은 서울 사람인데 마침 장사하러 이 땅에 다니러 왔습니다. 오는 길에 들으니 서울의 이부상서 장자영이라는 재상이 지난해 봄 이곳에 귀양 오셨다 하기에 반가이 뵙고자 왔으나 종적을 알 길이 없습니다. 노인장께서 아시거든 밝히 가르쳐 주시기를 바라옵니다.\" [?]","sp":[[282,285,"P","장자영"]]},{"c":1,"sub":"","t":"그 노인이 한참 생각하다가 말하였다. \"그대는 승상 익주목 장원의 아들인가?\" 소저가 대답하였다. \"그렇습니다.\" 노인이 갑자기 낯빛을 바꾸며 \"애석하다.\" 하더니 시름이 일어 한참 동안 말을 하지 못하였다. 반나절이 지난 뒤에야 말하였다. \"저 시내를 건너 동쪽으로 몇 리를 들어가면 산수가 빼어나고 푸른 소나무와 대나무가 층층이 무성한 곳에 초당이 있으니, 거기 가서 찾으면 자연히 알 것이다. 그리로 찾아가라.\" 소저가 사례하고 길을 찾아갔으나 노인이 왜 슬퍼하는지는 알지 못하였다. 시내를 건너 몇 리를 가니 산이 수려하고 나무가 무성한 가운데 오색 채운이 소나무와 대숲에 잠겨 있고, 온갖 새와 짐승이 사람의 시름을 돋우었다.","sp":[[33,35,"P","장원"]]},{"c":1,"sub":"","t":"두루 살펴보니 대숲 깊은 곳 집 동편 벽 위에 현판이 걸려 있었다. 자세히 보니 그 현판에 이렇게 쓰여 있었다. \"청주 사람 이부상서 장자영은 하늘을 우러러 탄식하며 온갖 시름을 잠깐 기록하노라. 슬프다, 사람의 운명은 하늘에 달렸으니 한때 빌기도 어렵도다. 그러나 나 같은 인생이 또 어디 있으리오. 몸을 나라에 바친 뒤 하늘 같은 은혜가 넓으시어 벼슬이 육경에 이르도록 나라의 은혜가 망극하였으나 조금도 갚지 못하였다. 평생의 소원은 이 한 몸이 다하도록 충성을 다해 나라에 보답하는 것이었는데, 시운이 불행하고 액운이 지중하여 소인의 참소였던지 임금의 명이 지엄하시어 만 리 먼 변방으로 내치시니 원한이 끝이 없다. 남은 목숨을 부지하며 하늘의 명을 바랐더니 끝내 뜻을 이루지 못하니, 슬프다, 마디마디 간장이 봄눈 녹듯 다 녹는 줄 그 누가 알리오. 마음에 맺힌 바는 충성을 다한 뒤 장영의 이름을 만세에 전하는 것이 소원이었는데, 운명이 기박하고 시운이 불길하여 사면을 얻지 못하고 온갖 시름을 묻어 둔 채 타향의 외로운 혼이 되겠구나.","sp":[[75,78,"P","장자영"],[443,445,"P","장자영"]]},{"c":1,"sub":"","t":"슬프다, 이 남은 목숨을 그 누가 위로하리오. 골수에 맺힌 병은 편작이 다시 살아와도 고치기 어렵도다. 속절없이 북해의 외로운 혼이 된단 말인가. 죽은 뒤에 해골인들 누가 거두어 선산에 묻어 주리오. 애석하다, 핏줄 하나가 깊은 규중에 있어 북해를 바라보며 약한 간장을 녹이는 것을 밤낮으로 생각하면 죽기보다 더 서럽도다. 사면을 얻거든 고향에 돌아가 딸의 짝을 이루어 원앙이 노는 모습을 보고자 하였더니, 하늘이 무심하여 황천으로 돌아가니 혈혈단신 약한 몸이 어디에 의지하여 혼인을 어찌하며 조상의 제사를 누구에게 부탁하리오. 이리저리 생각해도 지하에 돌아가 눈을 어찌 감으리오. 아득한 푸른 하늘은 장차 이 장영이 죄 없이 원통하게 죽는 것을 살피시어, 풀잎 이슬 같은 혈육을 돌보아 가련한 목숨을 잇게 하시고, 다시 장씨의 성을 이어 불효와 외로운 혼을 면하게 하옵소서. 불효자 장영은 음흉하고 간사한 자의 참소를 만나, 우리 임금의 밝은 총명을 가리어 억울하게 먼 곳으로 귀양 와 죽으니, 밝고 밝은 하늘과 해와 달과 별은 굽어살피시어 구천에 돌아가서도 원한을 씻게 하옵소서.\" 그 아래에 \"모월 보름날 이부상서 장자영은 온갖 시름을 한 조각 현판에 기록하고 눈물로 오늘 목숨이 다하노라.\" 하였다. [?]","sp":[[342,344,"P","장자영"],[439,441,"P","장자영"],[571,574,"P","장자영"]]},{"c":1,"sub":"","t":"소저가 다 보고 나서 상서께서 세상을 떠나신 줄 알고 목 놓아 통곡하며 땅에 엎어져 기절하니, 설낭과 영춘도 하늘을 부르며 통곡하였다. 오호라, 산천초목이 다 슬퍼하는 듯 근심스러운 구름이 일어나고 새와 짐승이 다 서러워하니, 누가 능히 구하리오.","sp":[[53,55,"P","설낭"],[57,59,"P","영춘"]]},{"c":1,"sub":"","t":"형세가 매우 급하였는데, 하늘이 돕고 신령이 도우셨다. 그 노인이 소저를 가르쳐 보내고 생각하였다. '그 소년의 얼굴이 상서와 비슷하고, 묻는 말도 이러하니 참으로 이상하다. 상서께서 살아 계실 때 나에게 아들은 없고 다만 딸 하나뿐이라 하셨으니, 반드시 상서의 친척일 것이다. 만일 그곳에 가서 상서의 필적을 보면 반드시 편치 못할 것이니, 내가 몸소 가서 그 소년을 위로하리라.' 하고 급히 가 보니 산천은 적막하고 인적이 고요하였다. 매우 이상히 여겨 들어가 보니 세 사람이 서로 손을 잡고 땅에 쓰러져 있었다. 가까이 다가가 살펴보니 숨이 이미 끊어진 듯하였다. 노인이 크게 놀라 허둥지둥 마을로 내려가 약물을 구해 와서 그 소년에게 먹이고 또 두 사람에게 먹인 뒤 그 소년의 손을 주물렀다. 한참 뒤 한 사람이 먼저 정신을 차려 일어나 앉으니 바로 설낭이었다. 노인이 사정을 물었다. \"그대들은 무슨 일로 이 지경을 당하였는가? 어서 저 소년을 구하라.\"","sp":[[35,39,"P","이 소저"],[424,426,"P","설낭"]]},{"c":1,"sub":"","t":"설낭이 허둥지둥 일어나 살펴보니 소저와 영춘이 모두 혼절해 있었다. 목 놓아 통곡하며 어찌할 줄 모르고 소저의 손발을 주물러 구하니, 이윽고 영춘도 정신을 차렸다. 다행히 소저의 기운을 살피니 가슴속에 조금 온기가 있으므로 부르짖어 깨우니, 날은 이미 저물었다. 소저가 겨우 정신을 차려 보니 약볕(햇볕)에 의지하여 앉아 있으므로 이상히 여겼다. 마음속으로 저 노인의 구함을 입어 다시 살아난 줄 알고, 정신을 수습하여 몸을 일으켜 노인께 절하며 사례하였다. \"노인장의 가르치심을 입어 아버님이 남기신 글을 찾아 보았으니 그 은혜를 잊지 못하겠거늘, 또 어찌 저희가 기절한 것을 아시고 여기에 오시어 사람을 살리는 덕을 베푸셨습니까. 은혜가 백골난망이옵니다.\" [?]","sp":[[0,2,"P","설낭"],[22,24,"P","영춘"],[79,81,"P","영춘"]]},{"c":1,"sub":"","t":"노인이 길게 탄식하였다. \"이 또한 하늘의 뜻이니 어찌 이 늙은이가 구한 것이라 하겠는가. 그대가 장 상서의 아들이라 하니 상서를 다시 본 듯 반갑기 그지없다. 그러나 가련하구나. 만 리 먼 길을 천신만고 끝에 겨우 왔는데 이승과 저승이 달라 서로 반겨 볼 수 없으니 망극하겠지만, 천륜을 좇아왔으니 그 지극한 효성에 감격함을 헤아릴 수 없다. 상서는 나의 죽마고우라. 어려서부터 청주에서 함께 자라 관악에서 같이 공부하고 함께 과거에 올랐으니, 비록 결의는 없었으나 관중과 포숙 같은 정을 나누었다. 내가 이곳에 와 머문 지 오래되어 서로 소식이 끊어지니 늘 그리워하였는데, 뜻밖에 상서가 소인의 참소로 여기에 이르러 옛 정을 펴고 서로 위로하며 지냈다. 그런데 상서가 불행히 우연히 병을 얻어 온갖 약이 효험 없이 끝내 일어나지 못하니, 그 슬픔을 어찌 다 적으리오. 이 늙은이가 상주가 되어 터를 잡아 장사 지내고 마을 사람들에게 일러 집을 세우고 임종 때 하던 말을 현판에 적어 두었다. 천만뜻밖에 그대가 이곳에 왔으니 상서의 영혼이 기뻐할 것이요, 슬픈 가운데 다행이다. 그런데 상서는 살아 있을 때 아들이 없음을 슬퍼하고 다만 딸을 근심하여 그 마음을 현판에 적었다. 상서는 본래 어진 군자라 나를 속였을 리 없으니 참으로 이 늙은이의 의혹이 그치지 않는구나. 아마 그대가 지금 옷을 바꾸어 입고 세상을 속이는 것이 아닌가?\" [?]","sp":[[55,59,"P","장자영"],[110,112,"P","도인"]]},{"c":1,"sub":"","t":"소저가 이 말을 듣고 넋이 나간 듯 머리를 숙이고 말을 하지 못하다가 마음속으로 생각하였다. '저 노인은 아버님의 벗이라 은인일 뿐 아니라 또 나의 기미를 환히 알고 있다. 끝내 숨기다가 나중에 막지 못하면 후회해도 소용없다. 이제 사실을 아뢰고 누설하지 말라고 당부하리라.' 하고 다시 일어나 절하며 말하였다. \"대인께서 돌아가신 아버님의 벗이시라 하니 아버님을 뵌 듯 슬픔이 그지없습니다. 어찌 마음을 숨기겠사옵니까. 소녀는 바로 상서의 외딸입니다. 일찍 어머님을 여의고 아버님을 모시고 세월을 보내던 중, 불행히 아버님이 이곳으로 귀양 오시니 오직 그 뒤를 따르고자 하였으나 뜻을 이루지 못하였습니다. 혈혈단신으로 유모와 시비와 함께 서로 마음을 나누다가 사나운 자들의 욕을 두려워하여 외람된 생각을 내어 여자가 남자로 꾸며 남녀를 가리고, 이리저리 먼 길을 걸어 이곳에 이르렀습니다. 그런데 소녀의 죄악이 극심하여 적막한 산천에 한 조각 필적뿐이요, 아버님의 모습은 구천에 막혀 버렸으니 망극합니다. 온 세상에 소녀뿐이라 아버님 시신을 선산으로 옮겨 모시고자 하오나 맨손뿐인 홑몸이라 할 수가 없사오니, 바라건대 대인께서 옛 정을 생각하시어 다시 돌보아 주신다면 아버님의 외로운 혼을 고향 땅에 편히 모실 수 있을 것입니다. 그러면 백골의 영혼이 감격하실 것이요, 소녀 또한 뼈에 새기고 마음에 새겨 이 은혜를 만분의 일이나마 갚을까 바라옵니다.\" 말을 마치자 목메어 우니 흐르는 눈물이 피가 되었다.","sp":[[347,349,"P","설낭"]]},{"c":1,"sub":"","t":"노인이 이 말을 듣고 더욱 슬퍼 지극히 위로하였다. \"소저는 너무 슬퍼하지 마오. 이는 다 하늘의 운수라 어찌 면하겠소. 이 늙은이가 비록 가난하나 소저의 소원을 따르겠소.\" 소저가 이에 눈물을 거두고 절하며 사례하였다. \"대인의 큰 덕이 이같이 거룩하시니 천만세토록 축원하겠사옵니다. 그러면 돌아가신 아버님의 빈소로 이끌어 주소서.\" 노인이 마지못하여 소저를 데리고 몇 리를 가더니 무덤 하나를 가리켰다. 눈을 들어 보니 푸른 숲 속에 비석을 세웠는데 '청주인 승상 장공의 묘'라 뚜렷이 서 있었다. 소저가 무덤을 붙들고 애통하게 우니 풀과 나무, 새와 짐승도 슬퍼할 만하였다. 그러다 정신을 잃으니 영춘 등이 구하여 겨우 진정하였으나, 애통함을 참지 못하여 통곡을 그치지 않았다. 노인이 나아가 위로하였다. \"소저는 어찌 이렇게 몸을 버리려 하오? 이 늙은이가 참으로 마음이 편치 않소. 청컨대 슬픔을 참고 시신을 고향으로 모셔 갈 계책을 생각하오.\"","sp":[[262,264,"P","장자영"],[337,339,"P","영춘"],[363,365,"P","소세필"]]},{"c":1,"sub":"","t":"소저가 노인을 위하여 억지로 참았으나 태연한 빛이 없었다. 노인이 갖은 말로 달래며 날이 저물었으니 슬픔을 거두고 집으로 돌아가자고 청하니, 소저가 마지못하여 노인을 따라가며 백 번 당부하였다. \"대인께서는 소녀의 행색을 누설하지 마소서. 만일 다른 사람이 알면 일이 그릇될 뿐 아니라 소녀가 고향에 돌아가지 못할 것이옵니다. 그러므로 애걸하옵니다.\" 노인이 태연히 대답하였다. \"소저가 말하지 않아도 이 늙은이가 이미 짐작하였으니 어찌 이런 큰일을 누설하겠소.\" 소저가 사례하고 돌아오니, 노인이 별당을 깨끗이 치워 소저를 편히 머물게 하고 저녁을 권하였다. 식사를 마친 뒤 밤 깊도록 이야기를 나누었으나 소저는 끝내 슬픔을 얼굴에 드러내지 않았으니, 그 신중함이 이러하였다.","sp":[]},{"c":1,"sub":"","t":"이튿날 노인이 장례 기구를 차리면서 태수께 들어가 장 승상의 친척이 왔다는 말을 전하였다. \"그가 다만 바라는 것은 상서의 시신을 옮겨 모시는 것인데, 맨손에 빈주먹이라 장례 비용을 조금이나마 돌보아 주시기를 청하더이다.\" 상서는 본래 태수의 은인이었다. 태수가 이 소식을 듣고 곧 나와 조문하고, 한편으로 상여를 차리며 군사 사십 명을 정하여 영구를 청주로 모시게 하였다. 소저는 감사함을 이기지 못하여 은혜에 사례하고 상구를 모시고 길을 떠났다. 노인이 십 리 밖까지 나와 전별하며 조심하라 당부하고, 상구를 붙들고 통곡하며 이별하는 정을 못내 슬퍼하였다. 소저도 눈물을 뿌리며 만세토록 태평하시라 인사하고 하직한 뒤, 영구를 모시고 밤낮으로 가서 선산에 돌아와 안장하였다. 묘 곁에 여막을 짓고 설낭, 영춘과 함께 서로 위로하며 세월을 보내는데, 슬픔 속에 몸이 여위어 얼굴이 초췌하고 기운이 쇠약하니, 보는 사람마다 슬퍼하지 않는 이가 없었다.","sp":[[20,22,"P","북해 태수"],[132,134,"P","북해 태수"],[143,145,"P","북해 태수"],[392,394,"P","설낭"],[396,398,"P","영춘"]]},{"c":1,"sub":"","t":"세월이 물 흐르듯 하여 삼년상을 마치니, 소저는 상복을 벗으며 새로이 슬퍼하였다. 하루는 설낭, 영춘과 앞길을 의논하는데 영춘이 말하였다. \"이제 삼 년을 지냈으니 묘 아래를 떠나야 할 터인데 어디로 가시겠습니까?\" 소저가 울며 말하였다. \"이제 아버님 유골을 선산에 안장하고 삼 년을 지냈으니 지금 죽은들 무슨 한이 있겠느냐. 차라리 자결하여 혼백이라도 부모님 뒤를 따르고자 한다.\"","sp":[[50,52,"P","설낭"],[54,56,"P","영춘"],[68,70,"P","영춘"]]},{"c":1,"sub":"","t":"영춘이 크게 놀라 말하였다. \"소저께서는 어찌 이런 말씀을 하십니까? 이제 부모님의 몸을 한곳에 모셨으니 천금 같은 몸을 보존하여 제사를 받드는 것이 지극한 효도이거늘, 까닭 없이 죽어 후사를 끊으려 하시니 어찌 불효가 아니겠사옵니까?\" 소저가 울며 말하였다. \"내 어찌 이런 줄 모르겠느냐마는 의지할 곳이 없으니 형세가 어쩔 수 없는 것인데, 너희가 어찌 말리겠느냐.\" 영춘이 울며 대답하였다. \"소저께서는 어찌 그사이 형주 객점에서 한 언약을 잊으셨습니까?\" 소저가 태연히 대답하였다. \"어찌 한시라도 잊겠느냐마는 오랜 세월에 사람의 일이 변하였을 것이기 때문이다.\" 영춘이 말하였다. \"소저께서는 어찌 가볍게 생각하십니까? 김 공자의 은정을 생각하면 태산도 가벼울 것입니다. 생각건대 그사이 여러 해가 되었으니 반드시 과거에 급제하여 높은 벼슬에 올랐을 것이요, 소저를 그리는 정이 자못 깊을 것입니다. 이때를 타서 인연을 맺어 부귀를 누리고 후사를 이으면 또한 경사가 아니겠사옵니까?\" 소저가 이에 옳다고 여겨 행장을 차리고 묘 아래에 나아가 통곡하며 하직하니, 그 슬피 목메어 우는 모습을 차마 볼 수 없었다.","sp":[[0,2,"P","영춘"],[208,210,"P","영춘"],[320,322,"P","영춘"],[352,356,"P","김희경"]]},{"c":1,"sub":"","t":"날이 늦어서야 묘 아래를 떠나 하람으로 향하였다. 멀고 험한 길을 걸어 여러 날 만에 다다라 한 집을 빌려 쉬며 영춘을 보내 김 공자의 소식을 알아보게 하였다. 이윽고 영춘이 돌아와 울며 말하였다. \"우리 세 사람은 무슨 죄로 고생도 끝이 없고 근심도 끝이 없는고. 소저께서는 이제 어디로 가시겠습니까?\" 소저가 크게 놀라 까닭을 물으니 영춘이 울며 말하였다. \"두루 다니며 김 공자의 거처를 물으니 몇 해 전에 집을 옮겨 영천으로 갔다 합니다. 영천은 남방의 변방이라 북해 가기나 다름이 없사오니, 박명한 인생이 고향을 생각하니 자연히 슬프옵니다.\" 소저가 이 말을 듣고 어이가 없어 아무 말도 못하고 눈물만 흘렸다.","sp":[[63,65,"P","영춘"],[70,74,"P","김희경"],[94,96,"P","영춘"],[189,191,"P","영춘"],[210,214,"P","김희경"]]},{"c":1,"sub":"","t":"두 사람이 서로 위로하였다. \"일이 이미 그릇되었으나 한갓 근심만 하는 것은 소용없습니다. 이미 뜻을 정하여 하늘이 정한 인연을 찾으려면 영천인들 어찌 마다하겠습니까. 천하를 다 돌아도 찾지 못한다면 그만이지만, 지금 찾지 않는 것은 옳지 않습니다.\" 소저와 영춘도 그렇게 여겨 곧 하람을 떠나 영천으로 향하였다. 백여 일 만에 겨우 그 땅에 이르렀으나 사는 곳을 알지 못하였다. 세 사람이 흩어져 날이 다하도록 찾았으나 알 수 없어, 하는 수 없이 한 집을 빌려 밤을 지내고 여러 날 머물며 널리 물었으나 끝내 종적이 없었다. 낙망하기 그지없어 울며 말하였다. \"슬프고 슬프다. 해는 서산에 지는데 발은 부르트고 피곤하며 배고프고 목마름이 심하구나.\"","sp":[[145,147,"P","영춘"]]},{"c":1,"sub":"","t":"주점을 찾아 밥을 얻어먹고자 세 사람이 서로 손을 잡고 한 걸음 한 걸음 걸으며 시냇물도 떠 마시고 주점을 찾아가다가, 배고픔이 심하여 바위 위에 앉아 쉬었다. 소저가 눈을 들어 보니 북쪽으로 큰 강이 가로놓였고 강 위에 고깃배가 오가고 있었다. 영춘에게 말하였다. \"저 강변에 인가가 있는 듯하니 거기를 찾아가 양식도 빌고 김 공자의 종적도 알아보자.\" 세 사람이 함께 강변을 찾아가니 인가는 없고 다만 고깃배뿐이었다. 영춘이 망극하여 말하였다. \"이곳에 인가가 없으니 작은 길을 찾아 시골 마을에 가서 밥을 빌어먹고 내일 다시 찾아보사이다.\" 소저가 태연히 말하였다. \"몸이 고단하니 잠깐 쉬어 가자.\" 하고 강변 바위 밑에 앉으니 설낭과 영춘도 함께 쉬었다.","sp":[[138,140,"P","영춘"],[182,186,"P","김희경"],[236,238,"P","영춘"],[356,358,"P","설낭"],[360,362,"P","영춘"]]},{"c":1,"sub":"","t":"그러다 소저가 갑자기 소매에서 붓주머니를 꺼내 바위 위에 썼다. \"청주 사람 장 소저 설빙은 병진년 가을 칠월 보름에 불효와 신의 없음을 무릅쓰고 이 물에 빠져 죽노라. 천지일월과 후토의 신령은 불쌍히 여기소서.\" 쓰기를 마치고 비단 치마로 낯을 가리며 강에 뛰어드니, 슬프다, 장 소저가 푸른 물 넓은 강에 깊이 들어갔으니 강이 변하여 뭍이 되기 전에는 소저 설빙이 다시 오지 못할 것이다. 아깝고 아깝도다. 고금에 드문 인물이 바람에 꺾인 나무와 뜬 풀처럼 세상을 버렸으니, 소저의 처지를 그 누가 슬퍼하지 않겠는가. 함께 고생하던 설낭과 영춘이 발을 구르며 통곡하였으나, 푸른 물결에 잠긴 혼이 무엇을 알겠는가. 영춘이 구하지 못할 줄 알고 다시 만나기 아득하므로 부르짖어 통곡하였다. \"소저를 모신 지 거의 십여 년에 한시도 떠난 적이 없었는데, 오늘 소비들을 저버리고 혼자 어디로 가시나이까. 내 이제 홀로 살아 무엇 하리오.\" 하고 물에 뛰어들려 하였다. [?]","sp":[[43,47,"P","장설빙"],[48,50,"P","장설빙"],[156,160,"P","장설빙"],[202,204,"P","장설빙"],[300,302,"P","설낭"],[304,306,"P","영춘"],[346,348,"P","영춘"]]},{"c":1,"sub":"","t":"설낭도 통곡하며 말하였다. \"우리 세 사람이 천하를 다 돌더라도 김 공자를 찾아 소저의 평생을 건지고 다시 좋은 날을 볼까 하여 마음과 힘을 다해 다니다가, 이곳에 와서 주인을 구하지 못하였으니 무슨 면목으로 세상에 남겠는가. 차라리 함께 죽어 혼백이라도 서로 떠나지 않으리라.\" 하고 말을 마치자 붓을 들어 소저가 쓴 글 아래에 썼다. \"같은 달 같은 날에 유모 설낭과 시비 영춘은 주인을 따라 함께 이 물에 빠지노니, 해와 달과 별은 깊이 살피소서.\" 쓰기를 마치자 두 사람이 서로 손을 잡고 한꺼번에 물에 빠지니, 가련하다, 세 사람의 남은 목숨이 한꺼번에 사라지니 푸른 하늘이 어찌 무심하겠는가.","sp":[[0,2,"P","설낭"],[36,40,"P","김희경"],[201,203,"P","설낭"],[204,206,"P","설낭"],[211,213,"P","영춘"]]},{"c":1,"sub":"","t":"이때 여남 땅에 사는 이영찬이라는 사람이 있었는데, 벼슬이 참지정사에 이르렀다. 나이 칠십에 강산 풍경을 구경하고 돌아와 고기잡이 늙은이가 되어 낚시를 일삼아 세월을 보내고 있었다. 마침 맑은 날을 맞아 종자 몇 사람을 데리고 작은 배에 그물을 치고 긴 강 한가운데 떠서 옥피리를 불고 있었다. 이때는 마침 단풍철이라 가을 물에 잠긴 푸른 소나무와 대나무가 산천을 둘렀고, 흰 갈매기는 훨훨 날아 오갔다. 참정이 취흥에 겨워 뱃전을 두드리며 어부사 한 곡을 부르며 때를 보내고 있었다.","sp":[[12,15,"P","이영찬"],[33,35,"P","소세필"],[227,229,"P","이영찬"]]},{"c":1,"sub":"","t":"그런데 갑자기 물 위에 푸른 것이 떠오며 근심스러운 구름이 사방에 둘러 끼므로, 매우 이상히 여겨 바라보았다. 뱃머리에 닿자 자세히 보니 바로 사람의 시신이었다. 참정이 크게 놀라 종자를 급히 불러 건지게 하여 배에 올려 보니 숨이 끊어진 지 오래였다. 참정이 이미 구하지 못할 줄 알고 슬픔을 이기지 못하여 적삼을 벗어 옥 같은 얼굴을 가리고 손을 거두어 가슴에 얹었다. 그러다 자세히 보니 손목에 맨 것이 있고 향내가 자욱하였다. 이상히 여겨 살펴보니 푸른 비단 같은 것으로 병의 목을 매었고 붉은 글자로 '환혼주(還魂珠)'라 쓰여 있었다. 급히 풀어 봉한 것을 열고 약물을 입에 흘려 넣은 뒤 손발을 주물렀다.","sp":[[91,93,"P","이영찬"],[142,144,"P","이영찬"]]},{"c":1,"sub":"","t":"이윽고 숨을 내쉬며 몸을 뒤척이므로 참정이 크게 기뻐하여 정신 차리기를 기다렸다. 그런데 문득 또 보니 두 사람의 시신이 푸른 물결을 따라 배에 닿았다. 참정이 또 놀라 급히 건져 배에 올린 뒤 살펴보니 가슴에 조금 온기가 있었다. 한편 놀랍고 다행하여 약물을 먹이려고 그 병을 찾으니 간 곳이 없었다. 크게 이상히 여겨 말하였다. \"이는 반드시 용왕의 조화로다. 어찌 기특하지 않으리오.\" 하며 못내 탄복하고, 마침내 자기 환약을 꺼내 물에 타서 두 사람에게 먹이고 종자를 시켜 손발을 주물러 깨우니, 둘이 정신을 차렸으나 소저를 생각하고 흐느낌을 그치지 않았다.","sp":[[20,22,"P","이영찬"],[86,88,"P","이영찬"]]},{"c":1,"sub":"","t":"소저가 기운이 희미하여 누워 있는데, 쌍상투를 튼 한 여동(女童)이 나와 말하였다. \"부인은 이제야 고생과 액운이 다하였으니 근심하지 마시고 귀한 몸을 보중하소서. 저는 남해 용궁의 시녀이온데, 오늘 부인의 목숨이 위급하므로 왕명을 받들어 환혼주를 구료선(救療仙)께 가서 얻어 와 부인을 구하고 돌아가나이다.\" 하며 소매에서 대추 같은 것을 꺼내 주며 말하였다. \"지금 부인의 정신이 맑지 못하시니 이것을 먹으면 정신이 씩씩해질 것입니다.\" 하고 곁에 놓인 병을 가지고 표연히 구름에 싸여 가니 그 종적을 알 수 없었다. 소저가 그 선약을 먹으니 기운이 맑아져 조금도 흐릿함이 없었다. 비로소 눈을 들어 살펴보니 집이 아니요 배 안의 사람들이 분주하였다. 마음속으로 생각하기를 '반드시 저 노인의 구함을 입어 살아났구나.' 하고, 유모와 영춘을 생각하며 슬퍼 눈물을 금치 못하였다. [?]","sp":[[30,32,"P","용궁 시녀"],[409,411,"P","설낭"],[413,415,"P","영춘"]]},{"c":1,"sub":"","t":"참정이 태연히 물었다. \"그대는 어떤 사람이기에 청춘 소년으로 세상을 싫어하여 강물에 들어 굴원의 자취를 따르려 하였는가?\" 소저가 급히 일어나 사례하고 태연히 대답하였다. \"소생은 남방 사람으로 굳이 세상을 싫어한 것이 아니오라, 스스로 액운을 피하지 못하여 이 지경에 이르렀는데, 뜻밖에 대인의 살리시는 덕을 입어 남은 목숨을 보존하였으니 다시 살려 주신 은혜가 망극하옵니다.\" 노인이 웃으며 말하였다. \"이 또한 하늘의 뜻이니 어찌 이 늙은이의 덕이라 하겠는가.\" 소저는 다만 사례할 뿐이었다.","sp":[[0,2,"P","이영찬"]]},{"c":1,"sub":"","t":"설낭과 영춘 등은 소저가 살아난 것을 보고 못내 기뻐 반가움을 이기지 못하여 서로 붙들고 소리 내어 우니, 세 사람의 울음소리가 하늘에 사무쳐 강물도 목메고 떠가는 구름도 참담하여 참으로 쇠와 돌 같은 간장이라도 녹지 않을 수 없었다. 참정이 이로써 평범한 사람이 아님을 알고 또한 슬퍼하며 위로하였다. 반갑게 차를 권하여 안정시킨 뒤 자세히 보니, 얼굴은 단장하지 않았으나 백옥을 다듬은 듯하고, 두 눈썹 사이는 맑은 샛별이 동쪽에 솟는 듯하며, 귀밑에는 푸른 구름 같은 머리가 엉기었고, 붉은 입술과 흰 이가 반쯤 드러났다. 가는 버들 같은 허리에 봄바람 같은 기상이 늠름하여 참으로 태임의 덕을 겸하였으니, 단산의 봉황이라 티끌 하나 없었다. 어찌 인간 사람에게 비기겠는가. 참정이 길이 감탄하며 말하였다. \"그대의 자색이여! 무슨 일로 옥경을 하직하고 인간에 내려와 영욕을 겪다가 푸른 물결에 빠져 물고기 밥이 되려 하였는가? 무슨 까닭인지 묻노니, 사는 곳은 어디며 이름은 무엇이며 부친의 존함은 누구라 하는가?\"","sp":[[0,2,"P","설낭"],[4,6,"P","영춘"],[132,134,"P","이영찬"],[381,383,"P","이영찬"]]},{"c":1,"sub":"","t":"소저가 슬픔을 참고 얼굴빛을 태연히 하여 공손히 대답하였다. \"소자는 전 이부상서 장자영의 아들이요 이름은 수정이라 하옵니다.\" 참정이 크게 놀라 말하였다. \"그렇다면 승상 익주후 장원의 직계 손자인가?\" 소저가 놀라 말하였다. \"과연 그러하옵니다. 대인께서 어찌 아시옵니까?\" 참정이 탄식하였다. \"애석하다. 내가 장후(장자영)와 죽마고우로 정이 각별하였는데, 내가 벼슬에 뜻이 없어 조정을 하직하고 고향에 돌아와 산림에 묻힌 뒤로 서로 소식이 끊어진 지 이미 십여 년이라. 늘 생각하였으나 만날 길이 없어 탄식하였더니, 오늘 그대를 보니 장후를 대한 듯 반가움을 헤아릴 수 없구나. 그런데 그대는 무슨 까닭으로 이 지경을 당하였으며, 장후께서는 안녕하신가?\"","sp":[[46,49,"P","장자영"],[60,62,"P","장설빙"],[72,74,"P","이영찬"],[94,100,"P","장원"],[101,103,"P","장원"],[156,158,"P","이영찬"],[177,179,"P","장자영"],[180,183,"P","장자영"],[303,305,"P","장자영"],[357,359,"P","장자영"]]},{"c":1,"sub":"","t":"소저가 눈물을 머금고 말을 못하다가 겨우 대답하였다. \"집안 운수가 불행하여 몇 해 전 아버님께서 소인의 참소를 입어 북해로 귀양 가셨는데, 반년 만에 귀양지에서 세상을 떠나셨습니다. 소자가 겨우 시신을 옮겨 선산에 안장하고 삼 년을 지낸 뒤, 의지할 곳이 없어 두 노복을 데리고 푸른 하늘의 뜬구름처럼 정처 없이 다니다가, 영주 땅에서 행장을 모두 잃고 어찌할 수 없어 주인과 종 세 사람이 물에 빠졌습니다. 어찌 살기를 바랐겠사옵니까. 푸른 물결의 외로운 혼이 될 것을 대인의 하해 같은 덕을 입어 다시 살아났으니, 은혜가 망극하여 백골난망이옵니다.\" 참정이 다 듣고 서글피 탄식하였다. \"그사이에 세상일이 이렇게 변할 줄 어찌 알았으리오. 그대는 이제 어디로 가려 하는가?\" 소저가 울며 대답하였다. \"대인께서 아버님의 옛 벗이시라 하니 아버님을 뵌 듯 반갑사옵니다. 소생이 향할 곳은 광풍의 낙엽 같고 긴 강에 뜬 낙엽 같으니 방향이 없사옵니다.\" 하며 눈물을 흘리고 슬픔을 이기지 못하였다.","sp":[[311,313,"P","이영찬"]]},{"c":1,"sub":"","t":"참정도 슬픔을 금치 못하여 눈물을 흘리며 위로하였다. \"그대 말과 같다면 이 늙은이도 외로운 몸이라. 내 집이 가난하나 그대의 외로움은 면할 터이니 조금도 염려 말고 이 늙은이의 집에 가서 편히 지내며 학업에 힘써 공명을 이루고, 때를 기다려 조상을 영화롭게 하면 그 또한 이 늙은이의 바람이다. 길이 생각하여 두터운 정을 저버리지 마라.\" 소저가 일어나 사례하였다. \"대인의 말씀이 이러하시니 소자가 뼈에 새기고 마음에 새겨 후세까지 축원하겠사옵니다. 거처 없는 인생을 거두어 주려 하시니 어찌 사양하겠사옵니까. 이 천한 아이가 배운 바 없이 자라 사람됨이 용렬하오니, 높으신 가문에 의지하여 그 덕을 더럽힐까 두렵습니다. 존공께서 더럽다 아니하시면 개와 말 같은 수고를 사양하지 않겠사옵니다.\" 참정이 크게 기뻐하여 곧 배를 돌려 언덕에 매고 강변에 내려 집으로 돌아왔다. 후원 깊은 곳에 별당을 깨끗이 치워 장생을 편히 머물게 하고, 안채에 들어가 부인께 장생을 데려온 이야기를 하며 장생의 사람됨을 못내 칭찬하였다.","sp":[[0,2,"P","이영찬"],[391,393,"P","이영찬"],[455,457,"P","장설빙"],[482,484,"P","장설빙"],[498,500,"P","장설빙"]]},{"c":1,"sub":"","t":"이때 소저는 다행히 집을 얻어 설낭, 영춘과 함께 후원에 머물렀다. 참정은 그 뒤로 날마다 장생과 옛글을 의논하였는데, 장생의 대답이 막힘이 없어 말마다 푸른 하늘을 헤치고 큰 바다를 건너는 듯하였고, 제왕의 흥망과 영웅의 득실을 환히 꿰뚫었다. 참정이 칭찬하였다. \"그대는 참으로 고금의 명사요 당세의 영웅이로다. 이 늙은이가 늘그막에 조용한 서생을 얻어 어두운 가슴을 열게 되었구나.\" 장생이 사례하였다. \"대인께서 소자를 이렇게 사랑하시니 황공함을 이기지 못하겠사옵니다.\" 참정이 갈수록 기뻐하여 술과 안주를 내오며 종일토록 이야기하다가 밤이 깊은 뒤에야 파하였다.","sp":[[17,19,"P","설낭"],[21,23,"P","영춘"],[38,40,"P","이영찬"],[51,53,"P","장설빙"],[67,69,"P","장설빙"],[138,140,"P","이영찬"],[218,220,"P","장설빙"],[268,270,"P","이영찬"]]},{"c":1,"sub":"","t":"이후로 소저는 책을 대하여 글에 힘쓰고 시와 부를 지으며 날을 보냈다. 세월이 흘러 삼 년이 지났다. 참정의 은근한 정과 위아래 노소의 공경이 태산 같아서, 소저는 죽음으로 은혜를 갚고자 하나 그리하지 못할까 걱정하였다. 하루는 참정이 나와 이야기하며 술을 내어 즐기고 시를 지어 화답하였다. 술이 반쯤 취하자 장생의 시를 읊으며 감탄하였다. \"시재는 청련(이태백)을 이끌고 풍채는 두목지를 닮았으니, 그대는 참으로 빼어난 재사로다. 장후가 비록 죽었으나 외로운 혼인들 즐겁지 않겠는가.\" 손을 잡고 등을 어루만지며 말하였다. \"내가 만일 그대 같은 아들을 두었다면 지금 죽더라도 무슨 한이 있겠는가.\" 하고 감탄해 마지않으니 소저는 그 은덕에 감사하였다. [?]","sp":[[57,59,"P","이영찬"],[128,130,"P","이영찬"],[174,176,"P","장설빙"],[243,245,"P","장자영"]]},{"c":1,"sub":"","t":"이미 한 해가 지났으나 참정의 후대가 한결같으니 소저는 마음속으로 감격을 이기지 못하여 다만 사례하였다. \"대인께서 이렇게 돌보아 주시니 소자의 복이 줄어들까 두렵사옵니다.\" 참정이 기꺼이 웃으며 말하였다. \"이 늙은이 집에 머문 지 거의 여러 해라 서로 속마음을 비추었으니 어찌 사정을 숨기겠는가. 이 늙은이가 올해 일흔인데 죄악이 지중하여 아들 하나 없고 다만 딸 하나를 두었네. 얼굴과 행실이 옛사람에는 미치지 못하나 군자의 수건과 빗을 받들 만은 하다네. 봉황이 노니는 모습을 보고자 하였으나 끝내 뜻대로 되지 못하여 늘 원통하였는데, 하늘이 살피시어 영웅을 가르쳐 주셨으니 이제 그대를 버리고 누구를 택하겠는가. 바라건대 깊이 생각하여 이 늙은이의 간절한 정을 저버리지 말게. 또 그대는 양친이 다 돌아가시고 한 몸이 외로운데 후사가 늦어 가니 인륜에 어찌 무심하겠는가. 청컨대 쾌히 허락하여 부모의 제사를 받들고 외로운 몸을 위로하게.\"","sp":[[13,15,"P","이영찬"],[98,100,"P","이영찬"]]},{"c":1,"sub":"","t":"소저가 이 말을 듣자 정신이 아득하고 기운이 막혀 대답하지 못하다가, 한참 생각한 끝에 말하였다. \"소자가 부모님 살아 계실 때 공명을 이루기 전에는 장가들지 않겠다고 맹세하였으니 천지신명이 이미 아는 바입니다. 이러하므로 감히 대인의 분부를 받들지 못하오니 황공하기 그지없사옵니다.\" 참정이 이 말을 듣고 잠잠하다가 기꺼이 대답하였다. \"그렇다면 또한 쉽도다. 그대의 급제는 손안에 있으니, 이 늙은이의 뜻을 따른다면 아직은 혼약만 하고 뜻을 이룬 뒤에 혼례를 올리는 것이 어떠한가?\" 소저가 민망하여 낯빛을 고치고 말하였다. \"분부가 마땅하오나 그 또한 마음을 속이는 것입니다. 납채를 하면 서로 부부이니 어찌 혼례가 아니라 하겠사옵니까.\" 말씀이 엄정하고 예의가 바르니 참정이 매우 옳게 여겨 칭찬하였다. \"이 늙은이가 억지로 청한 것은 그대의 공명을 재촉하려는 뜻이었는데, 사정이 그러하면 억지로 권하지 못하겠네. 다만 급제한 뒤에는 이 늙은이의 뜻을 어기지 말게.\" 소저가 일어나 두 번 절하며 말하였다. \"분부대로 받들어 행하겠사옵니다.\" 참정이 더욱 기뻐하였다.","sp":[[160,162,"P","이영찬"],[378,380,"P","이영찬"],[532,534,"P","이영찬"]]},{"c":1,"sub":"","t":"세월이 빨라 겨울이 다하고 봄이 오자, 황상이 인재를 뽑아 쓰고자 과거를 연다는 조서를 반포하였다. 참정이 과거 소식을 듣고 장생을 불러 말하였다. \"과거 소식이 분명하니 그대가 뜻을 이룰 때로다. 그대는 이때를 놓치지 말고 급제하여 높은 벼슬에 올라, 낙양의 봄바람에 비단옷을 날리며 성은을 축수하고 조상을 빛내며, 나와의 약속을 잊지 말게.\" 소저가 절하며 말하였다. \"과거가 닥쳤으니 분부를 받들어 어서 떠나겠사옵니다.\" 참정이 곧 노자를 갖추고 푸른 나귀 한 필과 행장을 차려 주니, 소저가 하직하고 나귀에 오르매 봄바람 같은 기상이 보름달이 솟는 듯하였다.","sp":[[22,24,"P","황제"],[56,58,"P","이영찬"],[70,72,"P","장설빙"],[239,241,"P","이영찬"]]},{"c":1,"sub":"","t":"한편, 김생은 장 소저와 한번 이별한 뒤 그리운 정을 이기지 못하였다. 봄바람에 꽃비 내리고 달밤에 두견이 우는 초당에 외로이 누워 소저의 혈혈단신 외로운 신세를 생각하며, 때때로 금가락지를 꺼내 보고 긴 한숨으로 지냈다. 하루는 평장이 생을 불러 봄바람과 꽃과 달을 두고 시를 지으라 하였는데, 생의 얼굴에 근심이 가득한 것을 보고 말하였다. \"너는 무슨 까닭으로 울적한 시름을 품고 있느냐?\" 생이 숨기지 못하여 장 소저의 앞뒤 사연을 아뢰고 말하였다. \"이제 종적을 찾아 혼례를 올리고자 하옵니다.\" 평장이 웃으며 말하였다. \"정말 그렇다면 까마귀와 까치는 봉황을 따르지 않고 기린은 소와 양을 따르지 않는 법이니, 거처를 찾아 어서 예물을 보내면 될 것을 무엇이 어렵겠느냐. 너는 염려 마라.\"","sp":[[4,6,"P","김희경"],[8,12,"P","장설빙"],[129,131,"P","김평"],[233,237,"P","장설빙"],[283,285,"P","김평"]]},{"c":1,"sub":"","t":"생이 크게 기뻐하여 행장을 꾸려 탁주의 정씨 집을 찾아가니, 문 앞이 적막하고 담장이 허물어져 인적이 없었다. 생이 이상히 여겨 이웃 사람에게 물으니 모두 말하였다. \"정 시랑은 세상을 떠나시고 그 부인은 외로움을 견디지 못하여 집을 버리고 탁군으로 갔습니다.\" 생이 크게 놀라 다시 물었다. \"탁군에는 누구를 찾아 언제 갔소?\" 대답하였다. \"그 부인의 외조카 선비 유영을 찾아간 지 이미 여러 해 되었습니다.\" 생이 어찌할 수 없어 집으로 돌아와 부모께 딱한 사정을 아뢰었다. 평장이 말하였다. \"탁군에 영리한 하인을 보내 그 허실을 자세히 알고 온 뒤라도 늦지 않다.\" 생은 마음이 급하였으나 그 명을 거스르지 못하여 하인에게 당부하여 탁군에 가서 정 시랑 부인이 계신 곳을 자세히 알아 오라 하고 보냈다. 몇 달 만에 하인이 돌아와 아뢰었다. \"몇 해 전 시랑 부인이 그곳에 간 것은 분명하나 여자에 대한 소식은 듣지 못하였다 하더이다.\" 평장 부부는 담담하게 들었으나 생은 낯빛이 변하였다. [?]","sp":[[22,24,"P","정씨"],[94,98,"P","정 시랑"],[269,271,"P","김평"],[366,373,"P","소씨"],[474,476,"P","김평"]]},{"c":1,"sub":"","t":"평장이 생의 거동을 보고 행여 몸이 상할까 염려하여 문득 엄한 목소리로 말하였다. \"대장부가 세상에 살면서 가는 곳마다 집이 있고 집마다 미인이 있다 하는데, 어찌 한 여자를 위하여 시름을 품느냐?\" 생이 황공하여 절하며 말하였다. \"소자가 굳이 그 여자만을 지극히 위하는 것이 아니오라, 그 여자는 참으로 이 세상에 드문 사람입니다. 그 재주와 미색은 말할 것도 없고 행실과 효행이 태임과 태사에 견줄 만합니다. 그뿐 아니라 그 홑몸이 외로워 의지할 곳이 없으니 생각하면 자연히 시름을 금치 못하옵니다. 또 지금 소자를 위해 절개를 지키느라 고생이 심할 터인데, 만일 그를 무심히 버려두면 소자는 신의 없고 박정한 사람이 될 듯하오니 저절로 마음이 불안함을 깨닫지 못하였습니다. 아버님 말씀이 이러하시니 황공함을 이기지 못하겠사옵니다.\" 평장도 애처롭게 여겼으나 의리로 꾸짖으니 생은 감히 다시 말을 꺼내지 못하였다.","sp":[[0,2,"P","김평"],[414,416,"P","김평"]]},{"c":1,"sub":"","t":"한편, 접숙공은 간신으로 일찍이 경장과 혐의가 있었으므로 평장은 하람을 버리고 영천으로 옮겨 갔다. 그리하여 장 소저의 소식은 더욱 아득해졌다[?]. 생은 그리움을 참지 못하였으나 부모의 꾸지람이 두려워 억지로 청하지 못하고, 밤낮으로 소저의 모습을 그리워하다가 어느새 은근히 병이 들었다. 먹고 마시기를 모두 끊고 자리에 누워 마음만 허비하니 모습이 수척하고 기운이 쇠진하여 병이 깊어졌다. 부모가 크게 근심하여 병상에 나아가 물었다. \"너는 어디를 갔다 왔기에 무슨 일로 부모의 마음은 생각지 않고 몸을 돌보지 않느냐? 지금 네 병을 보니 바람과 추위에 상한 것이 아니라, 얼굴이 초췌하고 모습이 괴로우며 미간에 시름이 가득하니 네가 장씨를 그리워하는 것이로구나. 사실을 숨기지 마라. 내 네 소원을 들어주리라.\" 생이 이 말을 듣고 감사함을 이기지 못하여 태연히 대답하였다. \"부모님 말씀이 이러하시니 황공하기 그지없사오나, 소자가 굳이 장씨를 위하는 것이 아니오라 그 사람의 일생이 외로운 것을 생각하니 마음이 저절로 편치 않아 여러 날 문안을 드리지 못하였습니다. 불효가 막대하오나 대단하지 않사오니 지나치게 염려하지 마소서.\" [?]","sp":[[4,7,"P","접숙공"],[32,34,"P","김평"],[61,65,"P","장설빙"],[92,94,"P","소세필"]]},{"c":1,"sub":"","t":"평장이 그 병을 짐작하고 행여 병이 더할까 두려워 좋은 말로 위로하였다. \"너는 염려 말고 어서 일어나 널리 물어 찾아서 인연을 이루고 몸을 보존하여라.\" 생이 기뻐하며 사례하고 곧 일어났다. 본디 장 소저를 찾지 못하여 얻은 병이라, 부모의 허락을 받으니 마음이 시원해져 저절로 회복되어 열흘이 못 되어 나았다. 평장이 기뻐하며 생을 불러 일렀다. \"네가 참으로 저 장씨를 위한다면 참지 못할 것이니 어서 찾아보아라.\" 생이 마음에 두고 있던 중 이 말씀을 들으니 온 마음이 기뻐 사례하였다. \"분부가 이러하시니 삼가 받들어 행하겠사옵니다.\"","sp":[[0,2,"P","김평"],[111,115,"P","장설빙"],[176,178,"P","김평"],[215,217,"P","소세필"]]},{"c":1,"sub":"","t":"이튿날 행장을 꾸려 길을 떠나면서 부모께 하직하였다. \"소자가 가는 길은 언제 돌아올지 정하지 못하오니 염려 마시고 몸 편안하옵소서.\" 부모는 아들에게 어서 돌아오라고 거듭 당부하였다. 생은 황금 백 냥을 가지고 푸른 나귀를 타고 바로 탁군으로 가서 유생을 찾아 물었다. 정 시랑 부인이 그곳에 있는 것은 분명하나 소저의 종적은 없었다. 생이 알 길이 없어 널리 찾다가 문득 생각하였다. '그 사람은 친척이 전혀 없고 의탁할 곳이 없으니 반드시 북해의 귀양지로 갔을 것이다. 그러나 만 리 먼 길에 큰 강이 가로막혔으니 규중의 약한 몸이 어찌 다다를 수 있으리오. 반드시 길에서 죽었구나.' 여러 가지로 생각하며 마음을 진정하지 못하여 눈물이 옷깃을 적시니, 그 모습은 차마 볼 수 없었다.","sp":[[140,142,"P","도인"],[152,159,"P","소씨"]]},{"c":1,"sub":"","t":"시신이라도 찾으려고 이튿날 길을 떠나 여러 날 만에 겨우 북해에 다다르니, 이미 해는 서산에 지고 먼 마을에 연기가 피어올랐다. 더욱 시름을 금치 못하여 한곳에 앉아 소저를 생각하고 있었는데, 이때 북해 태수가 마침 나왔다가 생의 모습을 보고 매우 이상히 여겨 불러서 물었다. 생이 앞뒤 사연을 아뢰자, 태수는 장생이 상구를 호송하여 보낸 일을 낱낱이 전하였다. 생이 속으로 생각하였다. '상여를 모시고 간 것이 확실하다면 산소로 찾아가면 자연히 알 수 있겠다.' 하고 나귀를 돌려 돌아오면서 길게 탄식하였다. \"애석하다. 소저는 혈혈단신이라 의탁할 데가 없는데 어디서 김희경을 생각하고 있는가. 떠난 지 오래되었으니 부모님의 근심이 적지 않을 것이다. 어서 돌아가 부모님을 뵙고 나서 산소에 가서 그 상주를 찾아 물으면 반드시 소저의 거처를 알 것이다.\" 하고 노새를 채찍질하여 돌아오는데, 오 리쯤 오니 서강 언덕에 큰 바위가 있고 그 아래 사람의 자취가 있었다. 살펴보니 웬일인지 마음이 쏠려 자세히 보고 싶어 노새에서 내려 두루 구경하였다.","sp":[[111,116,"P","북해 태수"],[170,172,"P","북해 태수"],[174,176,"P","장설빙"],[319,322,"P","김희경"]]},{"c":1,"sub":"","t":"김생이 노새에서 내려 잠깐 쉬다가 문득 눈을 들어 살펴보니 그 바위 위에 무슨 필적이 있었다. 자세히 보니 피로 쓴 글이었다. \"청주 사람 장 소저 설빙은 불효와 신의 없음을 무릅쓰고 병진년 가을 칠월 보름에 이 물에 빠져 죽노니, 천지일월과 후토의 신령은 밝히 아소서.\" 또 그 아래에 \"같은 달 같은 날에 유모 설낭과 시비 영춘은 주인을 따라 함께 이 물에 죽노니, 해와 달과 별은 아소서.\" 하였다. 생이 다 보고 크게 놀라 낯빛이 변하며 정신을 잃고 혼절하였다가, 한참 뒤에야 정신을 차려 다시 보고 크게 통곡하였다. \"장 소저가 이곳에 와서 죽었구나. 불쌍하고 가련하도다. 소저를 위하여 탁주군에서 북해까지 먼 길을 지척같이 다니며 찾았으나 끝내 종적을 알지 못하였다. 잠깐 부모님을 뵙고 걱정을 덜어 드린 뒤 다시 청주로 가서 상서의 시신을 옮겨 온 사람을 찾아 소저의 거처를 알고자 하였는데, 슬프다, 이곳에 와서 소저의 옥 같은 마음이 넓은 물결 속 물고기 밥이 될 줄을 어찌 알았으리오.\" 하고 하늘을 우러러 통곡하니 산천도 슬픔을 머금고 새와 짐승도 서러워하였다.","sp":[[0,2,"P","김희경"],[78,82,"P","장설빙"],[83,85,"P","장설빙"],[173,175,"P","설낭"],[176,178,"P","설낭"],[183,185,"P","영춘"],[295,299,"P","장설빙"]]},{"c":1,"sub":"","t":"생이 슬픔을 금치 못하여 행장에서 황금을 꺼내 마을에 내려가 팔아 제물을 갖추고 제문을 지어 제사를 지냈다. 그 제문은 이러하였다. \"모년 모월에 하람 김희경은 마음속에 쌓인 회포를 물속의 외로운 혼 소저께 고하노라. 오호 통재라. 천지가 생긴 뒤 오륜이 있고, 오륜 가운데 특별한 것은 부부라. 형초 객점에서 우연히 만나 백옥 한 조각과 금가락지 한 짝을 바꾸어 평생을 언약하니, 소저의 쇠와 돌 같은 맹세는 뒷날 버리지 않기로 굳게 정하였고, 나 또한 간담을 열어 백년가약을 정하였으니 천지신명이 분명히 아는 바라. 한번 급제하여 높은 벼슬에 오르면 부모님께 아뢰고 소저의 외로움을 위로하고자 하여, 한번 이별이 애처로우나 두 번 만남이 반드시 있으리라 생각하고 훌훌히 꽃 같은 얼굴과 이별하고 서울로 떠났노라. 마디마디 간장이 날로 녹아내리나 주머니 속에 금가락지 한 짝이 있으니, 이것으로 뒷날을 위로하며 세월을 보냈노라. 맺힌 회포를 이기지 못하여 옥 같은 얼굴을 어서 보고자 부모님께 아뢰고 탁주로 찾아가니, 만나기는커녕 종적이 끊어져 바라던 마음이 한 조각 뜬구름이 되어 허공에 흩어졌도다.","sp":[[85,88,"P","김희경"]]},{"c":1,"sub":"","t":"이에 넋을 잃어 세상일에 뜻이 없었으나, 소저의 얼음과 옥 같은 마음이 반드시 까닭 없이 남의 단심을 저버리지 않으리라는 생각이 솟아, 천하를 다 돌아서라도 종적을 찾고자 마음을 정하고 사방을 두루 다녔노라. 그래도 찾지 못하여 다시 청주 본가로 가려 하였는데, 슬프다, 이곳에 와서 꽃이 떨어지고 옥이 잠길 줄을 어찌 알았으리오. 가련하다, 청주에서 이곳은 천 리 밖이거늘 무슨 까닭으로 타향에서 주인 없는 외로운 혼이 되었는고. 애재라, 바라던 마음이 속절없이 끊어지고 썩은 간장이 오늘마저 사라지는구나. 처량하다, 소저는 무슨 일로 쇠와 돌 같은 언약을 버리고 청춘 홍안에 속절없이 세상을 버려 김희경에게 온갖 시름을 끼치는가. 옥 같은 손으로 쓴 두어 줄 필적은 세상에 걸려 있으나 구름 같은 머리와 붉은 얼굴은 구천에 가까웠으니, 꽃 같은 모습은 이미 세상에서 사라지고 신방에서 다시 만나기를 바랄 수 없구나. 나는 이제 몸을 버려 소저의 뒤를 따라 혼백을 위로하고자 하나, 집에 계신 백발의 양친이 바라는 것은 나 한 몸뿐이라. 그러므로 남은 목숨을 보전하여 소저의 뒤를 따르지 못하노라. 훗날 구천에서 서로 보는 것이 어찌 부끄럽지 않으리오. 그러나 하늘이 무너지고 땅이 꺼질지라도 이 한은 씻지 못하리로다.\" 천지를 부르며 슬피 통곡하니 넓은 물결에 바람과 구름이 일어나고 근심스러운 구름이 덮였다. \"소저의 영혼이 앎이 있거든 나에게 영혼의 자취를 비추소서. 오호 상향.\"","sp":[[336,339,"P","김희경"]]},{"c":1,"sub":"","t":"읽기를 마치고 크게 애통하니 기운이 쇠진하여 진정하지 못하다가, 이윽고 정신을 차려 다시 슬퍼하며 설낭과 영춘의 충심을 더욱 애달프게 여겼다. 길에는 인적이 없고 먼 산에 푸른 연기가 일어나니, 생의 슬픔이 태산 같았으나 부모님이 기다리실 것을 생각하여 오래 머물지 못하고 노새를 채찍질하여 집으로 돌아왔다. 부모님을 뵈니 평장 부부가 반기며 오래 그리던 정을 말하였다. 그런데 생의 기색을 보니 근심이 가득하여 얼굴이 수척하고 시름겨운 빛이 끝이 없으므로, 평장이 매우 놀라 물었다. \"네가 오래 부모를 떠나 다니다가 만났으니 정이 자못 깊을 터인데, 어찌 즐거운 빛이 없고 도리어 얼굴에 근심이 가득하냐? 모르겠구나, 무슨 까닭이 있느냐?\"","sp":[[55,57,"P","설낭"],[59,61,"P","영춘"],[181,183,"P","김평"],[257,259,"P","김평"]]},{"c":1,"sub":"","t":"생이 서글피 말을 못하다가 목이 메어 한참 잠잠하더니, 겨우 정신을 수습하여 장 소저가 죽은 사연과 유모와 시비가 함께 죽은 사연을 아뢰었다. 평장 부부가 놀라 소리 내어 울며 말하였다. \"불쌍하고 가련하다. 오죽 서러웠으면 청춘에 세상을 버리고 푸른 물결에 물고기 밥이 되었겠느냐. 이리 된 것도 다 우리의 불행이니, 이제 며느리 볼 바람이 끊어졌구나.\" 하며 그 정을 못내 애석해하였다. 생은 부모의 지극한 마음에 감격하여 슬픔을 얼굴에 드러내지 않았으나 마음속에 맺힌 한은 잊지 못하였다.","sp":[[43,47,"P","장설빙"],[56,58,"P","설낭"],[80,82,"P","김평"]]},{"c":1,"sub":"","t":"이럭저럭 겨울 석 달을 지내고 봄이 되자, 나라에서 어진 선비를 뽑으려고 과거 조서를 내렸다. 평장이 이 소식을 듣고 생을 불러 말하였다. \"이제 장 소저는 이미 죽었고 네 혼인은 늦어 가니 우리 근심이 적지 않다. 이제 들으니 과거를 보인다 하니 너는 속절없이 시골에 묻혀 때를 놓치지 말고 서울에 올라가 과거도 보고, 석 태위를 찾아 편지를 전하고 어진 숙녀를 구하여 우리 마음을 위로하여라.\" 생은 비록 장 소저를 향한 마음이 태산 같으나 죽은 줄을 분명히 알고, 또 부모님의 염려를 생각하여 기꺼이 대답하였다. \"부모님께서 믿으시는 것은 소자뿐인데, 남자가 어찌 죽은 사람을 위하여 절개를 지키느라 후사를 근심하지 않겠사옵니까.\" 평장이 크게 기뻐하여 곧 편지 한 통을 써 주니, 생이 명을 받들어 부모께 하직하고 서울로 떠났다.","sp":[[53,55,"P","김평"],[82,86,"P","장설빙"],[180,184,"P","석 태위"],[229,233,"P","장설빙"],[357,359,"P","김평"]]},{"c":1,"sub":"","t":"형초 객점에 이르자 장 소저를 생각하고 길게 탄식하였다. \"풍경은 예와 같은데, 애석하다, 장 소저는 어디로 갔는고.\" 하고 주머니를 열어 가락지를 꺼내 어루만지며 탄식하였다. \"주인이 없다 하였거늘 너는 어찌하여 나의 주머니를 지키며 임자를 만나지 못하느냐.\" 하며 눈물을 흘리고 슬픔을 금치 못하였다. 날이 저물자 노새를 채찍질하여 서울에 다다라 석 태위 집에 가서 문안하고 편지를 드렸다. [?]","sp":[[11,15,"P","장설빙"],[51,55,"P","장설빙"],[196,200,"P","석 태위"]]},{"c":1,"sub":"","t":"태위가 못내 반기며 생의 손을 잡고 안채로 들어가 대접하며 말하였다. \"평과 누이의 편지를 보니 태임과 태사, 반희 같은 숙녀를 구하라 하였으나, 조카의 풍채를 보니 반악과 사마상여라 할 만하니 짝을 찾기 어렵겠구나. 어디서 조카의 짝을 얻으리오.\" 생이 자리를 피하며 대답하였다. \"숙부께서 이렇게 저를 위하시니 감사함을 이기지 못하겠사옵니다.\" 태위가 칭찬하며 서당에 머물게 하고 어진 숙녀를 구하였다. 하루는 생에게 말하였다. \"조카를 위하여 배필을 구하였으나 뜻에 맞는 곳이 없더니, 이제 좌승상 최후의 딸이 자색이 당대 제일이요 덕행이 태임을 압도한다 하니, 참으로 그러하다면 조카의 짝이 될 만하다. 그러나 최공은 지위가 높고 풍채가 엄하여 조카의 한미함을 꺼려 허락하지 않을 듯하니, 부디 이번 과거를 놓치지 않으면 그 뜻을 이룰 수 있을 것이다.\" [?]","sp":[[0,2,"P","석 태위"],[195,197,"P","석 태위"],[278,281,"P","최후"],[282,284,"P","최후"]]},{"c":1,"sub":"","t":"생이 살짝 웃으며 말하였다. \"과거는 참으로 소질의 손안에 있사옵니다. 그러나 소질이 평생 정한 뜻이 있사오니, 비록 외람되오나 어떤 여자든 그 자색을 먼저 보고 난 뒤에야 인연을 맺겠습니다. 바라옵건대 숙부께서는 소질을 위하여 최 소저의 현명함과 어리석음을 볼 수 있게 해 주소서.\" 태위가 웃으며 말하였다. \"조카의 말이 터무니없구나. 시골의 미천한 사람이라도 그렇게는 못할 터인데, 하물며 공후 귀족 집안의 규수를 어찌 엿보겠느냐. 조카는 외람된 뜻을 품지 마라.\" 생이 옷깃을 여미고 대답하였다. \"소질은 타고난 성품이 고집스러워 한번 정한 뜻은 고치지 못하는 까닭에 진정을 아뢴 것인데, 숙부께서 외람되다 여기시니 황공함을 이기지 못하겠사옵니다.\"","sp":[[128,132,"P","최씨"],[160,162,"P","석 태위"]]},{"c":1,"sub":"","t":"태위가 한참 생각하다가 말하였다. \"조카는 무슨 풍악을 배운 재주가 있느냐?\" 생이 대답하였다. \"소질이 다른 풍악은 모르오나, 어려서 산에 갔다가 우연히 기이한 사람을 만나 거문고 타는 법을 조금 배웠습니다. 비록 혜강(嵇康) 같은 묘한 솜씨는 없사오나 음률은 대강 짐작하옵니다.\" 태위가 크게 기뻐하며 말하였다. \"그렇다면 조카의 뜻을 이룰 수 있을 듯하니 잠시 때를 기다려라.\" 생이 그 까닭을 물으니 태위가 웃으며 말하였다. \"이달 보름이 승상의 생신이다. 그날 이러이러하면 소원을 풀 수 있겠지만, 그렇지 않으면 규중의 꽃 같은 처녀를 그림자인들 어찌 엿보겠느냐. 모르겠구나, 조카가 능히 할 수 있겠느냐?\" 생이 웃으며 말하였다. \"이 일이 비록 경박하여 군자의 도리는 아니오나, 어진 숙녀를 구하여 부모님께 효도하고 제사를 정성으로 받들어 즐기는 것은 사람의 자식 된 도리이옵니다.\" 하니 태위가 크게 웃었다.","sp":[[0,2,"P","석 태위"],[159,161,"P","석 태위"],[228,230,"P","석 태위"],[449,451,"P","석 태위"]]},{"c":1,"sub":"","t":"이렇게 그날을 기다리는데 어느덧 시월 보름이 되었다. 태위가 의관을 갖추고 승상 댁으로 가면서 생에게 당부하였다. \"차림을 이러이러하게 하고 있다가 나의 기별을 기다려라.\" 생이 예, 하고 대답하였다.","sp":[[30,32,"P","석 태위"]]},{"c":1,"sub":"","t":"태위가 승상 댁에 이르니, 승상이 많은 손님을 모아 중당에 풍악을 벌이고 즐기다가 태위를 보고 서로 맞아 반겼다. 자리를 정한 뒤 다시 노래와 춤을 벌여 즐기다가, 술이 반쯤 취하자 태위가 승상께 청하였다. \"오늘 소제가 명공의 성대한 잔치에 함께 즐기며 좋은 경치를 구경하니 분에 넘치는 기쁨이옵니다. 오늘은 명공께서 즐기시는 날인데 소제가 위로해 드릴 것이 없습니다. 마침 소제에게 아름다운 기생이 하나 있는데, 혜강의 후신이요 백아의 넋이라, 흰 이 사이로 구름을 머무르게 하고 옥 같은 손끝으로 봉황을 부르는 재주가 있습니다. 소제가 그 사람의 재주를 아껴 문하에 머물게 하였사온데, 오늘 성대한 잔치에 여러 기생이 모였으나 그 미인을 잠깐 불러 명공의 웃음을 돕고자 하옵니다.\" 승상이 크게 기뻐하며 말하였다. \"현제가 나를 위하여 미인을 불러 주겠다 하니 감사한 일이라 어찌 사양하겠소. 곧 불러 잔치에 빛을 더하시오.\" 태위가 기꺼이 아이 종을 보내 그 미인을 데려오라 하였다.","sp":[[0,2,"P","석 태위"],[46,48,"P","석 태위"],[102,104,"P","석 태위"],[466,468,"P","석 태위"]]},{"c":1,"sub":"","t":"이때 김생은 태위와 약속을 정하고 남자 옷을 벗은 뒤 초록 저고리에 붉은 치마를 입고 구름 같은 머리를 단장하여 조용히 태위의 기별을 기다리고 있었다. 아이 종이 와서 부르자 생이 기꺼이 거문고를 가지고 아이 종을 따라 승상 댁에 이르러 중당으로 들어갔다. 승상이 주인 자리에 앉고 태위와 여러 손님이 좌우에 벌여 앉았는데, 기생 수십 명이 비단옷 단장으로 저마다 봄빛을 다투며 잔치 자리에 가득하니 마치 요지연에 모인 듯하였다. 생이 나아가 섬돌 아래에서 뵈니 승상이 명하여 대청 위에 자리를 주었다. 눈을 들어 보니 가을 같은 눈썹과 꽃 같은 얼굴은 연꽃이 아침 햇살을 띤 듯하고, 검은 귀밑머리와 붉은 얼굴은 초산에 흐르는 구름이 머문 듯하며, 한 쌍의 맑은 눈은 가을 하늘의 밝은 별이 돋은 듯하였다. 붉은 입술과 흰 이에 온갖 자태를 갖추었으니, 여러 손님이 모두 눈을 보내고 기생들은 넋을 잃어 어찌할 줄 몰랐다.","sp":[[3,5,"P","김희경"],[7,9,"P","석 태위"],[67,69,"P","석 태위"],[158,160,"P","석 태위"]]},{"c":1,"sub":"","t":"승상이 크게 기뻐하여 태위를 돌아보며 말하였다. \"이는 한나라 때의 왕소군이요 당나라 때의 양태진이로다. 현제가 일찍이 저런 사람을 구한 적이 없더니 이제 어디서 저런 미색을 얻어 왔소?\" 태위가 살짝 웃으며 말하였다. \"우연히 그 재주를 자랑하고자 불렀을 뿐인데 명공께서 이렇게 과찬하시니 참으로 부끄럽습니다. 그러나 그 재주를 시험해 보옵소서.\" 승상이 그 미녀를 나오라 하여 물었다. \"네 이름은 무엇이며 나이는 몇이며 누구의 딸이냐?\" 생이 가는 허리의 붉은 [□]을 끌고 푸른 소매를 펄럭이며 사뿐사뿐 걸어 나와 옷깃을 여미고 대답하였다. \"소첩의 이름은 초운이요 자는 초연이며, 천한 나이는 열여섯이옵니다.\" 승상이 크게 웃으며 말하였다. \"옛날 초왕이 아침 구름과 저녁 비가 되는 신녀를 만났는데, 이제 보니 네 이름과 재주가 꼭 맞는구나. 그러나 태위가 네 재주를 과히 칭찬하니 한 곡 청하는 것을 아끼지 마라.\"","sp":[[12,14,"P","석 태위"],[106,108,"P","석 태위"],[426,428,"P","석 태위"]]},{"c":1,"sub":"","t":"생이 속으로 웃음을 머금고 곧 거문고를 내어 가느다란 옥 같은 손으로 태평곡을 타며, 흰 이 붉은 입술로 죽지사를 부르니, 소리가 맑고 고와 공중으로 솟구쳤다. 떠가는 구름이 머무르고 단산의 봉황이 울며 옥쟁반에 진주가 구르는 듯하여 맑은 소리가 시원하니, 자리에 가득한 손님과 기생들이 모두 정신을 잃고 기운이 어지러워 말을 하지 못하였다. 승상도 낯빛을 고치고 묵묵히 있다가 한참 뒤 금빛 부채를 들어 치며 말하였다. \"내 나이 예순이 넘었으나 이런 소리는 처음 듣는도다. 모르겠구나, 천신이 내려와 나를 속이는 것이로다.\" 생이 일어나 절하며 말하였다. \"한 조각 곡조를 들으시고 어찌 이토록 아껴 주시니 황공하옵니다.\" 승상과 손님들의 칭찬이 오히려 대답하기 어려울 정도였다.","sp":[[274,276,"P","도인"]]},{"c":1,"sub":"","t":"이럭저럭 소문이 차차 전해져 안채에까지 미쳤다. 승상 부인이 여러 부인을 데리고 따로 잔치를 벌여 즐기다가, 바깥채에 명창이 왔다는 말을 듣고 구경하고자 시비를 시켜 승상께 청하였다. 승상이 그 미인에게 말하였다. \"안채에서 네 이름을 듣고 재주를 보고자 하시니 들어가기를 사양하지 마라.\" 생이 기꺼이 대답하였다. \"분부가 이러하시니 어찌 사양하겠사옵니까.\" 하고 시비를 따라 안으로 들어가 살펴보니, 승상 부인이 여러 부인과 중당에 자리를 정하였는데, 아름다운 얼굴과 화려한 붉은 치마가 자리에 벌여 있어 참으로 요지연에 모인 것 같았다. 생이 기쁨을 이기지 못하여 섬돌 아래에 나아가 뵈니 부인이 청하여 대청 위에 자리를 주었다. 부인들이 눈을 들어 보니 봄바람 같은 화기와 달 같은 자태, 꽃 같은 얼굴이 사람의 넋을 놀라게 하니, 참으로 돌 속의 옥이요 바다 속의 밝은 구슬이었다. 자리에 가득한 이들이 크게 놀라 어찌할 줄 모르고 이상히 여겼다.","sp":[]},{"c":1,"sub":"","t":"부인도 정신을 잃어 홀린 듯 취한 듯 묵묵히 있다가 한참 뒤 탄식하였다. \"아름답다. 세상에 어찌 이런 미색이 있는고. 그러나 귀한 소리를 잠깐 듣고자 하니 품은 재주를 아끼지 마라.\" 생이 옷깃을 여미고 절한 뒤 거문고를 내어 양춘곡을 타며 옥 같은 목소리를 가다듬어 요지군 태평가를 부르니, 그 곡조가 맑고 고와 공중으로 솟구쳤다. 승상 부인과 여러 부인이 모두 놀라 칭찬하였다. \"이 사람은 참으로 비연의 넋이요 혜강의 후신이로다. 그렇지 않으면 어찌 세상에 이런 사람이 있으리오.\" 자리에 가득한 이들이 모두 감탄하는 빛이었다.","sp":[]},{"c":1,"sub":"","t":"여러 부인이 승상 부인께 청하였다. \"오늘은 좋은 날이요, 게다가 기특한 사람을 만나 세상에 없는 소리를 들으니 참으로 우리끼리만 듣기 아깝습니다. 생각건대 소저가 별당에 혼자 있어 적적할 듯하오니 불러서 함께 즐기는 것이 좋을까 하옵니다.\" 부인이 대답하였다. \"딸아이가 본래 이런 일을 좋아하지 않기에 생각하지 못하였는데, 이렇게 권하시니 함께 참여하는 것이 어찌 꺼릴 일이겠습니까.\" 곧 시비를 시켜 부인의 명을 전하였다. \"오늘 성대한 잔치는 집안의 즐거운 날이요, 게다가 이름난 여악사가 왔으니 사양하지 말고 나와서 구경하여라.\" 소저가 다 듣고 명을 받들어 말하였다. \"오늘 성대한 잔치를 맞아 원근의 친척이 다 모였으니 나아가 뵙는 것이 당연하오나, 마침 몸이 피곤하여 분부를 받들지 못하오니 황공하옵니다.\" 시비가 아뢰자 자리에 있던 이들이 모두 서운해하였고, 생도 마음이 언짢아 무엇을 잃은 듯하였다. [?]","sp":[]},{"c":1,"sub":"","t":"자리에 있던 최 부인은 부인의 조카딸이었다. 문득 일어나며 말하였다. \"자리에 가득한 이들이 다 언니가 나오기를 바라는데, 무슨 병이 잠깐 사이에 그리 깊어 움직이지 못한단 말입니까. 이는 반드시 꾀병이니 제가 친히 들어가겠습니다.\" 하고 소저의 방으로 들어가니 소저가 책상에 기대어 옛글을 보고 있었다. 최 부인이 곁에 앉으며 웃었다. \"오늘 잔치가 집안의 지극한 경사인 줄은 언니도 아는 바요, 게다가 여악사가 왔는데 인물이 비범하고 재주 또한 기이합니다. 그래서 언니를 청한 것인데 굳이 사양하는 것은 어째서입니까?\" 소저가 옷깃을 여미고 대답하였다. \"어찌 조금이라도 병을 핑계하겠느냐. 마침 체하여 몸이 피곤하기에 나갔다가 병이 더할까 해서이다.\" 최 부인이 웃으며 말하였다. \"언니의 얼굴을 보니 봄빛이 영롱하여 붉은 입술에 혈기가 넘치고 병색은 반 점도 없는데 체할까 핑계하니, 이는 이른바 귀를 막고 방울을 훔치는 격입니다.\" 하고 소저의 손을 잡고 나가기를 재촉하였다. 소저는 마음이 내키지 않았으나 마지못하여 함께 나왔는데, 중당에 이르자 최 부인이 먼저 들어가 소저가 나온다고 알렸다.","sp":[[7,11,"P","최씨"],[171,175,"P","최씨"],[368,372,"P","최씨"],[536,540,"P","최씨"]]},{"c":1,"sub":"","t":"승상 부인과 여러 부인이 매우 기뻐하였고, 생도 실망하였다가 못내 기뻐하였다. 문득 한 쌍의 차환이 앞에서 인도하여 나오는데, 채색 옷에 붉은 치마로 사뿐사뿐 걸어 자리에 이르니 여러 부인이 일시에 맞아 자리를 다시 정하였다. 생이 온 마음이 기뻐 몸을 일으켜 소저를 향해 공손히 절하고 물러앉아 눈길을 흘려 소저를 보았다. 구름 같은 [□]발이 옥 같은 얼굴에 비꼈고, 태양이 처음 솟는 듯하며, 두 뺨은 가을바람 속 모란꽃이 무르녹은 듯하고, 붉은 입술은 따스한 햇볕과 단 이슬에 새로 핀 복숭아꽃 같았다. 흰 눈 같은 살결에 비단 적삼이 나부끼고, 가는 버들 같은 허리에 붉은 치마가 향기로운 바람을 일으키니, 참으로 직녀가 하강하고 항아가 월궁에 앉은 듯하여 천고의 일색이라 할 만하였다. 여러 부인이 다 고와 반 점의 흠도 없었으나 이에 비하면 밝은 구슬 옆 모래 속 돌과 같고 백옥 옆에 묻힌 흙과 같았으니, 참으로 장 소저의 짝이라 할 만하였다. 생이 속으로 못내 탄복하였고 여러 부인의 칭찬이 끊이지 않았다. [?]","sp":[[463,467,"P","장설빙"]]},{"c":1,"sub":"","t":"이에 술을 내와 승상 부인께 올리니 부인이 기쁨을 이기지 못하여 기쁜 빛이 가득하였다. 자리에 가득한 이들이 다 즐겨 웃고 이야기하는 소리가 자리에 어지러웠으나, 소저는 홀로 옷깃을 바로 하고 단정히 앉아 눈썹을 숙이고 웃거나 말하지 않으니, 그 차가운 기색이 눈서리 속 매화 같아 그 속마음을 헤아릴 수 없었다. 생은 속으로 중당이 넓어 소저가 멀리 앉은 것을 탄식하였는데, 승상 부인이 거문고 소리를 소저에게 자세히 들려주고자 가까이 앉으라 명하였다. 생이 매우 기뻐 거문고를 안고 소저 앞에 나아가 앉으며 말하였다. \"소녀는 하람의 기생인데, 어려서 기이한 사람을 만나 거문고 두어 곡조를 배웠사오나 오늘에 와서는 아무것도 모르오니 황공하옵니다. 듣자오니 소저께서는 혜강의 넋을 지니시어 음률에 정통하시다 하오니, 잠깐 평론하시어 가르쳐 주시기를 청하옵니다.\"","sp":[]},{"c":1,"sub":"","t":"소저는 명창이 온 것을 이미 들었으나 타고난 성품이 신중하여 살펴보지 않았는데, 문득 눈을 들어 보니 아리따운 자태가 눈을 놀라게 하고 가을 같은 눈썹과 붉은 뺨이 정신을 크게 놀라게 하였다. 마음속으로 생각하였다. '내 일찍이 이런 미인을 보지 못하였으니 이는 반드시 선녀로다. 기생 무리의 이름난 미색이라니 아깝지 않은가.' 한번 보자 오랜 벗 같아서 반갑게 대답하였다. \"깊은 규중의 약한 몸이 어찌 음률을 알겠느냐. 그러나 그대가 배운 바를 듣고자 하노라.\" [?]","sp":[]},{"c":1,"sub":"","t":"이에 생이 거문고를 내어 한 곡조를 타니 소리가 맑고 고와 구름을 머무르게 하는 듯하여 자리에 있던 이들이 모두 칭찬하였다. 그러나 소저는 홀로 기뻐하는 기색 없이 말하였다. \"이는 당나라 진왕의 파진곡이다. 태종이 군사를 일으켜 이 곡조를 지어 삼군을 즐겁게 하였으니, 비록 웅장하나 영웅호걸이 천하를 다투는 곡이라 여자에게는 상관없으니 다른 곡조를 타라.\" 생이 또 다른 곡조를 타니 소저가 서글피 말하였다. \"이는 옥수후정화라. 진 후주가 장려화와 함께 즐기다가 끝내 나라를 망하였으니, 이는 나라를 망하게 한 곡조라 반갑지 않으니 다른 곡조를 타라.\" 생이 또 한 곡조를 타니 소저가 낯빛을 바꾸며 말하였다. \"이는 예상우의곡이라. 당 명황이 양귀비와 화청궁에서 이 곡조를 즐기다가 안녹산의 난을 만났으니, 이는 난리를 부른 곡조라 불길하니 다른 곡조를 타라.\" 생이 또 한 곡조를 타니 소저가 낯빛을 고치며 옥 같은 손으로 구름 같은 귀밑머리를 어루만지며 말하였다. \"아름답다. 이 곡조를 어려서 듣고 지금까지 잊지 못하였는데, 그대는 이런 기특한 곡조를 어디서 배웠느냐? 대순(大舜)이 남훈전에서 이 곡조를 타시며 만백성의 괴로움을 염려하시던, 태평성대를 즐기던 소리라 들을 만하니, 다른 곡조가 있더라도 이 곡조만 이어서 타라.\"","sp":[]},{"c":1,"sub":"","t":"생이 한참 타다가 그치고 옷깃을 여미며 사례하였다. \"소첩이 곡조를 배웠으나 이름은 몰랐는데, 소저께서 이렇게 밝히 가르쳐 주시니 가슴이 시원하여 구름과 안개를 헤치고 푸른 하늘에 오른 듯하옵니다. 감사하오며, 남은 곡조가 하나 있사오니 가르침을 바라옵니다.\" 하고 또 한 곡조를 타니, 소저가 갑자기 얼굴이 붉어지며 봉황 같은 눈을 들어 한참 보다가 눈썹을 숙이고 부끄러워하는 빛이 있었다. 생이 속으로 짐작하고 짐짓 말하였다. \"참으로 이 곡조를 모르오니 밝히 가르쳐 주소서.\" 소저가 발끈 낯빛을 바꾸며 말하였다. \"나도 이 곡조는 처음 듣는 것이라 알지 못하노라.\" 하고 문득 화기가 사라지고 가을 서리 같은 기운이 일어 차가운 기색이 씩씩하더니, 부인께 아뢰었다. \"소녀가 갑자기 몸이 불편하여 들어가겠사옵니다.\" 하며 비단 휘장을 들고 훌쩍 들어가 버리니, 부인과 자리에 있던 이들은 그 기미를 모르고 정말 체한 것인가 걱정하였다.","sp":[]},{"c":1,"sub":"","t":"원래 이 곡조는 사마상여가 탁문군을 꾀어 함께 달아날 때 탄 봉구황곡이었다. 생이 짐짓 모르는 체하고 소저의 마음을 시험해 본 것인데, 소저가 기미를 알고 피하자 생은 그 밝은 눈에 탄복하였다. 오래 머무는 것이 옳지 않다 여겨 부인께 하직하였다. \"소저께서 소첩을 아끼시어 묻고 답하시다가 체하여 몸이 불편하시다 하니 불안하옵니다. 황공하오나 돌아가기를 청하옵니다.\" 부인이 애석해 마지않았다. 생은 하직한 뒤 곧 바깥채로 나와 또 승상께 하직하니, 승상이 못내 칭찬하며 황금 백 냥을 상으로 주었으나 또 사양하여 받지 않고 나오니 자리에 있던 이들이 모두 칭찬하였다.","sp":[]},{"c":1,"sub":"","t":"이럭저럭 해가 기울어 손님들이 모두 흩어지자 태위도 하직하고 돌아와 생을 불렀다. 생이 검은 두건에 푸른 적삼 차림으로 옥 같은 얼굴에 웃음을 띠고 나와 뵈니, 태위가 웃으며 말하였다. \"조카가 변하여 일등 명창이 되고 명창이 변하여 조카가 되니, 남녀를 바꾸는 것이 이렇게 쉬우냐.\" 하며 크게 웃었다. 생도 크게 웃고 모시고 앉으니 태위가 웃으며 물었다. \"그 사이 봄빛은 어떠하더냐?\" 생이 소저가 곡조를 평론하던 이야기를 모두 아뢰니 태위가 크게 놀라 말하였다. \"소저가 어찌 이렇게 밝고 슬기로운고. 그 자색은 들었으나 이러한 줄은 몰랐으니 참으로 기특하도다.\" 하며 각별히 칭찬하였다. 생은 봉구황곡을 타던 이야기도 하려다가 망령되다고 여길까 두려워 끝내 숨기고, 종일 이야기하다가 밤이 깊은 뒤 초당에 돌아왔다. 최 소저의 용모와 재덕을 못내 그리워하며, 또 장 소저를 생각하고 한탄하였다. \"장 소저가 살았더라면 숙녀 한 쌍을 두고 즐길 것을, 귀신이 사람의 자격을 시기하여 청춘의 원한을 끼쳤도다.\" 하며 탄식해 마지않았다.","sp":[[25,27,"P","석 태위"],[90,92,"P","석 태위"],[188,190,"P","석 태위"],[220,224,"P","이 소저"],[247,249,"P","석 태위"],[406,410,"P","최씨"],[432,436,"P","장설빙"],[451,455,"P","장설빙"]]},{"c":1,"sub":"","t":"한편, 최 소저는 병을 핑계하고 침소로 돌아와 크게 의혹하여 종일 근심이 가득하고 마음을 진정하지 못하였다. 시비 춘빙이 여쭈었다. \"소저께서 오늘 잔치에 다녀오신 뒤로 근심이 얼굴에 가득하시니 무슨 까닭이 있사옵니까?\" 소저가 한참 생각하다가 말하였다. \"너도 보았겠지만 오늘 거문고 타던 여악사가 아무래도 수상하여 나갔던 일을 후회하노라.\" 춘빙이 위로하였다. \"그 사람은 본래 석 태위 댁 가인이니 의심하지 마소서.\" 소저가 또 말하였다. \"분명 벌과 나비가 꽃향기를 찾아 엿본 것이다. 그렇지 않으면 굳이 봉구황곡을 탔겠느냐.\" 춘빙이 그 까닭을 묻자 소저가 탄식하며 말하였다. \"그 미인이 처음에 여러 곡조를 타다가 대순의 남훈곡을 타기에 매우 좋게 여겨 다른 곡조를 구하지 않았는데, 스스로 원하여 또 한 곡조를 탔다. 이는 봉(鳳)이 천하를 두루 다니며 황(凰)을 구하다가 만나지 못하더니 이제 만나 즐기는 소리라. 내가 매우 놀라 자세히 보니, 그 미인이 비록 절묘하나 기운이 웅장하고 소리 가운데 은연히 천지의 조화를 품었으니 반드시 여자가 아니다. 내가 남의 꾀에 빠져 얼굴을 들고 마주하였으니 참으로 부끄럽도다.\"","sp":[[4,8,"P","최씨"],[64,66,"P","춘빙"],[193,195,"P","춘빙"],[214,218,"P","석 태위"],[300,302,"P","춘빙"]]},{"c":1,"sub":"","t":"춘빙도 의혹하여 서로 이상하게 여기며 탄식하는데, 부인이 들어와 물었다. \"체하였다 하여 몹시 염려하였더니 금방 나은 것을 보니 다행이구나.\" 소저가 대답하였다. \"잠깐 앓은 병이 어찌 오래가겠사옵니까.\" 승상이 웃으며 말하였다. \"어찌 잠깐이라 하느냐?\" 그러자 춘빙이 여쭈었다. \"소저께서 미친 봉황의 그림자가 방에 일어나는 바람에 놀라신 기운이 불편하셨는데 이제 나으셨습니다.\" 승상이 그 곡절을 몰라 다시 물으니 춘빙이 다시 아뢰었다. 승상 부부가 크게 의혹하여 한참 말이 없었다. 소저가 옷깃을 여미고 말하였다. \"그 미인의 얼굴이 수상할 뿐 아니라 봉황곡을 탔으니, 다만 나갔던 일만 한탄스럽사옵니다.\" 승상이 웃으며 말하였다. \"이는 경박한 자의 행실에 불과하다. 너는 잘못한 것이 없으니 어찌 꺼리겠느냐. 그러나 그 미인이 간 곳이 있으니 내가 석공을 보고 물어보리라.\" [?]","sp":[[0,2,"P","춘빙"],[148,150,"P","춘빙"],[235,237,"P","춘빙"],[425,427,"P","석 태위"]]},{"c":1,"sub":"","t":"곧 석 태위의 집에 가니 태위가 맞아 반기며 말하였다. \"명공께서 누추한 곳에 왕림하시니 감사함을 이기지 못하겠습니다.\" 승상이 말하였다. \"일전에 잔치에서 초연의 거문고를 잊지 못하여 다시 듣고자 왔으니 청컨대 잠깐 불러 주시오.\" 태위가 크게 놀라 미처 대답할 말을 생각하지 못하다가 이윽고 대답하였다. \"하찮은 소리를 명공께서 이렇게 아껴 주시니 감격스럽습니다만, 잔치 자리를 떠나던 날 훌쩍 고향으로 가 버렸으니 승상께서 생각해 주시는 것이 속절없게 되었습니다.\" 승상은 소저의 말을 들었으므로 매우 의심하여 참으로 꼭 찾고자 하였는데, 태위가 둘러대는 것을 보고 더욱 의혹하여 말하였다. \"그러면 언제 다시 오겠소?\" 태위가 웃으며 말하였다. \"달 속의 계수나무가 조용함을 버리고 산으로 갔으니 어찌 기꺼이 다시 오기를 바라겠습니까.\" 승상도 그가 거절하는 것을 의아히 여겨 다시 말을 하지 않았다. [?]","sp":[[2,6,"P","석 태위"],[14,16,"P","석 태위"],[131,133,"P","석 태위"],[305,307,"P","석 태위"],[351,353,"P","석 태위"]]},{"c":1,"sub":"","t":"그때 문득 한 소년이 밖에서 들어오다가 피하여 나가니 승상이 물었다. \"저는 어떤 소년이오?\" 태위는 속으로 당황하였으나 내색하지 않고 말하였다. \"이는 소제의 생질인데 마침 다니러 왔습니다.\" 승상이 말하였다. \"그러면 상서 김후의 아들이오?\" 태위가 말하였다. \"그렇습니다.\" 승상이 그 풍채를 아껴 보기를 청하니 태위가 마지못하여 생을 불러 승상께 뵈라 하였다. 이때 김생은 마침 나갔다가 무심히 들어오던 차에 태위가 승상과 함께 앉아 있는 것을 보고 황급히 피하여 나갔는데, 문득 부르시므로 들어가 예를 갖추어 뵙고 태위 곁에 앉았다. 승상이 한번 보니 밝은 눈과 꽃 같은 얼굴이 원근에 빛나고 따뜻한 봄볕이 흰 해를 띤 듯하니, 참으로 범상치 않았다.","sp":[[53,55,"P","석 태위"],[138,140,"P","석 태위"],[178,180,"P","석 태위"],[209,211,"P","김희경"],[233,235,"P","석 태위"],[293,295,"P","석 태위"]]},{"c":1,"sub":"","t":"승상이 크게 놀라 다시 보니 전에 본 얼굴이 있으므로 매우 이상히 여겨 태위를 돌아보며 말하였다. \"현질은 곤륜산 가운데의 호걸이라 세상에 미칠 이가 없겠구려. 그런데 일찍이 마음으로 맺은 바가 없는데도 어찌 반가운 마음이 드는 듯하니 무슨 까닭이오?\" 태위가 살짝 웃으며 말하였다. \"평생 처음 보는데 어찌 구면이 되겠습니까.\" 하고 대답하였으나 웃음을 참지 못하여 일행이 크게 웃었다. 생도 옥 같은 얼굴에 웃음을 머금고 태위를 보는데 수상한 기색이 있었다. 승상이 크게 의혹하여 눈을 들어 태위와 생을 보며 한참 머뭇거리다가, 환히 깨닫고 무릎을 치며 크게 웃었다. \"틀림없이 전날 잔치에 왔던 소년이 아니냐. 어찌 모르는 체하며, 예법을 버리고 방탕한 짓을 하여 세상을 속이는 것이 이렇게 심하냐?\" 생은 당황하여 옥 같은 얼굴에 붉은빛이 가득하고 대답할 말이 없었다. [?]","sp":[[40,42,"P","석 태위"],[142,144,"P","석 태위"],[199,201,"P","소세필"],[238,240,"P","석 태위"],[277,279,"P","석 태위"]]},{"c":1,"sub":"","t":"태위도 묵묵히 있다가 크게 웃으며 말하였다. \"명공께서는 어찌 이렇게 실성하셨습니까? 이 아이는 바로 김평장의 아들이요 나의 생질입니다. 검은 두건에 푸른 적삼이 뚜렷한데 어찌 남녀를 분별하지 못하십니까? 이는 그 소년의 자색을 잊지 못하여 이렇게 상사병을 얻어 눈이 흐려지신 것이니, 소저 또한 같은 마음일 것입니다. 그렇다면 어찌 일찍 혼사를 허락하지 않으셨습니까?\" 승상이 이에 금빛 부채를 들어 태위를 치며 하늘을 우러러 크게 웃었다. \"내 이미 환히 알고 있는데 그대는 어찌 사람을 속이오? 전날의 소년이 오늘의 김생이라. 내가 그대의 꾀에 빠졌거니와, 그대는 밝은 군자라면서 방황하는 아이를 막지 않고 도리어 경박한 행실로 남의 규방을 엿보게 하였으니 이것이 무슨 군자의 도리요?\" [?]","sp":[[0,2,"P","석 태위"],[57,60,"P","김평"],[225,227,"P","석 태위"],[292,294,"P","김희경"]]},{"c":1,"sub":"","t":"태위는 이미 숨기지 못할 줄 알고 정색하고 대답하였다. \"명공의 거울이 천 리를 비추니 소제가 어찌 털끝만큼이라도 숨기겠습니까. 평장이 벼슬을 버리고 고향에 내려간 뒤 이 조카를 낳았는데, 타고난 성품이 준수하여 하는 일이 기이하였습니다. 행여 봉황이 까마귀와 짝을 맺을까 염려하여 소제에게 보내며 널리 숙녀를 구해 달라 청하였기에 두루 물었습니다. 그러다 듣자오니 명공께서 따님을 두셨는데 태임과 태사의 덕행과 강양(康楊)의 자색이 있다 하므로 혼인을 구하고자 하였으나, 외람되게 여기실까 머뭇거렸습니다. 그런데 조카가 인륜에서 남다른 도량이 있어 어떤 여자든 보지 못한 여자는 아내로 삼지 않으려 하므로, 그 외람됨을 꾸짖었으나 그 뜻을 막지 못하여 망설이던 중에 마침 명공의 밝으신 눈을 가리게 되었으니 황공하옵니다. 그러나 감히 중매를 보내지 못하고, 요행히 급제하여 공명을 이룬 뒤에 명공의 사랑을 입을까 하였는데 뜻밖에 행적이 탄로 나니 부끄러움을 이기지 못하겠습니다.\" [?]","sp":[[0,2,"P","석 태위"],[72,74,"P","김평"]]},{"c":1,"sub":"","t":"승상이 다 듣고 딸의 총명함에 속으로 탄복하였다. 또 김생의 사람됨은 헤아릴 수 없으니 봉이 황의 짝이라, 어찌 흠잡을 것이 있겠는가. 크게 웃으며 말하였다. \"평장은 나와 같은 해에 급제한 벗이요 나의 지음이라, 또 가문도 서로 걸맞으니 어찌 외람될 것이 있겠소. 그대의 뜻이 이러하다면 명석한 조카의 공명은 그 손안에 있을 터이니 걱정할 것이 없소. 어서 날을 받아 사위를 맞으리다.\" 태위가 기쁨을 이기지 못하여 사례하였다. \"명공의 두터운 은혜가 이러하시니 어찌 감사하지 않겠습니까. 언약을 굳게 정하시니 황공함을 이기지 못하겠습니다.\"","sp":[[30,32,"P","김희경"],[90,92,"P","김평"],[218,220,"P","석 태위"]]},{"c":1,"sub":"","t":"승상이 이에 김생을 나오라 하여 손을 잡고 웃으며 말하였다. \"방탕한 아이가 어린 나이에 이런 외람된 생각을 하여 어른을 속이느냐. 그때 명창의 이름은 초운이요 자는 조연이라 하더니, 조연이 꾸미기가 어찌 그리 쉬우며 비단 치마와 붉은 치마는 어디 두고 초록 도포와 푸른 적삼을 걸쳤느냐. 네 죄는 용납하지 못할 것이나 내 타고난 성품이 너그러워 마음에 두지 않겠다. 이후로는 다시 방탕한 생각을 품지 마라. 그러나 내 딸은 네가 이미 본 바이니 욕될 것이 없을 것이다. 백년을 서로 저버리지 마라.\" 말을 마치고 손뼉을 치며 크게 웃었다. 생이 일어나 절하며 사례하였다. \"대인께서 소생의 어리석음을 마음에 두지 않으시고 이렇게 아끼시어 방탕한 죄를 용서하시니 황공하고 감사함을 이기지 못하겠습니다. 게다가 소생의 한미함을 허물하지 않으시고 사위로 삼으려 하시니 감격하기 그지없습니다. 군자가 어찌 신의를 저버리고 신의 없고 의롭지 못한 일을 하겠습니까마는, 분부가 이에 미치시니 몸 둘 바를 모르겠사옵니다.\" 말마다 엄정하고 씩씩하니 태위의 기쁨과 승상의 사랑을 헤아릴 수 없었다.","sp":[[7,9,"P","김희경"],[525,527,"P","석 태위"]]},{"c":1,"sub":"","t":"날이 저물자 승상이 집으로 돌아와 안채에 들어가 부인께 김생의 이야기를 전하였다. 부인도 놀라며 칭찬하였으나 속으로는 한탄하였다. \"딸아이의 말이 이처럼 슬기롭고 김생의 화려하고 방탕함이 또한 이러하니 딸아이의 일생이 고단하겠구나.\" 하며 오히려 근심하였다. 승상이 웃으며 말하였다. \"이는 참으로 풍류 있는 선비라 어찌 방탕하다 하겠소. 이번 사정을 들으면 자연히 방탕한 뜻으로 보이겠지요. 부인은 의심하지 마시오. 오늘 그 사람됨을 보니 끝내 한 여자로 늙을 기상은 아니나, 또한 그 어질고 밝음이 부귀 때문에 신의를 저버릴 사람은 아니오. 그러므로 내 뜻을 이미 정하였으니 부인은 염려하지 마시오.\" 부인이 비록 기쁘지는 않았으나 어찌할 수 없어 함께 기뻐하였다.","sp":[[31,33,"P","김희경"],[91,93,"P","김희경"]]},{"c":1,"sub":"","t":"이때 소저가 마침 난간에 기대어 앵무새와 놀고 있는데 춘빙이 들어와 아뢰었다. \"소저의 밝으심은 해와 달 같으십니다. 전날 잔치에서 거문고 타던 미인이 석 태위의 외조카요 하람의 김생이라 하더이다.\" 소저가 크게 놀라 물었다. \"네가 어떻게 아느냐?\" 춘빙이 승상의 말씀을 전하고 또 혼인이 정해졌다는 것을 전하니, 소저는 더욱 놀라 다시 말을 하지 않고 침소로 돌아갔다.","sp":[[30,32,"P","춘빙"],[85,89,"P","석 태위"],[100,102,"P","김희경"],[141,143,"P","춘빙"]]},{"c":1,"sub":"","t":"이때 석 태위는 혼인을 정하고 곧 날을 받아 예를 올리고자 하였다. 한편으로 영천에 기별하여 평장을 기다려 혼례를 치르려 하였는데, 마침 황상께서 평장의 재주를 아끼시어 다시 벼슬을 내리셨다. 평장은 명을 받들었으나 벼슬에 뜻이 없어 사양하려다가 마지못하여 가족을 거느리고 서울로 올라가 황제께 숙배하였다. 황상이 매우 기뻐하며 금은과 비단을 많이 내리시니 평장이 사은하고 물러나 석 태위 집에 돌아왔다. 태위와 부인이 생과 함께 맞이하여 서로 반가움을 이기지 못하는 가운데, 희경의 혼인이 정해진 일과 그간 지낸 이야기를 늘어놓으며 웃고 즐거워하였다. 평장이 태위를 향하여 무수히 사례하기를 그치지 않으니 태위가 웃으며 말하였다. \"이는 다 조카가 특출한 덕이요 형님의 복이니 어찌 사례를 받겠습니까.\"","sp":[[3,7,"P","석 태위"],[52,54,"P","김평"],[77,79,"P","황제"],[82,84,"P","김평"],[108,110,"P","김평"],[161,163,"P","황제"],[172,174,"P","황제"],[200,202,"P","김평"],[213,217,"P","석 태위"],[227,229,"P","석 태위"],[267,269,"P","김희경"],[310,312,"P","김평"],[314,316,"P","석 태위"],[340,342,"P","석 태위"]]},{"c":1,"sub":"","t":"곧 날을 받아 혼례를 올리는데, 생이 옥 같은 얼굴과 영웅다운 풍채에 혼례복을 갖추고 금 안장 백마를 타고 의젓하게 나아가니 그 위의가 대단하였다. 최씨 댁에 이르러 하늘께 절하고 혼례 자리에 나아가 맞절을 마친 뒤 눈을 들어 소저를 보니, 옥 같은 살결과 붉은 얼굴에 온갖 자태를 갖추어 그 곱고 단정한 거동과 화려한 모습은 이루 다 말할 수 없었다. 생이 한번 보고 마음이 황홀하여 취한 듯 미친 듯하였다. 이어 신방에 나아가 상을 물리고 바깥채로 나가니 자리에 가득한 이들이 모두 칭찬하였다. 이윽고 밤이 되어 신방에 들어가니 소저가 일어나 맞았다. 서로 동서로 나누어 자리를 정하자 시비가 비단 휘장을 드리웠다. 촛불을 끄고 소저의 가녀린 손을 이끌어 잠자리에 나아가니 두 사람의 물고기와 물 같은 즐거움이 깊었다. 생은 최씨를 아내로 맞아 평생의 소원을 이루었으므로 부부가 화락하고 부모를 효성으로 봉양하며 세월을 보냈다.","sp":[[83,85,"P","최씨"],[408,410,"P","최씨"]]},{"c":1,"sub":"","t":"세월이 빨라 이듬해 봄이 되었다. 황제가 여러 번 과거를 열었으나 인재를 뽑지 못하여 한탄하셨는데, 하루는 태사관이 아뢰었다. \"요사이 천문을 보오니 문창성이 장안을 비추고 있사오니 반드시 기이한 사람이 있을 것이라, 그러므로 아뢰옵니다.\" 황상이 매우 그럴듯하게 여겨 곧 과거를 여시고 천하의 선비를 다 모아 춘경전에 나와 앉으시어 글제를 거셨다. 글제가 어려워 이백과 두보의 문장이나 조자건의 칠보시 재주라도 능히 짓지 못할 만하였다. 여러 선비가 붓과 벼루를 거두어 돌아가는 자가 무수하였다. 생은 과거 마당에서 구경하며 선비들의 용렬함을 속으로 웃다가, 전각 위에서 북소리가 울리자 붓과 벼루를 꺼내 단숨에 써 내려가 잠깐 사이에 지어 바치고 두루 거닐었다. 그런데 문득 전각 위에서 글 두 장을 먼저 비점을 찍어 휘장에 걸고 부르는 소리가 전각을 울렸다. 과거장의 모든 선비가 놀라며 칭찬하고 다투어 구경하니, 이는 김생과 장 소저가 지은 글이었다. 구절구절이 으뜸이요 글자글자가 주옥이라, 용이 날고 뱀이 오르는 듯하여 귀신을 놀라게 하니 여러 선비가 모두 탄복하며 어찌할 줄 몰랐다.","sp":[[19,21,"P","황제"],[85,87,"P","김희경"],[135,137,"P","황제"],[462,464,"P","김희경"],[466,470,"P","장설빙"]]},{"c":1,"sub":"","t":"이윽고 황제가 좌우를 돌아보며 말씀하셨다. \"이는 반드시 천신이로다. 인간 세상에 어찌 이런 재주가 있으리오. 짐이 처음에 한 사람을 뽑고자 하였는데 이 글 두 장이 별로 우열이 없으니 짐이 결단하지 못하겠노라. 경들은 의논하여 결단하라.\" 여러 신하가 일시에 나아가 보니 문채가 황홀하고 뜻이 활달하여 털끝만 한 흠도 없으니 모두 입을 다물고 말이 없었다. 승상 최후가 아뢰었다. \"두 사람을 불러 사람됨을 보아 뽑는 것이 마땅할까 하옵니다.\" 황상이 옳게 여겨 곧 두 사람을 불러 보시는데, 봉한 이름을 뜯어 보니 하나는 하람 김희경이요 하나는 청주 장수정이라. 부르는 소리가 전각을 울렸다.","sp":[[4,6,"P","황제"],[32,34,"P","도인"],[204,206,"P","최후"],[250,252,"P","황제"],[297,300,"P","김희경"],[310,313,"P","장설빙"]]},{"c":1,"sub":"","t":"이때 두 사람은 글을 바치고 나와 있다가 이름 부르는 소리를 듣고 나아갔다. 두 사람의 기상과 풍채가 빼어나 이백과 두보의 풍채를 지녔다. 두 사람이 함께 나아가 엎드려 서로 보며 말을 하지 못하였다. 황상이 보시고 칭찬하셨다. \"세상에 어찌 조자건이 있으며 두공부(두보)의 짝이 있는고. 참으로 하늘이 짐을 도우시어 이 두 사람을 내셨도다. 이는 참으로 나라의 큰 다행이니 어찌 기쁘지 않으리오. 짐이 처음에 한 사람을 뽑고자 하여 두 사람을 부른 것은 그 사람됨을 보아 정하려 함이었는데, 두 사람을 보니 당당한 나라의 기둥이 될 신하라 참으로 둘 다 버리지 못하겠노라. 두 사람을 함께 쓰려 하니 경들의 생각은 어떠하냐?\" 여러 신하가 감히 막지 못하여 일시에 아뢰었다. \"폐하께서 나라의 기둥 같은 신하를 얻으셨으니 국가의 큰 다행이옵니다.\" 황상이 크게 기뻐하여 두 사람에게 벼슬을 내리시는데, 김희경은 한림학사로, 장수정은 문현각 태학사로 삼으셨다. 두 사람이 일시에 사은숙배한 뒤 물러 나오는데, 옥 같은 얼굴과 영웅다운 풍채에 어사화를 꽂고 푸른 적삼을 펄럭이며 대궐 문밖으로 나오니, 구경하는 사람마다 칭찬하지 않는 이가 없었다.","sp":[[113,115,"P","황제"],[420,422,"P","황제"],[450,453,"P","김희경"],[462,465,"P","장설빙"]]},{"c":1,"sub":"","t":"한림이 속으로 생각하기를 '부친의 이름이 자영이라 하였으니...' 하며 장 소저를 생각하고 조용히 학사를 돌아보며 말을 묻고자 하였으나, 평장과 최 승상이 계시므로 사사로운 이야기를 하지 못하고 각각 집으로 돌아갔다. 이때 석 부인과 일가친척이 못내 기뻐하였다. [?]","sp":[[40,44,"P","장설빙"],[77,79,"P","김평"],[81,85,"P","최후"],[125,129,"P","석 부인"]]},{"c":1,"sub":"","t":"한편, 장 소저는 설낭, 영춘 등과 함께 서울에 머물며 과거를 기다렸다. 그런데 나라에 일이 있어 과거가 물려지자 조용히 내려가려 하였으나, 태학의 선비들이 소저의 재주를 아껴 머무르게 하고 보내지 않았다. 그리하여 주인과 종이 객관에 머물다가 이듬해 봄이 되어 다시 과거령이 반포되었다. 소저가 과거장에 나아가 붓과 벼루를 꺼내고 다시 생각하였다. '내 몸이 여자라 아버님의 원한을 씻을 길이 없으니, 요행히 급제하면 원한을 다 풀 수 있을까.' 하고 글을 지어 바쳤더니, 잠깐 사이에 이름 부르는 소리가 들렸다. 자세히 들으니 자기 이름이라 기꺼이 대궐 섬돌로 나아가는데, 김생도 함께 급제하였다. 김생과 함께 섬돌 앞에 이르러 엎드리며 소저가 잠깐 보니 오랜 벗을 만난 듯 반가움이 그지없었으나 내색하지 않았다. 황상이 보시고 크게 칭찬하시며 문현각 태학사를 내리시니, 사은하고 물러 나와 김생과 함께 걸었다. 정회가 매우 간절하였으나 서로 묻는 말 없이 바삐 돌아갔다. 먼저 말을 거는 것이 옳지 않다 여겨 잠자코 여관으로 돌아왔다.","sp":[[4,8,"P","장설빙"],[10,12,"P","설낭"],[14,16,"P","영춘"],[86,90,"P","이 소저"],[323,325,"P","김희경"],[337,339,"P","김희경"],[402,404,"P","황제"],[445,447,"P","김희경"]]},{"c":1,"sub":"","t":"설낭과 영춘 등이 놀라 맞으며 눈을 들어 보니, 소저가 머리에 어사화를 꽂고 몸에 푸른 적삼을 걸치고 손에 옥홀을 잡고 천천히 들어오니 당당한 명사였다. 영춘 등이 속으로 크게 놀라 그 망령됨을 간하고자 하였으나 축하하는 분위기가 번화하여 감히 드러내지 못하고 조용해지기를 기다렸다. 이윽고 사람들이 다 흩어지자 학사가 촛불을 밝히고 책상에 기대어 깊이 생각하는 빛이 있었다. 영춘 등이 나아가 가만히 여쭈었다. \"소저께서 처음 이곳에 오신 것은 다만 김생의 종적을 알아보고 잠시 구경하려던 것인데, 이제 어찌 된 곡절로 정말 급제하여 대궐 섬돌을 밟으셨습니까? 모르겠사옵니다, 나중 일을 어찌하려 하시옵니까?\" [?]","sp":[[0,2,"P","설낭"],[4,6,"P","영춘"],[86,88,"P","영춘"],[211,213,"P","영춘"],[253,255,"P","김희경"]]},{"c":1,"sub":"","t":"학사가 서글피 대답하였다. \"이는 나의 본뜻이 아니다. 부득이한 것은 아버님의 원한을 풀고자 함이니, 선산에 나아가 부모님의 혼령을 위로하면 비록 죽더라도 무슨 한이 있으리오.\" 그리고 김생이 같은 방에 급제하여 한림이 되었다는 것을 말하니, 영춘 등이 또 물었다. \"전날의 굳은 약속은 어찌하려 하시옵니까?\" 소저가 살짝 웃으며 말하였다. \"김생이 비록 장안에서 말 위에 높이 앉았으나 참으로 나를 모를 것이요, 분명 찾을 일이 있을 것이다. 나도 대답할 말이 있을 터이니 전날의 굳은 약속은 저버리지 않으리라. 너희는 부디 근심하지 마라.\" [?]","sp":[[104,106,"P","김희경"],[136,138,"P","영춘"],[192,194,"P","김희경"]]},{"c":1,"sub":"","t":"이럭저럭 밤이 깊었다. 학사가 촛불을 밝히고 원정(原情)을 지어, 날이 새기를 기다려 대궐 아래에 나아가 글을 올렸다. 상서의 억울함을 풀어 주시고, 또 고향에 돌아가 부모님의 외로운 혼을 위로하게 해 달라고 아뢰었다. 황상이 다 보시고 그 정에 감동하시어 장공에게 청주후를 추증하시고, 곧 원통하게 죽은 것을 특별히 사면하셨다. 한 달 말미를 주시며 속히 돌아와 짐을 도우라 하시고, 아울러 상서의 영혼을 위로하라고 금은을 많이 내리셨다. 학사가 성은에 감사하고 물러 나와 행장을 차렸다.","sp":[[123,125,"P","황제"],[144,146,"P","장자영"],[149,152,"P","장설빙"]]},{"c":1,"sub":"","t":"그때 문득 김 한림이 오신다고 아뢰었다. 학사가 허둥지둥 의관을 갖추고 들어오시라 청하였다. 한림이 들어와 예를 마치고 자리를 정한 뒤 서로 사귐을 맺고 회포를 풀었다. 한림이 칭송하며 말하였다. \"듣자오니 존부께서 억울하게 원통한 죽음을 당하시어 조정의 모든 이가 한탄하지 않는 이가 없었는데, 이제 현형께서 천은을 입으시어 원한을 풀고 후작을 받으셨으니 효심을 충분히 이루셨습니다. 상서의 혼령이 즐거워하실 것이라 그 정성에 속으로 탄복합니다. 그런데 전에는 현형이 계신다는 말을 듣지 못하였는데 이제 보니 세상 사람들이 헛말을 믿었던 것이로군요. 그러나 존대인께서 북해로 가실 때 뒤를 따르지 않으신 것은 무슨 까닭이 있었습니까?\"","sp":[[6,10,"P","김희경"]]},{"c":1,"sub":"","t":"학사가 탄식하였다. \"형께서 어찌 이렇게 다 아시고 마음 써 주시니 감사함을 이기지 못하겠습니다. 어찌 마음을 조금이라도 숨기겠습니까. 소제는 부모님 늘그막에 태어나 지극한 사랑을 받았는데, 하루는 관상 보는 도인을 만났더니 명이 짧다 하며 남에게 주어 기르라 하였습니다. 그래서 두 살 때 여남 땅의 이 참정께 길러 주기를 청하였습니다. 참정도 아들이 없어 소제를 거두어 기르시며 근본을 끝내 숨기셨는데, 부친이 세상을 떠나시자 그제야 천륜을 찾지 못하여 원통하게 귀양 가 돌아가신 말씀과 처음부터 끝까지의 사연을 일러 주셨습니다. 소제가 비로소 듣고 천지가 망극하여 가슴이 오그라드는 듯하였습니다. 죽기로 북해에 다다라 시신을 옮겨 선산에 안장하고 삼 년을 지낸 뒤, 남은 목숨을 지금까지 부지해 왔습니다. 마침 과거를 당하여 꼭 천운을 바란 것은 아니나 요행히 급제하면 부친의 남은 한을 씻을까 하였는데, 하늘이 감동하시어 소제의 첩첩한 소원을 풀었으니 죽어 지하에 가더라도 한이 없사옵니다.\"","sp":[[117,119,"P","도인"],[169,173,"P","이영찬"],[190,192,"P","이영찬"]]},{"c":1,"sub":"","t":"이럭저럭 이야기가 길어지니 서로 속마음이 비치어 정의가 자못 깊어졌다. 한림은 장 소저의 남긴 모습이 학사와 비슷하므로 그리운 마음을 금치 못하여 은근히 소저의 일을 꺼내 물었다. 학사가 짐작하고 대답하였다. \"누이가 부친을 찾아 북해로 가다가 도중에 몸을 버려 푸른 물결에 물고기 밥이 되었다 하나 지금까지 찾지 못하였으니, 한 조각 원통한 마음을 금치 못하여 사실을 아뢰는 것입니다.\" 말을 마치자 첩첩한 시름을 진정하지 못하여 두 줄기 눈물이 옷깃을 적셨다. 한림이 다 듣고 슬픔을 참지 못하여 소매로 낯을 가리고 목메어 탄식하니 슬픈 눈물이 옷깃을 적셨다. 봄바람에 꽃과 버들 같던 얼굴이 문득 변하여 처량하고 서글펐다. 학사가 속으로 그 마음에 감격하였으나 얼굴빛을 고치고 몸을 굽혀 사례하였다. \"형께서 우연히 물으신 데 대해 사실을 말씀드렸더니 이렇게 마음 아파하시니 감사함을 이기지 못하겠습니다.\" [?]","sp":[[44,48,"P","장설빙"],[273,275,"P","소세필"]]},{"c":1,"sub":"","t":"한림이 한참 말을 못하다가 겨우 정신을 차려 말하였다. \"현형께서 진정을 다 말씀하시니 소제도 마음속에 쌓인 회포를 어찌 숨기겠습니까. 소제가 지난번 서울로 길을 가다가 형초 객점에 이르러 마침 쉬고 있었는데, 우연히 한 행차를 만났습니다. 과연 형의 말씀처럼 행색이 초라하였고, 다만 유모와 시비를 데리고 가다가 주점에 머물렀는데 서로의 처소가 멀지 않았습니다.\"","sp":[[160,162,"P","설낭"]]},{"c":1,"sub":"","t":"\"그 시비 영춘이 소제의 용렬한 사람됨을 잘못 사모하여 혼인의 뜻을 정하고 소제에게 이러이러하게 말하기에, 그 마음을 짐작하니 영춘의 정성이 참으로 기특하였고, 그 사람이 헛말을 하지 않을 것이었습니다. 소제는 외람됨을 잊고 굳은 약속을 정하였는데, 이는 인륜의 큰일이라 갑자기 시비의 말[□]만 듣고 신의를 지키는 것이 옳지 않아, 비록 예는 아니나 누이의 목소리를 직접 듣고 정하기를 청하였습니다. 누이는 당대의 숙녀라 큰 의리를 정하는데 어찌 세속의 태도를 꺼리겠습니까. 순순히 허락하고 춘랑을 통해 소제의 어리석음을 마음에 두지 않고 평생을 함께할 뜻을 완전히 정하니, 소제가 그 활달함에 탄복하였습니다. 그리고 신표를 나눌 때 소제는 한 조각 [□]증(백옥 서진)을, 누이는 금가락지 한 짝을 바꾸어 서로 백년가약을 길이 맹세하였으니 천지신명이 길이 증명하는 바입니다. 소제는 누이의 단심을 반석같이 믿었으나 서로 길 가는 나그네라 지체할 길이 없어, 영춘 등에게 보중하라 부탁하고 서울과 시골로 길을 나누어 한번 이별한 뒤로 소식이 아득하였습니다.\"","sp":[[6,8,"P","영춘"],[71,73,"P","영춘"],[276,278,"P","영춘"],[482,484,"P","영춘"]]},{"c":1,"sub":"","t":"\"소제는 한결같은 간절한 생각과 그 외로움을 밤낮으로 그리다가 부모님께 아뢰고 탁주의 정 시랑을 찾아갔더니, 시랑은 이미 세상을 떠났고 부인도 외조카 유랑을 찾아갔으며, 누이의 종적은 아득하여 아는 이가 없었습니다. 소제는 죽기로 사방을 돌아서라도 거처를 찾고자 마음을 정하고 탁군의 유랑을 찾아갔으나 종적을 모른다 하였고, 또 북해를 찾아가니 상서께서는 이미 세상을 떠나시고 영구를 청주 산소로 모셔 갔다 하였습니다. 소생은 어찌할 바를 몰라 크게 낙심하여 또 누이를 찾아 물으려고 청주로 가다가 벽해수 가에 이르렀는데, 문득 한 바위 위에 필적이 있으므로 이상히 여겨 보니 천만뜻밖에 누이의 필적이었습니다. 같은 달 같은 날에 주인과 종 세 사람이 물에 빠져 죽노라 한 필적이 분명하니, 다 보고 나서 어찌 마음이 온전하겠습니까. 그 뒤를 따라 혼백이라도 위로하고자 하였으나 부모님이 계시므로 차마 그러지 못하고, 다만 술과 음식을 갖추어 그 외로운 혼을 위로하고 돌아왔습니다. 마음으로는 혼자 흐느끼며 그 정성을 저버리지 않고자 하였으나, 부모님께 외아들로 믿으시는 바가 소제 한 몸뿐이라 후사를 끊는 일이 중하고, 또 부모님을 위하는 까닭에 지금의 좌승상 최후의 딸과 혼인하여 예를 올린 지 거의 석 달입니다.\"","sp":[[48,52,"P","정 시랑"],[591,594,"P","최후"],[595,597,"P","최후"]]},{"c":1,"sub":"","t":"\"그러나 누이의 정신을 한시도 잊을 길이 없는 가운데, 푸른 물결에 주인 없는 외로운 혼이 되어 시신도 찾지 못하였으니 밤낮으로 생각할수록 간담이 흩어지고 깊은 원한이 되어 자나 깨나 잊지 못하였습니다. 그런데 오늘 현형을 뵈니 누이의 얼굴과 비슷하므로 슬픔을 금치 못한 것인데, 현형께서 정회를 다 펴시니 어찌 슬프지 않겠습니까. 비록 하늘이 무너지고 땅이 꺼져도 이 희경이 죽기 전에는 뼈에 새기고 마음에 새겨 잊지 못할 것입니다. 누이는 이미 세상을 떠났으나 이제 형이 계시니, 서로 관중과 포숙 같은 사귐을 맺고 목숨을 함께할 정의가 있다면 누이와의 신의를 저버리지 않는 것이 될 것입니다. 길이 생각하시어 소제의 간절한 정을 버리지 마소서.\" 말을 마치며 길게 탄식하니 눈물이 옥 같은 얼굴에 흘러, 그 슬퍼하는 모습을 차마 볼 수 없었다.","sp":[[207,209,"P","김희경"]]},{"c":1,"sub":"","t":"학사가 속으로 생각하였다. '나의 거처를 알고자 천 리를 지척으로 삼아 사방을 다녔으니 그 신의는 탄복할 만하다.' 또 스스로 생각하였다. '그사이 세상일이 이렇게 바뀌었구나. 그가 이미 아내를 얻었다 하니 내 근본을 깊이 숨겨야겠다. 최씨가 어진지 어리석은지는 모르나, 아내를 얻은 뒤에도 나를 생각하고 그 은정이 이러하니 참으로 마음에 새길 일이다.' 슬픔을 진정하지 못하여 눈물을 흘리며 사례하였다. \"비록 남매의 정이 있었으나 이런 사정이 있는 줄은 몰랐는데, 이제 형의 말씀을 들으니 소제의 간담이 오그라드는 듯하니 어찌 마음이 온전하겠습니까. 하물며 죽은 사람을 이렇게 잊지 않으시니 형의 신의는 천고에 드문 것이라 어찌 감사하지 않겠습니까. 소제가 선산에 가서 부모님의 혼령을 위로하고 돌아와 형을 위해 개와 말 같은 수고도 달게 받아 만분의 일이나마 갚고자 하옵니다.\" 이럭저럭 날이 저물자 서로 하직하고 떠나는데, 한림이 백 번 당부하며 어서 돌아오기를 청하였다.","sp":[[132,134,"P","최씨"]]},{"c":1,"sub":"","t":"학사가 한림을 보내고 안으로 들어오니 설낭과 영춘이 학사께 여쭈었다. \"김 한림의 은정이 이렇게 고마운데 소저께서는 어찌 저버리고 몸을 감추시니 나중을 어찌하려 하시옵니까?\" 소저가 한참 있다가 탄식하였다. \"이것이 다 하늘의 뜻이니 설마 어찌하겠느냐. 그가 이미 내가 죽은 줄 알고 다른 여자를 얻어 새 정이 아직 다하지 않았을 터인데도, 옛 정을 잊지 않고 못내 생각하며 신의를 지키려고 내 자취를 찾아 사방으로 고생이 무수하였던 일은 참으로 고맙지만, 지금은 도리어 우습구나. 그러나 신의 있는 군자라, 그가 아내를 얻었어도 내가 세상에 살아 있는 줄 알면 결코 무심하지 않을 것이다. 내가 이제 장녀(張女)가 무릉도원을 찾듯 하면 그 여자는 반드시 빈 방에서 백두음(白頭吟)을 읊을 터이니 내 어찌 남에게 원한을 끼치겠느냐. 자연히 세월이 오래되어 그들이 여러 자녀를 낳게 되면, 비록 내가 끼어들더라도 그 믿는 바 골육이 있으니 그 뜻이 또한 너그러워질 것이다. 그러므로 내 근본을 감추어 그 여자로 하여금 원한을 품지 않게 하려는 것이니 너희는 근심하지 마라.\" 영춘이 대답하였다. \"소저의 너그러움과 두터운 덕이 이러하시니 소비들의 복이 줄어들까 두렵사옵니다. 그런데 일이 오래되면 이 참정 댁 혼사는 어찌하시겠사옵니까?\" 학사가 살짝 웃으며 말하였다. \"이것도 처리할 도리가 있으니 어찌 미리 염려하겠느냐.\" 학사가 행장을 꾸려 청주로 향하였다. [?]","sp":[[21,23,"P","설낭"],[25,27,"P","영춘"],[40,44,"P","김희경"],[545,547,"P","영춘"],[613,617,"P","이영찬"]]},{"c":1,"sub":"","t":"한편 김 한림은 학사와 작별하고 집에 돌아와 장 소저의 애처롭던 정성을 생각하며 슬픔을 진정하지 못하였다. 최씨의 침소에 들어가 옷을 벗고 다시 바깥채로 나와 책상에 기대어 잇달아 잔을 부어 마셨다. 술이 반쯤 취하자 생각이 더욱 간절하여 비단 주머니를 열고 금가락지를 꺼내 들고 길게 탄식하였다. \"가락지는 뚜렷한데 임자는 어디 갔는고. 이제 가인을 얻었으니 부족할 것이 없으나 그 사람의 은정을 생각하니 어찌 정회를 참겠는가. 슬프다, 남처럼 뭍에서 죽어 시신이라도 있으면 슬픔을 씻고 혼령이라도 위로하련만, 넓은 물결 어디를 향하여 그 외로운 혼을 위로한단 말인가. 애석하다, 백옥 서진은 속절없이 푸른 물결에 묻혔도다.\" 하며 탄식해 마지않았다.","sp":[[3,7,"P","김희경"],[25,29,"P","장설빙"],[60,62,"P","최씨"]]},{"c":1,"sub":"","t":"마침 시비가 이 말을 듣고 최씨에게 전하니 최씨가 서글피 말하였다. \"이는 반드시 평범한 사람이 아니요 틀림없이 명문대가의 인물에 빠진 것이로다. 그러나 모르겠구나, 어떤 여자가 이 지경에 이르렀는가.\" 하며 의아해하던 차에 한림이 들어왔다. 최씨가 일어나 맞으며 잠깐 눈을 들어 보니 옥 같은 얼굴에 시름이 가득하고 불편한 기색이 있었다. 최씨가 매우 민망하여 옷깃을 여미고 물었다. \"첩이 군자를 모신 지 거의 열 달이 되었으나 한시도 시름겨워하시는 빛을 보지 못하였는데, 오늘 얼굴빛이 참담하고 근심이 가득하시니 분명 작지 않은 근심이옵니다. 청컨대 속마음을 숨기지 마소서. 첩이 비록 어리석으나 조금은 군자의 근심을 짐작할 수 있을 것이옵니다.\"","sp":[[15,17,"P","최씨"],[24,26,"P","최씨"],[136,138,"P","최씨"],[191,193,"P","최씨"]]},{"c":1,"sub":"","t":"한림이 두 눈썹을 찡그리며 말하였다. \"부인이 총명하여 사람의 속마음을 비추니 그 밝은 눈에 탄복하겠으나, 이 근심은 부인이 알 바가 아니오. 옥비녀가 강물에 잠기고 은정이 끊어졌으니 비록 하늘이 굽어보신들 어찌할 수 없는 일이오. 부인이 나의 시름을 알아도 소용없고 말해도 쓸데없지만, 매우 마음 써 물으니 어찌 숨기겠소. 회포를 털어놓을 터이니 부디 번거롭게 여기지 마시오.\" 하고 처음 장 소저를 만나던 이야기와 나중에 죽은 사연, 장 학사를 만난 앞뒤 사연을 다 이야기하였다. 최씨가 다 듣고 서글피 옥 같은 얼굴에 근심을 띠며 말하였다. \"가엾도다, 장 소저여. 어찌 된 일인가. 속절없이 넓은 물결에 물고기 밥이 되어 외로운 혼이 물속에 잠겼는가.\" 하며 탄식해 마지않았다. 한림은 속으로 그 사람됨이 이렇게 어질고 밝은 것에 탄복하였으나 내색하지 않고 태연히 사례하였다. \"부인의 어질고 너그러움은 짐작하였으나 이렇게까지 하실 줄은 뜻밖이오.\"","sp":[[219,223,"P","장설빙"],[245,249,"P","장설빙"],[271,273,"P","최씨"],[313,317,"P","장설빙"]]},{"c":1,"sub":"","t":"최씨가 이에 낯빛을 고치며 말하였다. \"군자께서는 어찌 첩의 마음을 작게 여기시어 숨기심이 자못 깊으셨습니까. 이는 다 첩이 어질지 못한 탓이라 도리어 부끄럽사옵니다. 그러나 일이 이러하다면 비록 혼례는 올리지 않았으나 당당한 부부입니다. 구천에 돌아간 혼백이라도 몸 둘 곳이 없어 반드시 김씨 문하에 의탁하였을 터인데, 어찌하여 지금까지 부모님께 아뢰고 예를 세워 주인 없는 영혼을 위로하지 않으시고, 한갓 부인의 어짊만 생각하여 정신만 허비하며 사람의 의심을 끼치셨습니까. 첩이 비록 어리석으나 조상의 제사를 욕되게 하지 않을 것이니, 바라건대 군자께서는 큰 의리를 세우시어 첩의 소원을 따라 주시면 후세에 투기했다는 말을 면할까 하옵니다.\" 한림이 다 듣고 나니 지난 일이 봄꿈에서 처음 깬 듯하였다. 기꺼이 몸을 굽혀 사례하였다. \"부인의 깊은 마음이 이렇게 갸륵하시니 이 사람이 바라던 것보다 더하여 도리어 나의 구구함이 부끄럽소. 부인의 두터운 덕에 탄복하니 어찌 금옥 같은 말씀을 따르지 않겠소.\" 이튿날 이 뜻을 부모님께 아뢰고 장씨의 신위를 세워 사철 제사를 지내니, 최씨가 조금도 게을리하는 일이 없어 평장 부부와 일가친척이 모두 그 어짊에 탄복하였다.","sp":[[0,2,"P","최씨"],[551,553,"P","최씨"],[571,573,"P","김평"]]},{"c":1,"sub":"","t":"한편, 장 학사는 고향에 돌아가 선산에 성묘하고 좌우를 살펴보니 소나무와 대나무는 예와 같아 반기는 듯하였으나, 부모님의 모습은 구천에 가까워 반겨 주실 이가 없고 영화를 사랑해 줄 이도 없었다. 적막한 가운데 외로이 옛일을 생각하며 슬픔을 금치 못하여 크게 통곡하였다. 이럭저럭 묘 아래에서 열흘 남짓 머물다가 여남으로 돌아오니, 슬프다, 한 달 사이에 이 참정이 세상을 떠나 부인이 홀로 소저만 데리고 있었다. 부인이 장생이 급제하여 왔다는 말을 듣고 기쁜 가운데 참정을 생각하며 슬픔을 참지 못하여 한바탕 통곡한 뒤 학사를 안채로 청하였다. 학사가 들어가 부인께 뵈니 부인이 슬픔을 이기지 못하여 목메어 우니, 집안의 하인들이 모두 그 참담함을 슬퍼하였다. 학사가 참정의 영위 앞에 나아가 한바탕 통곡하는데 애통함이 친부모 상과 다름이 없으니, 사람마다 그 두터운 덕을 칭찬하지 않는 이가 없었다.","sp":[[4,8,"P","장설빙"],[199,203,"P","이영찬"],[236,238,"P","장설빙"],[262,264,"P","이영찬"],[275,277,"P","소세필"],[375,377,"P","이영찬"]]},{"c":1,"sub":"","t":"여러 날이 되어 말미의 기한이 차자 이 부인께 하직하며 말하였다. \"소생이 어찌 참정의 영위를 잠시라도 떠나고자 하는 마음이 있겠사옵니까마는, 몸을 이미 나라에 바쳤기에 말미의 기한이 다 되었으니 신하의 도리로 황공하옵니다. 그러므로 부인의 괴로움을 위로하지 못하고 훌쩍 떠나오니 마음이 몹시 서운하옵니다. 바라옵건대 부인께서는 마음을 너그러이 하시어 보중하소서. 세월이 흐르는 물 같으니 삼 년도 덧없을 것입니다. 소생이 그때를 헤아려 부인을 서울로 모셔 백세의 은혜를 만분의 일이나마 갚을 것이니 부인께서는 염려하지 마소서.\" 부인은 감격을 이기지 못하여 다만 눈물로 사례할 뿐이었다. 이에 행장을 꾸려 길을 떠나는데, 학사가 부인께 하직하고 서울에 올라와 황제께 문안한 뒤, 종남산 아래에 집을 크게 짓고 부모님의 사당을 세워 제사를 이으니, 홑몸은 비록 외로우나 상서의 영혼을 위로하게 되어 조금은 마음이 편안하여 세월을 보냈다.","sp":[[20,24,"P","이 소저"],[45,47,"P","이영찬"],[370,372,"P","황제"]]},{"c":1,"sub":"","t":"한편, 한림은 학사와 이별한 뒤 최씨의 뜻을 좇아 장씨 사당을 세우고 날마다 슬픔을 금치 못하며 세월을 지냈다. 그러다 학사가 서울에 왔다는 말을 듣고 곧 찾아가니 학사가 반겨 맞았다. 예를 마치고 자리를 정한 뒤 서로 떨어져 있던 정을 이야기하며 종일 은근히 담소하다가 돌아왔다. 이럭저럭 봄 석 달이 다 지나고 칠월 보름이 되자, 한림이 장 소저의 제사를 지내려고 제찬을 차리고 학사를 청하였다. [?]","sp":[[18,20,"P","최씨"],[191,195,"P","장설빙"]]},{"c":1,"sub":"","t":"이때 학사는 설낭, 영춘과 함께 옛 일을 살피다가 밤이 깊은 뒤 이부자리를 펴고 잤다. 그런데 문득 바람과 구름이 몸을 이끌어 한 곳에 다다르니 바로 김 한림의 집이었다. 학사가 까닭 없이 안채에 들어가니, 화려하게 꾸민 집에 비단 휘장을 드리우고 탑상 위에 신위를 모시고 온갖 음식을 차려 놓았는데, 한림이 상 아래에서 슬피 울고 있었다. 한참 보고 있으니 한림이 곡을 그치고 한 여자를 돌아보며 말하였다. \"오늘 장씨의 외로운 혼을 위로하는 것은 부인의 덕이라. 장씨의 혼백이 어찌 감동하지 않으리오.\" 최씨도 얼굴빛이 참담하여 대답하였다. \"이는 군자의 신의이니 어찌 저의 덕이라 하겠습니까.\" 하며 슬픔이 끝이 없었다. 학사가 매우 이상히 여겨 그 영위에 쓴 것을 보니 '청주인 장 소저 신위'라 쓰여 있었다. 크게 의혹하여 묻고자 하였으나 한림이 너무 슬퍼하므로 묻지 못하고, 문득 시장하여 상에 차린 것을 다 먹고 또 옥쟁반의 황혼주를 마시다가, 홀연 닭 우는 소리에 깨니 한바탕 꿈이었다.","sp":[[7,9,"P","설낭"],[11,13,"P","영춘"],[84,88,"P","김희경"],[284,286,"P","최씨"],[384,388,"P","장설빙"]]},{"c":1,"sub":"","t":"매우 이상하여 날짜를 따져 보니 바로 벽해수에 빠지던 날이었다. 문득 한림이 자기를 위하여 제사를 지내는 줄 알고 감격과 슬픔을 금치 못하는 가운데 또 생각하였다. '그 여자는 틀림없이 한림의 정실이로다. 슬퍼함이 지극하니 그 어짊을 알 만하구나.' 하며 감탄해 마지않았다. 날이 새자 의관을 갖추고 한림의 집에 이르니 한림이 반겨 맞았다. 예를 마치고 자리를 정한 뒤 서로 이야기하는데, 술을 내어 권하기에 자세히 보니 모두 꿈에 먹던 것이었다.","sp":[]},{"c":1,"sub":"","t":"학사가 잔을 잡고 한림을 향하여 말하였다. \"소제가 오늘 우연히 성찬을 받으니 지극히 감사하오나, 모르겠습니다, 형께서 손님을 대하시고도 화기가 없으시니 무슨 불편한 마음이 있으십니까?\" 한림이 길게 탄식하였다. \"다른 것이 아니라 오늘이 가을 칠월 보름이니 누이가 세상을 버린 날입니다. 그래서 한잔 술로 외로운 혼을 위로하던 중인데, 형을 보니 자연히 시름을 감추지 못하였습니다.\" 학사가 다 듣고 절하며 사례하였다. \"형의 큰 덕은 천고에 둘도 없겠습니다. 주인 없는 외로운 혼을 이렇게 위로하시니 누이의 영혼이 반드시 감사할 것입니다. 소제는 동기이면서도 생각지 못하였는데, 형을 대하니 부끄러움을 이기지 못하겠습니다.\" 하며 사례해 마지않으니 한림이 슬픔을 참고 위로하였다. 날이 저물자 학사가 하직하고 집으로 돌아와 한림의 은덕에 속으로 탄복하였다.","sp":[]},{"c":1,"sub":"","t":"천자가 학사와 한림의 바르고 곧음을 생각하시어 칙교를 내려 장수정을 병부상서로, 김희경을 이부상서로 삼으시니 두 사람의 은총이 온 나라에 떨쳤다. 조정의 모든 관원이 그 강직함을 두려워하지 않는 이가 없었다.","sp":[[0,2,"P","황제"],[33,36,"P","장설빙"],[45,48,"P","김희경"]]},{"c":1,"sub":"","t":"하루는 학사가 조회를 마치고 집에 돌아와 옷을 벗고 난간에 기대어 앉았는데, 설낭과 영춘이 눈을 들어 보니 금빛 관과 옥 장식 조복이 단정하고 옥패 소리가 은은하여, 옥 같은 얼굴과 영웅다운 풍채가 늠름한 재상의 골격이요 조금도 여자의 태도가 없었다. 설낭이 한편으로 기뻐하고 한편으로 민망하여 조용히 간하였다. \"소저께서는 본래 깊은 규중의 여자로서 외람되게 높은 벼슬에 올라 몸에 푸른 적삼을 걸치고 허리에 옥띠를 둘러 세상을 속이는 것이 심하십니다. 비록 존귀함을 즐기시나 장래를 어찌하려 하시옵니까?\" 학사가 다 듣고 노한 빛으로 말하였다. \"내가 자연히 처리하겠다고 일렀거늘 이제 또 부질없이 말을 꺼내 내 마음을 흔드느냐. 부디 이후로는 이런 말을 다시 하지 마라. 나라고 모르는 바가 아니나 형세가 부득이한 것이지 마음대로 즐기는 것이 아니다.\" 기색이 엄하고 말씀이 정대하니 설낭 등이 감히 다시 말을 못하고 물러 나와 매우 민망해하며, 옛일을 생각하고 소저의 신세가 이리 번잡해진 것을 한탄하였다.","sp":[[43,45,"P","설낭"],[47,49,"P","영춘"],[141,143,"P","설낭"],[442,444,"P","설낭"]]},{"c":1,"sub":"","t":"천자가 금원(禁苑)에 나와 앉으시어 봄 경치를 구경하시며 여러 신하와 글을 지어 주고받으셨다. 수정과 희경의 글이 가장 뛰어나 그 활달한 뜻이 넓은 바다를 헤치며 흐르는 별 같아 사람의 마음을 시원하게 하였다. 황상이 크게 칭찬하시어 장수정을 연왕의 태부(太傅)로, 김희경을 연왕의 제왕사(帝王師)로 삼으시고 바른 도리로 이끌어 가르치라 하셨다. 연왕은 황후께서 낳으신 분이었다. 두 사람이 엎드려 아뢰었다. \"신들은 나이 어리고 재주가 없어 배운 바가 없사오니 성은을 감당하지 못하겠사옵니다.\" 하며 굳이 사양하였으나 황상이 듣지 않으시니, 두 사람이 마지못하여 연왕궁에 머물며 바른 도리로 왕윤을 이끌었다. 엄정하고 강직하여 조금도 사사로움이 없으니 왕이 매우 공경하였다. [?]","sp":[[0,2,"P","황제"],[53,55,"P","장설빙"],[57,59,"P","김희경"],[118,120,"P","황제"],[131,134,"P","장설빙"],[136,138,"P","연왕"],[149,152,"P","김희경"],[154,156,"P","연왕"],[194,196,"P","연왕"],[291,293,"P","황제"],[316,318,"P","연왕"],[332,334,"P","연왕"]]},{"c":1,"sub":"","t":"하루는 왕이 내궁에 들어가 점을 치고 나오다가[?] 그 사부들을 엿보았는데 눈이 마주치자 놀라 피하였다. 한림이 못 본 체하고 학사에게 말하였다. \"왕이 들어오다가 피한 것은 반드시 우리가 곧 일어나 맞이하지 않은 것을 꺼려서일 것입니다. 뒷날 반드시 그 꾸지람을 면치 못할 것이니 형은 살펴서 무례하지 마소서.\" 학사가 한림의 겁내는 모습을 보고 웃으며 한참 묵묵히 있다가, 훌쩍 몸을 일으켜 의관을 바로 하고 목소리를 높여 좌우에 호령하였다. \"연왕을 끌어들이라.\" 한림이 크게 놀라 급히 말렸다. \"형은 어찌 망령된 일을 하오?\" 학사는 대답하지 않고 어서 잡아들이라 재촉하니 호령이 가을 서리 같았다. 이윽고 좌우가 연왕을 붙들어 들이자 학사가 무릎을 꿇게 하고 크게 경계하였다. \"수정이 비록 어리석으나 나라의 대신이요 전하의 스승입니다. 황상의 명을 받들어 바른 도리로 전하를 이끌면서 조금도 예가 아닌 일을 한 적이 없거늘, 전하께서는 어찌하여 배우지 않은 행실을 찾아 문을 열고 몰래 자취를 숨겨 사람의 거동을 엿보십니까. 이런 가르침은 없습니다. 전하께서 비록 언짢으시더라도 잠깐 스승과 제자의 의리를 생각하시어 얼굴빛을 바르게 하시고 말씀을 순하게 하시어 의리로 타이르실 것이거늘, 전하께서는 문득 눈을 들어 사람을 보시고 도로 피하시니 이는 성인의 도를 따르는 행실이 아닙니다. 속으로 전하를 위하여 한심하게 여기옵니다.\" 경계하는 기색이 엄하고 위풍이 늠름하여 한겨울의 눈서리 같고 붉은 해가 둘도 없는 듯하니, 좌우의 여러 신하가 그 강직함을 두려워하지 않는 이가 없었다. [?]","sp":[[251,253,"P","연왕"],[349,351,"P","연왕"],[386,388,"P","장설빙"],[419,421,"P","황제"]]},{"c":1,"sub":"","t":"이에 학사가 연왕을 보내고 곧 표를 올렸다. \"신은 본래 미천하고 박한 인생이라 왕을 바른 도리로 이끌지 못하여 왕께서 도리어 배운 바가 없게 되었습니다. 그러므로 왕께서 예의에서 벗어나 바르지 못한 길로 가시는데, 신이 외람되게 폐하의 명을 받들어 왕의 스승이 되었으니 그 허물을 간하지 않을 수 없어 잠깐 스승과 제자의 도리를 세운 것입니다. 예를 어기지 못하는 것은 법도의 바른 이치이옵니다. 위엄을 두려워하고 세력에 눌려 법을 폐하는 것은 간신이 제 몸을 돌보며 임금의 총애를 생각하는 것입니다. 신이 비록 어리석으나 법을 맡은 사람으로서 의리가 있기에 부득이 왕을 꾸짖고 이렇게 표를 올려 죄를 청하오니, 엎드려 바라옵건대 폐하께서는 신의 죄를 각별히 다스려 뒷사람을 경계하옵소서.\" [?]","sp":[[7,9,"P","연왕"]]},{"c":1,"sub":"","t":"황상이 다 보시고 크게 칭찬하셨다. \"수정은 참으로 한나라의 급암이로다.\" 하시고 곧 비답을 내리셨다. \"짐이 경의 표를 보니 감격을 이기지 못하겠노라. 연왕의 사람됨을 기뻐하였는데, 이런 표를 날마다 본다면 참으로 짐의 마음이 즐거울 것이다. 저 왕은 경의 제자요 경은 왕의 스승이라, 제자가 허물이 있으면 매를 때려도 되거늘 그만한 경계를 어찌 방자하다 하겠느냐. 경의 바르고 곧음을 후세에 남의 스승 되는 자로 하여금 본받게 하고자 하노라. 부디 왕이 잘못함이 있거든 당당히 법으로써 가르쳐 그릇됨이 없게 하라.\" 학사가 이후로 경계하며 가르치니 왕도 조심하여 그런 일이 없었다. 칭송하는 소리가 안팎에 떨쳤고, 한림은 학사의 바르고 곧음을 보고 황공하여 공경을 극진히 하였으며 조정이 모두 두려워하였다.","sp":[[0,2,"P","황제"],[21,23,"P","장설빙"],[86,88,"P","연왕"]]},{"c":1,"sub":"","t":"하루는 학사가 한가하여 책상에 기대어 옛일을 생각하니 마음이 저절로 울적해졌다. 문득 북해 노인의 은혜를 생각하고 길게 탄식하였다. \"아버님의 유골을 선산에 안장하고 내 몸도 영화롭고 귀하게 되어 조상의 제사를 받드는 것은 참지(參知)의 덕이다. 내 몸을 버려서라도 그 은혜를 갚는 것이 옳거늘, 지금 부귀에 잠겨 남의 은혜를 버리고 있으니 도리어 배은하는 사람이 되겠구나.\" 하며 탄식해 마지않았다.","sp":[[48,53,"P","소세필"],[125,127,"P","소세필"]]},{"c":1,"sub":"","t":"이튿날 조회를 마친 뒤 조용히 임금의 자리 앞에 나아가 아뢰었다. \"신이 듣자오니 나라가 법을 세움에 마땅히 법을 숭상하여 가볍고 무거움을 살핀다 하오니, 법령과 형벌이 밝고 깨끗한 뒤에야 간신이 물러가고 충신이 나아온다 합니다. 이제 전 참지정사 소세필은 선조 때의 적하 현성의 외손으로, 충효를 다한다는 소문이 끊이지 않았는데, 어느 날 간신의 참소를 입어 북해로 귀양 간 지 이미 삼십여 년이 되었습니다. 엎드려 바라옵건대 폐하께서는 깊이 생각하시어 특별히 사면하여 주시기를 바라옵니다.\" 황제가 다 듣고 깨달으시어 그날로 소세필을 풀어 주시고 예부상서로 부르시니, 학사가 머리를 조아려 사은하고 물러 나왔다. 조정이 모두 학사의 두터운 덕에 탄복하였다. [?]","sp":[[134,136,"P","소세필"],[139,142,"P","소세필"],[277,279,"P","황제"],[296,299,"P","소세필"]]},{"c":1,"sub":"","t":"한편, 소공을 사면한다는 글이 북해에 이르렀으나, 애석하게도 소공은 한 달 전에 세상을 떠났다. 태수가 조문하려던 차에 마침 사면의 글이 왔으므로 그 죽음을 아뢰니, 조정이 크게 탄식하고 황상도 슬퍼하시어 북해 태수에게 조칙을 내려 소공의 상구를 서울로 호송하게 하시고 그 일가를 서울에 와서 살게 하셨다. 태수가 칙교를 받들어 소공의 상구를 호송하면서 아전과 백성을 청하여 상여를 모시게 하니, 소공의 일가가 성은을 못내 칭송하였다. 학사는 소공의 부고를 듣고 슬퍼하여 십 리 정자에 나아가 조문하며 크게 통곡하였는데, 아는 이 없음을 서러워하니 보는 사람들이 슬퍼하였다. [?]","sp":[[4,6,"P","소세필"],[34,36,"P","소세필"],[54,56,"P","북해 태수"],[105,107,"P","황제"],[115,120,"P","북해 태수"],[130,132,"P","소세필"],[172,174,"P","북해 태수"],[184,186,"P","소세필"],[222,224,"P","소세필"],[248,250,"P","소세필"]]},{"c":1,"sub":"","t":"학사가 조문을 마친 뒤 소공 부인께 말을 전하였다. \"이 사람은 전 이부상서 장자영의 아들인데, 아버님께서 북해에서 원통하게 돌아가셨을 때 홑몸으로 의탁할 데가 없고 어찌할 바가 아득하여 망극하였습니다. 온 세상에 혼자였는데 천만뜻밖에 상공의 하해 같은 은혜를 입어 남은 목숨을 부지하고 아버님 시신을 선산에 편히 모셨으니, 밤낮으로 그 은혜를 뼈에 새겼습니다. 다행히 급제하여 몸이 나라에 매인 까닭에 일찍 찾아뵙지 못하였으니 황공하기 그지없습니다. 이 사람이 죽기를 무릅쓰고 임금의 위엄을 범하여 참지의 억울함을 풀어 드렸고, 황상께서 깨달으시어 사면의 명이 내리시니 반가이 뵙기를 손꼽아 기다렸는데, 꿈에도 생각지 못하게 이승과 저승이 바뀌었으니 슬픔을 어찌 다 헤아리겠습니까.\" 소공 부인이 문득 깨닫고 옛일을 생각하며 감격하여 사례하고 못내 서러워하였다.","sp":[[13,15,"P","소세필"],[43,46,"P","장자영"],[280,282,"P","소세필"],[297,299,"P","황제"],[384,386,"P","소세필"]]},{"c":1,"sub":"","t":"소공은 본래 아들이 없었으므로 학사가 친히 상주가 되어 선산에 안장하였다. 조정 사람들이 학사의 낯을 보아 조문하는 이가 길을 메웠으니 참으로 왕후의 장례 기구와 다르지 않았다. 장례를 마친 뒤 학사는 그 부인을 모시고 서울에 올라와 종남산 밑에 별당을 지어 소 부인을 머물게 하고 날마다 문안을 끊지 않았다. 소 부인이 못내 감격하였고, 학사는 아침저녁 공양과 소공의 삼년상을 극진히 받드니 세상 사람들이 모두 칭찬하고 조정이 모두 그 큰 덕에 탄복하였다. 은혜를 갚는 일이 분명함을 알 만하였다.","sp":[[0,2,"P","소세필"],[203,205,"P","소세필"]]},{"c":1,"sub":"","t":"이때 천하가 태평하고 사방이 안정되어 온 백성이 즐겨 격양가를 부르고, 나라에 일이 없어 관청이 한가하였다. 학사는 나가면 김 상서와 함께 시와 술을 일삼고, 들어오면 설낭, 영춘과 옛일을 한가로이 이야기하며 소일하였다. 하루는 학사가 마음이 심심하여 두루 거닐다가 바깥채에 나와 난간에 기대어 경치를 구경하며 시를 지어 흥을 풀고 있었다. 그런데 문득 한 유생이 밖에서 들어와 바로 중헌에 올라 예를 하고 앉으며 말하였다. \"서로 본 지 이미 이십 년이라. 이제 고생을 지내고 복록을 받는구나.\" 눈을 들어 그 거동을 보니 갈건에 표주박 옷을 입었고 얼굴이 비상하며 움직임이 기이하여 조금도 예법의 격식이 없었다. 학사가 몹시 의혹하여 속으로 생각하였다. '내 비록 나이 어리나 벼슬이 육경에 있고 이름이 온 세상에 떨치니, 평범한 사람이라면 어찌 감히 유생의 복색으로 거리낌 없이 중헌에 올라 앉겠는가. 반드시 뜻이 있는 사람이다.' 하고 공경히 답례하였다. \"소생은 일찍이 견문이 없어 존안을 뵌 적이 없는데 구면이라 하시니 의혹을 풀지 못하겠습니다. 게다가 이십 년 전에 보았다 하시나 소생은 태어난 지 열아홉 해입니다. 선생께서 어찌 이렇게 소생을 희롱하십니까. 바라옵건대 가르치실 말씀이 있거든 밝혀 말씀하시어 의혹을 없애 주소서.\" [?]","sp":[[69,73,"P","김희경"],[94,96,"P","설낭"],[98,100,"P","영춘"],[200,202,"P","도인"],[423,425,"P","도인"]]},{"c":1,"sub":"","t":"그 사람이 살짝 웃으며 대답하지 않다가 갑자기 소매에서 보검과 책을 꺼내 주며 말하였다. \"그대가 묻는 말에 대답하지 않는 것은 하늘의 기밀이 지극히 비밀하여 감히 입으로 말할 수 없기 때문이다. 나중에 자연히 알게 될 것이니, 이 두 가지를 힘써 익히면 머지않아 임금의 은혜를 갚고 조상에게 기쁨을 끼쳐 충과 효를 모두 온전히 할 것이다. 삼가 누설하지 마라.\" 말을 마치고 섬돌에 내려서더니 문득 간 곳이 없었다. 학사가 그제야 천신의 도술인 줄 알고 신기하게 여겨 그 칼과 책을 보았다. 칼은 길이가 석 자요 빛이 황홀하여 해와 달의 정기와 북두성, 견우성의 광채가 쏘이며, 그 속에 은은히 '태항천의 검'이라 새겨져 있으니 범인의 손에 들 물건이 아니요 신선의 조화였다. 또 책을 보니 선비의 학업이 아니라 뜻이 웅장하고 넓어 천지의 조화가 끝이 없었다. 태공의 병서도 아니요 손무와 오기의 병서도 아니며 황석공의 비서도 아니었다. 학사가 속으로 '내가 알기로 육도삼략과 병서를 많이 보았으나 이 책은 참으로 처음 보는구나.' 하였다. [?]","sp":[[242,244,"P","도인"],[456,458,"P","석 태위"]]},{"c":1,"sub":"","t":"속으로 하늘의 비밀한 뜻을 짐작하고 매우 의혹하여 스스로 생각하였다. '이는 반드시 장수의 기물이요 서생에게는 맞지 않는 것이다. 내 근본을 세상 사람은 모르나 하늘과 땅은 환히 아는 바인데, 이것을 나에게 보낸 것은 무슨 까닭인가.' 하며 몹시 의아해하다가 또 생각하였다. '나라가 만일 위태로우면 충신의 자손은 비록 부녀라도 창검을 잡아 임금과 아버지의 위태로움을 구할 것이다. 하물며 나는 몸을 나라에 바쳤으니, 비록 근본은 여자이나 집 안에 들어앉은 부녀와는 다르다. 만일 나라에 변이 있어 위태로우면 갑옷과 투구를 갖추고 칼을 잡아 죽기를 사양하지 않는 것이 신하의 도리다. 그 하늘의 기밀은 알지 못하나 그 도인이 나에게 충효를 모두 온전히 하리라 하였으니, 반드시 머지않아 적국의 변란이 있겠구나.' 하고 이상하게 여겨 탄식해 마지않았다.","sp":[[346,348,"P","도인"]]},{"c":1,"sub":"","t":"이후로 학사는 조회를 마치면 집에 돌아와 낮이면 천문학에 힘쓰고 밤이면 검술을 익히며 때를 기다렸다. 이미 온갖 책을 통달하였으므로 한 달이 못 되어 검술을 통달하니, 병법은 한나라 때의 제갈량이라도 미치지 못하고 검술은 초패왕도 우습게 여길 만하였다. 학사가 이에 마음속으로 웃으며 말하였다. \"내가 일찍이 남녀를 바꾼 것은 한때 부모를 향한 정을 참지 못하고 의탁할 데가 없어 아버님의 얼굴을 뵐까 하여 세상을 속인 것이었다. 이제 벼슬이 재상에 이르고 아버님의 원혼을 위로하였으니 다시는 한이 없을 듯하나, 아직 여자의 도리를 회복하지 않았으니 반드시 하늘이 미워하실 것이라. 생각이 이에 미치자 밤낮으로 근심하였는데, 이제 또 이런 일을 맡아 어진 마음을 고칠 줄 모르니 훗날 구천에 돌아가서도 조상의 꾸지람을 면치 못하겠구나. 그러나 이미 마음을 허락하여 임금을 섬기고, 만세 뒤에 함께 구천으로 돌아간다면 비록 조상의 꾸지람을 받더라도 어찌 마음에 부끄럽지 않겠는가[?]. 어쨌든 문무를 겸하여 변방에 나아가 적들에게 영웅의 재주를 자랑하고 이름을 만세에 전하면 이 또한 사람의 사업으로 족하니 설마 어찌하겠는가.\" 하고 날마다 글과 검을 일삼았다. [?]","sp":[[196,198,"P","소세필"]]},{"c":1,"sub":"","t":"이럭저럭 위국에 왕으로 봉해진 유협이 있었는데, 왕이 된 지 이미 삼 년이 되었으나 한 번도 조회하러 온 일이 없었다. 조정이 황상께 아뢰어 죄를 묻기를 청하자 황상이 옳게 여겨 곧 사자를 보내, 여러 해 조회하지 않은 죄를 묻고 어서 와서 조회하라 하셨다. 사신이 위국에 이르러 조서를 전하니, 위왕이 다 보고 발끈 크게 노하여 손으로 북쪽을 가리키며 크게 꾸짖었다. \"조그마한 아이가 어른을 공경하지 않고 이렇게 무례하냐. 이제 이런 욕을 보고서 무슨 면목으로 위국 사람을 보겠느냐.\" 말을 마치고 좌우에 명하여 사신을 끌어내 베라 하니, 좌우의 무사들이 일시에 달려들어 사신을 베고 그 머리를 올렸다. 그리고 곧 따라온 아이 종을 밖으로 내쫓으며 욕하여 보냈다. [?]","sp":[[17,19,"P","유협"],[71,73,"P","황제"],[90,92,"P","황제"],[166,168,"P","유협"]]},{"c":1,"sub":"","t":"아이 종이 크게 두려워 그 머리를 가지고 황성에 돌아와 황제께 드리고 욕하던 말을 낱낱이 아뢰니, 황상이 크게 놀라 노하시어 곧 여러 신하를 모아 말씀하셨다. \"이제 왕숙 위왕이 반역의 마음을 품고 사신을 베어 머리를 보냈으니, 위왕은 짐의 숙부라 형세가 난처하도다. 이를 어찌하리오.\" 여러 신하가 반열에서 나와 아뢰었다. \"그가 여러 해 조회를 하지 않았으니 그 죄를 묻는 것이 당연하온데, 도리어 사신을 죽이고 조정을 욕되게 하였으니 이는 반드시 머지않아 변란을 일으켜 하늘의 뜻을 범할 것이옵니다. 폐하께서는 살피시어 지혜와 용기를 겸비한 자에게 한 무리의 군사를 주어 반적을 소멸하여 후환이 없게 하옵소서.\" 황상도 개탄하시고 곧 교장(敎場)에 큰 붉은 깃발을 세우고 북을 울려 모든 관원을 모으고 서글피 탄식하셨다. \"짐의 덕이 밝지 못하여 골육이 원수가 되어 스스로 반역의 마음을 품고, 이제 짐의 사신을 베어 머리를 보냈으니 어찌 불행하지 않으리오. 짐이 이제 대군을 일으켜 위국을 평정하고 간사한 무리를 소탕하고자 하니, 누가 대장이 되어 위왕을 잡아 짐의 근심을 덜겠느냐?\" [?]","sp":[[31,33,"P","황제"],[55,57,"P","황제"],[93,98,"P","유협"],[128,130,"P","유협"],[346,348,"P","황제"],[535,537,"P","유협"]]},{"c":1,"sub":"","t":"여러 신하 가운데 한 사람도 대답이 없었는데, 문득 한 소년 대신이 조복을 끌고 천천히 나와 엎드려 반열에서 아뢰었다. \"소신이 비록 재주가 없사오나 원컨대 선봉이 되어 유협을 사로잡아 폐하의 근심을 덜겠사옵니다.\" 모두 보니 얼굴이 옥으로 깎은 듯하고 가는 버들 같은 허리에 목소리가 맑아 봉황이 단산에서 우는 듯하였으며, 두 눈썹 사이에 은은히 천지의 조화를 감추었고 가슴속에 만고의 흥망을 품은 듯하였다. 풍채가 빼어나 원근에 빛나니, 이는 태학사 병부상서 연왕 태부 장수정이었다. 황상이 크게 기뻐하시고 여러 신하도 감탄하였다. 또 한 소년이 나와 엎드려 목소리를 높여 아뢰었다. \"소신은 본래 대대로 녹을 받은 신하라 나라의 은혜가 망극하오니, 청컨대 수정과 힘을 합하여 위왕의 머리를 폐하의 휘하에 바치겠사옵니다.\" 모두 보니 청춘의 영걸이라 위엄이 늠름하고 기운이 빼어나, 마치 구름과 안개를 헤치고 푸른 하늘에 오른 듯하니, 이는 춘방 한림 겸 이부상서 제왕사 김희경이었다. [?]","sp":[[95,97,"P","유협"],[259,261,"P","연왕"],[265,268,"P","장설빙"],[273,275,"P","황제"],[370,372,"P","장설빙"],[381,383,"P","유협"],[490,493,"P","김희경"]]},{"c":1,"sub":"","t":"황상이 두 사람의 준수하고 늠름함을 기뻐하시어 매우 즐거워하셨는데, 여러 신하가 일시에 아뢰었다. \"장수정과 김희경은 나이 어린 서생이라 문무를 배워 태평성대에 백성을 다스리는 것은 좋으나, 대군 가운데 적장을 베는 것은 옳지 않습니다. 폐하께서 믿으시고 이들을 보냈다가 큰일이 그릇되면 뉘우쳐도 소용없을 것이오니, 바라옵건대 무반 가운데 지혜와 용기를 겸한 장수를 보내 후환이 없게 하소서.\"","sp":[[0,2,"P","황제"],[56,59,"P","장설빙"],[61,64,"P","김희경"]]},{"c":1,"sub":"","t":"장 학사가 이 말을 듣고 분을 이기지 못하여 모든 관원을 꾸짖었다. \"제비와 참새가 어찌 기러기와 고니의 뜻을 알겠느냐. 대장부가 세상에 살면서 몸을 나라에 바쳐 임금을 섬긴다면 마땅히 충성을 다하여 몸이 죽더라도 나라의 은혜를 갚는 것이 군자의 도리요 신하의 행실이다. 그런데 그대들은 대대로 나라의 녹을 받아 태평을 누리다가, 이제 조그마한 일을 당하자 마음속으로 한갓 처자 떠나는 것을 애달파하고 제 몸에 해가 있을까 두려워 황상께서 물으셔도 하나도 대답이 없더니, 이제 우리를 유생이라 하여 혈기를 꺾고 충성을 시기하니, 이러고서 어찌 임금을 섬겨 나라를 도울 재목이라 하겠느냐. 임금께서 욕을 당하시면 신하는 죽는 것이 떳떳한 일이라, 나라의 은혜를 입고 어지러운 때를 당하여 어찌 손을 묶고 앉아 죽기를 기다리겠느냐. 내 비록 서생이나 당대의 문무를 지푸라기같이 아니, 조그마한 위국을 어찌 근심하겠느냐.\" 말을 마치고 황상께 아뢰었다. \"신이 이제 김희경과 함께 위국에 나아가 위왕을 잡지 못하거든 군법을 시행하옵소서.\" 말이 웅장하고 기상이 빼어나 당당한 열사요 충신이었다. 황상이 처음에는 염려하셨으나 이렇게 활달함을 크게 기뻐하시어 말씀하셨다. \"경들의 충성이 이러하니 짐이 어찌 위왕을 근심하리오.\" 하시고 곧 장수정을 대원수로, 김희경을 부도독으로 삼으시고 군사 오만을 주어 출정하게 하셨다. 절월과 인검을 주시며 군중의 위엄을 도와 마음대로 처리하라 하시니, 문무 여러 신하가 감히 막지 못하였고 학사의 말에 대답할 자도 없었다. [?]","sp":[[0,4,"P","장설빙"],[241,243,"P","황제"],[271,273,"P","도인"],[465,467,"P","황제"],[482,485,"P","김희경"],[498,500,"P","유협"],[554,556,"P","황제"],[615,617,"P","유협"],[633,636,"P","장설빙"],[644,647,"P","김희경"],[650,652,"P","김희경"]]},{"c":1,"sub":"","t":"사은하고 물러 나와 군사를 정비하여 출발하는데, 학사는 부모님 사당에 하직하고 다음으로 설낭, 영춘에게 무탈하라 당부하였다. 또 정부인께 하직하니 정부인이 서운해하며 무사히 돌아오라고 백 번 당부하였다. 김희경도 집에 돌아가 부모께 하직하니, 참정은 장한 일이라 하며 조심하라 당부하였으나 부인과 최씨는 위험한 땅으로 떠나는 것을 못내 서운해하였다. 상서가 이에 학사와 함께 교장에 나아가 군사를 이끌고 남방으로 향하는데, 깃발과 창검이 해와 달을 희롱하고 군령이 엄숙하니 이는 만고에 제일이었다. 천자가 모든 관원을 거느리고 십 리 밖까지 친히 거둥하여 원수를 전송하시는데, 군대의 모습이 이렇게 엄숙함을 보시고 칭찬하셨다. \"이 두 사람의 재주가 이러하니 어찌 한 지방을 근심하리오.\" 하시며 못내 기뻐하시고 환궁하셨다. [?]","sp":[[49,51,"P","설낭"],[53,55,"P","영춘"],[72,75,"P","정부인"],[82,85,"P","정부인"],[114,117,"P","김희경"],[136,138,"P","이영찬"],[166,168,"P","최씨"],[279,281,"P","황제"]]},{"c":1,"sub":"","t":"한편, 위왕은 사신의 머리를 베어 보내고 여러 신하와 의논하였다. \"원제(元帝)가 만일 사신의 머리를 보면 결코 가만있지 않을 것이다.\" 모두 아뢰었다. \"원제가 비록 나약하나 큰 나라라 장수와 군사가 많사오니 우리의 적은 군사로는 막지 못할 것입니다. 전에 듣자오니 남경왕이 원나라를 치려고 군사를 조련한다 하오니, 이제 전하께서 남경왕과 동맹하여 힘을 합해 치면 도모할 수 있을 것이옵니다.\"","sp":[[4,6,"P","유협"],[38,40,"P","황제"],[87,89,"P","황제"],[150,153,"P","남경왕"],[186,189,"P","남경왕"]]},{"c":1,"sub":"","t":"위왕이 옳게 여겨 곧 글을 써서 남경에 보내 서로 맹세하고 뜻을 통하였다. 남경왕은 위왕이 사신을 베었다는 말을 듣고 속으로 뜻을 두고 있던 터라, 기별을 듣고 매우 기뻐하여 날을 기약하여 답을 보내고 군사를 일으켜 위국에 이르렀다. 위왕이 문밖에 나와 맞아들여 자리를 정하고 인사를 마친 뒤 몸을 굽혀 사례하였다. \"과인이 먼저 대왕을 찾아뵙는 것이 옳은데 대왕께서 이렇게 와 주시니 감사함을 이기지 못하겠습니다.\" 남왕이 겸손해 마지않으며 말하였다. \"대왕은 귀하신 몸이요 한 지방을 다스리시는 분이니 어찌 그런 예를 받으시겠습니까.\" 위왕이 또 사례하고 말을 꺼냈다. \"원제는 과인의 조카인데, 방자하게 황제 자리에 의지하여 과인을 업신여기니 어찌 달게 받겠습니까. 과인이 이제 군사를 일으켜 개돼지 같은 그 아이를 잡아 욕을 씻고자 하나 군사가 적고 모자란 것을 근심하던 중, 듣자니 대왕께서도 반역의 마음을 두어 군사를 연습한다 하기에 감히 청하였습니다. 과인을 용렬하다 아니하시고 군량을 도우신다면 두 나라가 힘을 합하여 중원을 얻은 뒤 서로 경계를 정하고 생사를 함께하심이 어떠하십니까?\" [?]","sp":[[0,2,"P","유협"],[42,45,"P","남경왕"],[47,49,"P","유협"],[131,133,"P","유협"],[234,236,"P","남경왕"],[302,304,"P","유협"],[322,324,"P","황제"],[341,343,"P","황제"]]},{"c":1,"sub":"","t":"남왕이 기꺼이 대답하였다. \"저도 이런 뜻을 둔 지 오래이나 대왕께서 길을 막고 계셨기에 힘이 부족하여 일으키지 못하였고, 다만 대왕의 위엄을 두려워하였습니다. 이제 대왕께서 저의 어리석음을 허물하지 않으시고 이렇게 너그러이 대해 주시니 감사함을 이기지 못하겠습니다. 대장부가 어찌 남에게 굽혀 조공을 하겠습니까. 대왕께서 저를 어리석다 아니하시면 개와 말의 수고를 어찌 사양하겠습니까.\" 위왕이 크게 기뻐하여 곧 흰 말을 잡아 하늘에 맹세하고 생사를 함께하기로 하였다. 이튿날 두 나라가 장대에 올라 군세를 정비하니 군사가 삼십만이요 장수가 천여 명이었다. 밤낮으로 연습하며 중원을 엿보았다. [?]","sp":[[0,2,"P","남경왕"],[218,220,"P","유협"]]},{"c":1,"sub":"","t":"그런데 문득 천자의 대군이 성 밖 십 리에 이르렀다는 보고가 오자 두 나라 왕이 크게 노하여 각각 자기 나라 군사를 거느리고 성 밖에 진을 치고 기다렸다. 이때 장 학사는 김 상서와 함께 행군하여 위국에 다다랐는데, 위왕이 이미 군사를 일으켰다고 하였다. 바라보니 깃발이 나부끼고 칼과 창이 빽빽이 늘어섰다. 위왕의 준비를 보고 군사를 재촉하여 적진을 마주하여 진을 치고, 학사가 상서와 함께 장대에 높이 앉아 적진을 바라보았다. 위왕이 남경왕과 함께 대군을 거느려 진세를 이루었는데, 병마는 비록 웅장하나 방향을 제대로 잡지 못하였다. 학사는 속으로 대수롭지 않게 여겼으나 상서는 적진의 진세가 엄숙하고 병마가 많은 것을 염려하였다. 이는 병법에 익숙하지 못한 까닭이요, 학사는 천문학을 보아 변화의 이치를 배웠기에 잘 알았던 것이다. [?]","sp":[[7,9,"P","황제"],[90,94,"P","장설빙"],[96,100,"P","김희경"],[121,123,"P","유협"],[173,175,"P","유협"],[241,243,"P","유협"],[245,248,"P","남경왕"]]},{"c":1,"sub":"","t":"이에 위왕이 남경왕과 함께 진 앞에 나와 원나라 진을 바라보니, 장대에 한 젊은 장수가 자금빛 쌍봉관을 쓰고 몸에 백화 홍금포를 입고 허리에 황룡 요대를 두르고 손에 태양천의 검을 잡고 의젓하게 앉아 있었다. 기운이 씩씩하여 흰 구름이 채색 구름 사이로 솟는 듯하고 해와 달의 정기가 온몸을 둘렀으니, 보건대 사람 가운데 호걸이요 세상의 기이한 남자였다. 위왕이 크게 놀라 군사를 시켜 적진의 젊은 장수는 이름을 밝히라 하니, 학사가 웃으며 대답하였다. \"나는 중국의 대원수 연왕 태부 병부상서 태학사 장수정이다. 하늘이 그대를 도우시어 왕의 작위를 주어 한 지방을 지키게 하였거늘, 하늘의 은혜를 생각지 않고 도리어 반역의 마음을 품어 천자의 사신을 베고 황상을 욕되게 하였으니, 사람은 무심하다 하더라도 하늘이 어찌 두렵지 않겠느냐. 그러므로 황상께서 진노하시어 나로 하여금 그대를 다스리라 하시기에 내가 대군을 거느리고 여기에 온 것이다. 그대가 지금이라도 허물을 스스로 꾸짖어 끈을 풀고 몸을 묶어 항복한다면 죄를 용서하겠지만, 그렇지 않으면 당당히 태양천의 검을 한번 시험하리라.\"","sp":[[3,5,"P","유협"],[7,10,"P","남경왕"],[199,201,"P","유협"],[266,268,"P","연왕"],[281,284,"P","장설빙"],[357,359,"P","황제"],[368,370,"P","황제"],[418,420,"P","황제"]]},{"c":1,"sub":"","t":"왕이 크게 노하여 꾸짖었다. \"이름 없는 젖비린내 나는 어린아이가 감히 나를 욕하느냐.\" 하며 친히 나가 싸우고자 하는데, 문득 한 젊은 장수가 분연히 말하였다. \"대왕께서는 잠깐 노여움을 참으소서. 소장이 장 원수를 잡아 욕을 씻겠사옵니다.\" 하고 말을 달려 나는 듯이 나오니 위국의 명장 방후열이었다. 긴 창을 휘두르며 원수를 가리켜 크게 꾸짖었다. \"어린아이가 당돌하게 큰 진을 대하여 큰소리를 치니, 이른바 어린 강아지가 사나운 범을 두려워하지 않는 격이로다.\" 원수가 크게 노하여 좌우를 돌아보며 말하였다. \"누가 능히 적장을 베어 내 욕을 씻겠느냐?\" 말이 끝나기도 전에 한 대장이 응하여 말을 몰아 훌쩍 내달으니 모두 보니 석호준이었다. 두 장수가 서로 싸워 이십여 합에 이르도록 승부를 내지 못하였으나 방후열이 오히려 용맹하였다. 호준이 스스로 이기지 못할 줄 알고 창을 버리고 유성추를 들어 후열을 치려다가 문득 실수하여 말에서 떨어지니, 후열이 그 틈을 타 칼을 빼어 호준을 베어 들고 승승장구하여 기세를 돋우었다.","sp":[[116,120,"P","장설빙"],[163,166,"P","방후열"],[356,359,"P","석호준"],[401,404,"P","방후열"],[417,419,"P","석호준"],[496,498,"P","석호준"]]},{"c":1,"sub":"","t":"원수가 호준의 죽음을 보고 크게 슬퍼하고 분노하였다. 하후창이 나아가 싸우려 하는데, 문득 한 대장이 칼을 들고 말을 달려 훌쩍 내달으니 이는 부도독 김희경이었다. 원수가 크게 놀라 극구 말렸다. \"적장의 용맹이 남보다 뛰어나고 검술이 비범하니 가볍게 대적하지 못할 것이오.\" 도독이 말하였다. \"이는 밝지 못한 계책이요 평탄하지 못한 말씀입니다. 원수께서는 어찌 싸움터에서 적의 위풍을 돕고 스스로 예기를 꺾어 버리십니까?\" 말을 마치자 나는 듯이 내달으니 그 날램은 나는 제비라도 미치지 못할 정도였다. 다음 회를 볼지어다. [?]","sp":[[4,6,"P","석호준"],[81,83,"P","김희경"],[84,87,"P","김희경"],[155,157,"P","김희경"]]},{"c":2,"sub":"","t":"한편, 방후열이 멀리 바라보니 원나라 진 가운데서 한 젊은 대장이 나는 듯이 나오는데, 몸에 녹포와 은갑을 입고 머리에 용봉 투구를 쓰고 천리마에 올라 반월검을 들었다. 기상이 엄숙하고 풍채가 늠름하여 당당한 명장이었다. 후열이 한번 보고 그 사람됨에 감복하였으나 나이가 어린 것을 업신여겨 말을 몰아 맞붙어 싸우니, 삼십여 합에 이르도록 승부를 내지 못하였다. 후열이 한 꾀를 생각하고 도독을 유인하려고 거짓 패하여 달아나니, 도독이 크게 노하여 따라가려다가 문득 생각하였다. '저가 거짓 패하는 것은 반드시 간사한 꾀가 있어서다. 내 어찌 그 꾀를 모르고 빠지겠는가.' 하고 태연히 고삐를 잡고 서 있었다. 후열이 오십 보나 가도록 한 번도 돌아보지 않자, 도독이 철궁을 들어 쇠 화살을 먹여 쏘니 시위 소리가 나며 후열의 말이 맞았다. 후열이 말에서 떨어지자 도독이 급히 말을 달려 후열의 머리를 베어 창끝에 꿰어 들고 진 앞을 오가며 돌아갔다.","sp":[[4,7,"P","방후열"],[217,219,"P","김희경"],[240,242,"P","김희경"],[370,372,"P","김희경"],[428,430,"P","김희경"]]},{"c":2,"sub":"","t":"위왕이 후열의 죽음을 보고 크게 놀라 친히 여러 장수를 거느리고 나와 크게 외쳤다. \"나의 선봉을 죽인 장수는 빨리 나와 내 칼을 받아라.\" 도독이 크게 노하여 칼을 잡고 춤추며 나와 응하여 크게 꾸짖었다. \"후열이 이미 내 칼 아래 죽었거늘 네가 또 감히 나를 당하겠느냐.\" 하며 바로 위왕을 치려 하는데, 문득 적장 위충이 내달아 도독과 맞붙어 싸웠다. 이때 남경왕이 본진에서 두 진의 승패를 보다가 도독을 원수로 알고 군사를 지휘하여 사면을 둘러싸니, 도독이 그 병세가 굳건함을 보고 좌충우돌하였으나 빠져나오지 못하여 매우 위급하였다.","sp":[[0,2,"P","유협"],[79,81,"P","김희경"],[161,163,"P","유협"],[187,189,"P","김희경"],[203,206,"P","남경왕"],[226,228,"P","김희경"],[256,258,"P","김희경"]]},{"c":2,"sub":"","t":"이때 장 원수가 장대에서 위나라 진을 바라보다가, 위나라 군사가 머리와 꼬리가 맞닿도록 에워싼 것을 보고 크게 놀라 급히 여러 장수에게 말하였다. \"지금 도독이 위급하니 어찌 그저 있겠느냐.\" 하고 여러 장수를 거느리고 위나라 진에 다다르니, 사면을 위나라 군사와 남경 군사가 둘러싸 그 형세의 굳음이 쇠통 같았다. 원수가 말 한 필 창 한 자루로 춤추듯 한 곳을 쳐부수며 들어가는데, 문득 한 장수가 길을 막았다. 원수가 크게 노하여 태양검을 번뜩이니 그 장수의 머리가 떨어졌다. 중군을 향하여 짓쳐 들어가는데 또 한 장수가 길을 막으므로 원수가 이름을 물으니 위나라 장수 위영이었다. 원수가 크게 노하여 말하였다. \"원나라 장수는 어디 있느냐?\" 위영이 춤추며 크게 꾸짖었다. \"원나라 장수는 벌써 죽어 칼 아래 귀신이 되었으니 찾고 싶거든 지하에 가서 찾아라.\" 원수가 더욱 분노하여 태양검을 들어 치니 위영의 머리가 말 아래로 떨어졌다. 원수가 승승장구하여 짓쳐 들어가니, 위와 남경 두 나라 왕이 각각 여러 장수를 거느리고 원나라 장수를 둘러싸고 북소리와 함성으로 외쳤다. \"원나라 장수는 날개가 없으리니 목숨이 아깝거든 빨리 항복하라.\" 하는 소리가 천지를 울렸다. 원수가 도독의 위급함을 보고 벼락같이 소리를 지르며 달려들어 동서로 내달으니, 닿는 곳마다 적장의 머리가 가을바람에 낙엽같이 떨어져 시체가 산 같고 피가 흘러 시내가 되었다. 누가 감히 대적하겠는가.","sp":[[3,7,"P","장설빙"],[86,88,"P","김희경"],[322,324,"P","위영"],[364,366,"P","위영"],[453,455,"P","위영"],[607,609,"P","김희경"]]},{"c":2,"sub":"","t":"이에 도독을 구하여 나왔다. 도독은 처음에 겹겹이 싸여 병세가 쇠통 같았는데, 죽기로 좌우를 쳐도 빠져나오지 못하자 하늘을 우러러 탄식하였다. \"내가 적장을 가볍게 여기다가 오늘 이곳에서 청춘을 마치겠구나.\" 하고 탄식해 마지않았다. 그런데 홀연 적군이 사방으로 흩어져 무너지며 한 젊은 장수가 진중에 돌입하여 종횡으로 날뛰므로, 도독이 정신을 차려 자세히 보니 바로 장 원수였다. 크게 기뻐하여 자기를 구하러 온 것을 보고 다시 칼을 들어 원수 뒤를 따라 나왔다. 원수가 다시 정신을 가다듬어 좌우로 쳐부수니, 태양검 휘두르는 곳마다 봄날 배꽃이 날리고 가을바람에 낙엽이 지듯 적장의 머리가 떨어져 위와 남경 장졸의 시체가 산처럼 쌓였다. 도독이 원수의 위엄에 의지하여 기운을 수습하고 칼을 휘둘러 장수를 베며 짓쳐 나오니, 적진 장졸의 시체가 언덕 같고 피가 흘러 강물이 되었다. 원수가 도독과 함께 본진에 돌아와 장대에 올라 앉아 장졸에게 상을 내리고 큰 잔치를 벌여 즐기는데, 도독이 친히 잔을 들어 원수께 사례하였다. \"소장이 원수와 한 조정에서 지내는 정의가 있으나, 이렇게 활쏘기와 말타기의 재주를 품어 만 사람을 당할 용맹이 있는 줄은 전혀 몰랐습니다. 오늘 보니 천신이라도 미치지 못하겠으니 어찌 사례하지 않겠습니까.\" 하며 다시 술을 권하였다.","sp":[[3,5,"P","김희경"],[16,18,"P","김희경"],[185,187,"P","김희경"],[206,210,"P","장설빙"],[359,361,"P","김희경"],[443,445,"P","김희경"],[495,497,"P","김희경"],[604,606,"P","도인"]]},{"c":2,"sub":"","t":"한편, 위왕이 남경왕과 함께 본진에 돌아가 군사를 점고하니 죽은 장수가 천여 명이요 죽은 군사가 태반이었다. 위왕이 탄식하였다. \"내가 남을 업신여기다가 이렇게 패하였도다.\" 하고 다시 의논하였다. \"원나라 장수 장수정이 비록 나이 어리나 지혜와 용기를 겸하였고 검술이 남보다 뛰어나 가볍게 대적하지 못하겠소. 과인에게 한 비밀한 계책이 있으나 이 소임을 아무나 맡지 못할 것이니, 청컨대 대왕께서 기꺼이 맡아 주시겠습니까?\" 남경왕이 대답하였다. \"우리 두 나라가 생사를 함께하기로 천지에 맹세하였으니 어찌 서로 사양하겠습니까. 보낼 곳이 있거든 보내 주시기 바랍니다.\" 위왕이 크게 기뻐하며 말하였다. \"원나라 장수정이 병마를 거느리고 여기 왔으니 중원은 틀림없이 비었을 것이오. 대왕께서 지금 한 무리의 군사를 거느리고 물길로 나아가 바로 황성을 겁박하여 원제를 사로잡은 뒤, 다시 군사를 거느려 원수를 치면 반드시 큰일을 이룰 것이니 대왕의 뜻은 어떠하오?\" 남경왕이 다 듣고 크게 기뻐하였다. \"[□]왕의 신기한 계책은 귀신도 미치지 못하겠습니다.\" 하고 마침내 본국 군사를 거느리고 가만히 진을 떠났다.","sp":[[4,6,"P","유협"],[8,11,"P","남경왕"],[61,63,"P","유협"],[119,122,"P","장설빙"],[239,242,"P","남경왕"],[321,323,"P","유협"],[344,347,"P","장설빙"],[426,428,"P","황제"],[485,488,"P","남경왕"]]},{"c":2,"sub":"","t":"위왕이 남경왕을 보내고 진문을 굳게 닫고 여러 날 나오지 않았다. 원수가 도독과 상의하였다. \"이제 위왕이 한번 패한 뒤로 여러 날 숨어 나오지 않으니, 우리가 욕을 하여 분을 돋우어 꾀어내리라.\" 하고 곧 도독에게 한 무리의 군사를 거느리고 성 아래에 나아가 싸움을 돋우게 하였다. 진시부터 유시에 이르도록 위왕이 끝내 응하지 않자 군사를 시켜 무수히 욕을 퍼부었다. 위왕은 본래 성품이 조급하여 분노한 나머지 군사를 시켜 성문을 열고 급히 나와 도독을 향해 크게 꾸짖었다. \"내 오늘 너를 잡아 원수를 갚고 전날 패한 한을 씻으리라.\" 하고 창을 들어 도독을 맞아 싸웠다. 위왕은 본래 용력이 남보다 뛰어나 십여 합에 이르러 도독이 대적하지 못하고 말을 돌려 달아나니 위왕이 급히 뒤쫓았다.","sp":[[0,2,"P","유협"],[4,7,"P","남경왕"],[41,43,"P","김희경"],[56,58,"P","유협"],[116,118,"P","김희경"],[173,175,"P","유협"],[207,209,"P","유협"],[251,253,"P","김희경"],[311,313,"P","김희경"],[323,325,"P","유협"],[352,354,"P","김희경"],[376,378,"P","유협"]]},{"c":2,"sub":"","t":"원수가 문득 진중에서 포 한 방 소리와 함께 진문을 크게 열고, 한 젊은 대장이 나는 듯이 내달아 길을 막으니 위왕이 놀라 고삐를 잡고 섰다. 원수가 크게 꾸짖었다. \"반적 위왕은 장수정을 모르느냐. 내 칼은 본래 사정이 없으니 남은 목숨이 아깝거든 빨리 말에서 내려 항복하라.\" 위왕이 크게 노하여 도독을 버리고 원수와 싸우는데, 원수의 칼빛이 번개같이 빨라 위왕이 크게 놀라 대적하지 못할 줄 알고 말을 돌려 달아나려 하였다. 그때 원수의 칼빛이 번뜩이며 위왕이 탄 말을 내리치니 위왕이 몸을 뒤집으며 말에서 떨어졌다. 원수가 군사에게 호령하여 위왕을 사로잡아 오니, 위국 장졸이 왕이 잡힌 것을 보고 크게 놀라 낯빛을 잃고 각각 목숨을 아껴 사방으로 달아났다. 원수가 의기양양하여 바로 성안으로 들어가 위왕의 가속을 모두 사로잡아 함거에 가둔 뒤 본진에 돌아와 승전고를 울리며 삼군에 상을 주고 백성을 안무하였다.","sp":[[62,64,"P","유협"],[97,99,"P","유협"],[101,104,"P","장설빙"],[157,159,"P","유협"],[168,170,"P","김희경"],[202,204,"P","유협"],[257,259,"P","유협"],[271,273,"P","유협"],[307,309,"P","유협"],[396,398,"P","유협"]]},{"c":2,"sub":"","t":"그리고 도독과 의논하였다. \"위왕을 잡고 성안에 들어왔으나 남경왕의 거처가 없으니 이는 틀림없이 본국으로 달아난 것이오. 이제 남경을 함락하고자 하는데 도독의 생각은 어떠하오?\" 도독이 대답하였다. \"지금 남경을 치지 않으면 이는 돼지를 풀어 주고 사나운 범을 기르는 것이니 어찌 후환을 두려워하지 않겠습니까.\" 뜻이 같았으므로 이에 부장 진합에게 위국을 지키게 하고 대군을 거느리고 남경에 이르러 성 아래에 진을 친 뒤 곧 격서를 보냈다. [?]","sp":[[4,6,"P","김희경"],[16,18,"P","유협"],[33,36,"P","남경왕"],[85,87,"P","김희경"],[100,102,"P","김희경"]]},{"c":2,"sub":"","t":"이때 남경을 지키던 장수 마철이 크게 놀라 스스로 생각하였다. '원나라 대원수가 틀림없이 우리 왕과 위왕을 죽이고 또 이 성을 차지하려고 왔구나. 두 나라 오십만 대군도 당하지 못하였는데 혼자 성을 지켜 대군을 막겠는가. 차라리 이곳에서 항복하여 남은 목숨을 도모하는 것만 못하다.' 하고 곧 성문을 열고 진 앞에 나와 항복하였다.","sp":[[14,16,"P","마철"],[56,58,"P","유협"]]},{"c":2,"sub":"","t":"원수가 속으로 생각하였다. '저것이 틀림없이 거짓 항복하여 나를 꾀어내려는 것이 아닌가.' 하고 큰 소리로 꾸짖었다. \"내 비록 나이 어리나 싸움의 형세를 미리 아니, 네가 어찌 간사한 꾀로 나를 꾀어내려 하느냐.\" 말을 마치고 무사에게 명하여 끌어내 베라 하였다. 무사가 명을 받아 마철을 잡아 진문 밖으로 끌고 가니, 마철이 하늘을 우러러 탄식하였다. \"내가 임금의 원수 갚기를 잊고 내 몸만 살기를 생각하다가, 하늘이 무심하지 않으시어 도리어 재앙을 받으니 누구를 원망하리오.\" 원수가 이 말을 듣고 임금의 원수라는 말을 이상히 여겨 '반드시 무슨 기미가 있구나.' 하고 무사에게 명하여 마철을 가두었다. 그리고 군중에 영을 내려 깃발을 눕히고 진문을 굳게 닫게 하고, 또 가만히 비밀 명령을 내렸다. \"오늘 밤에 만일 적장이 습격해 오더라도 나에게 알리지 말고, 날이 새기 전에는 장졸이 장대에 오지 마라. 만일 영을 어기는 자가 있으면 군법으로 다스리리라.\"","sp":[[159,161,"P","마철"],[180,182,"P","마철"],[332,334,"P","마철"]]},{"c":2,"sub":"","t":"도독과 장졸이 모두 그 뜻을 알지 못하여 매우 의혹하였다. 이에 원수가 홀로 촛불을 밝히고 앉아 병서를 깊이 읽다가, 삼경이 지나자 자연히 몸이 고단하여 잠깐 졸았다. 그런데 홀연 꿈인 듯 생시인 듯 아버님이 곁에 와 앉으시어 길게 한숨지으며 원수의 손을 잡고 머리를 어루만지며 서글피 탄식하셨다. \"지금 나라의 형세가 시급하여 사직은커녕 천자의 자리가 위급하시니 너는 어서 계명산으로 가거라.\" 원수가 한편 기쁘고 한편 슬퍼 크게 놀라 까닭을 물으려다가 놀라 깨니 한바탕 꿈이었다. 마음에 슬픈 가운데 천자의 자리가 위급하다는 말이 분명하였음을 생각하고 의아하여 바삐 창을 여니, 찬 바람이 일어나며 하늘에는 구름 한 점 없고 정신이 매우 맑았다. 원수가 홀로 창을 짚고 가만히 장대에 올라 천문을 살펴보니, 황제의 별이 제자리를 떠나 계명산 서편을 비추고 있었다. 마음속으로 크게 놀라 또 제왕의 별을 살펴보니 남경왕의 장성(將星)이 제자리를 떠나 황성을 범하였는데 그 사이가 멀지 않았다.","sp":[[0,2,"P","김희경"],[190,192,"P","황제"],[282,284,"P","황제"],[398,400,"P","황제"],[456,459,"P","남경왕"]]},{"c":2,"sub":"","t":"원수가 크게 놀라 말하였다. \"늙은 도적놈이 반드시 중원이 빈 줄 알고 가만히 황성에 들어가 황상을 침범하니, 황상께서 막지 못하시어 친히 싸우시는구나. 지금 조정에 충성스럽고 어진 신하가 없고 소인의 무리만 있으니 황상께서 어찌 평안하시겠느냐.\" 하며 울분을 이기지 못하여 곧 도독을 청하여 이러이러하다고 이야기하니, 도독이 크게 놀라 말하였다. \"원수께서는 어찌 아십니까?\" 원수가 정색하고 말하였다. \"장수 된 자가 천문을 모르면 어찌 장수라 하겠소. 지금 천문을 보니 익성(翼星)이 흘러 장안을 범하였는데 익성은 남경왕의 별이요, 자미성(紫微星)이 본궁을 떠났으니 이는 황상의 별이라. 벌써 싸움이 벌어졌소.\" 도독이 몸을 굽혀 사례하였다. \"원수께서는 참으로 천신이시옵니다. 저 같은 장수는 진을 맡더라도 쓸모없는 사람이니 무엇에 쓰겠습니까.\" 원수가 살짝 웃으며 대답하지 않았다. [?]","sp":[[52,54,"P","황제"],[62,64,"P","황제"],[121,123,"P","황제"],[156,158,"P","김희경"],[179,181,"P","김희경"],[291,294,"P","남경왕"],[323,325,"P","황제"],[346,348,"P","김희경"],[374,376,"P","도인"]]},{"c":2,"sub":"","t":"원수가 그 아래 여러 장수를 모으고 군사를 시켜 항복한 장수 마철을 잡아 오라 하니, 이윽고 결박하여 섬돌 아래에 꿇렸다. 원수가 정색하고 말하였다. \"너를 죽여 없애려 하였으나 네가 이미 항복하였기에 남은 목숨을 살려 주니 삼가 조심하라.\" 마철이 머리를 조아려 두 번 절하며 말하였다. \"소장이 죽게 되었는데 원수의 넓으신 덕을 입어 남은 목숨을 보전하니 은혜가 백골난망이옵니다.\" 원수가 위로하고 함께 성안에 들어가 남경왕의 가속을 잡아 묶고 마철에게 성을 지키게 하였다. 그리고 도독에게 말하였다. \"도독은 군사를 거느리고 먼저 장안으로 가시오. 나는 백성을 안돈하고 곧 뒤를 따를 터이니 도독은 빨리 가시오.\" 하고 보낸 뒤, 방을 붙여 백성을 안무하고 후진에게 위왕의 가속을 거느리고 뒤를 따라오라 하였다. [?]","sp":[[34,36,"P","마철"],[136,138,"P","마철"],[236,239,"P","남경왕"],[251,253,"P","마철"],[272,274,"P","김희경"],[284,286,"P","김희경"],[334,336,"P","김희경"],[376,378,"P","유협"]]},{"c":2,"sub":"","t":"원수는 곧 남은 장졸을 거느리고 밤낮으로 행군하여 황성에 이르니, 온 성의 백성이 다 달아나 흩어졌고 황상도 계명산 서편에 이르러 남경 군사에게 싸여 계셨다. 도독이 겨우 진을 이루어 놓았는데 원수가 말하였다. \"지금 적의 형세가 급한데 어찌 진을 치고 머무르겠소.\" 하고 도독과 함께 군사를 재촉하여 계명산 아래에 다다르니, 넓은 들판에 창검이 서리 같고 수많은 적병이 겹겹이 둘러싼 가운데 천자의 한 무리 군사가 갇혀 있었다. 원수가 크게 놀라 도독에게 말하였다. \"지금 형세가 무겁고 황상께서 위태하시니 신하 되어 어찌 죽기를 아끼겠소. 우리가 오늘 생사를 결단할 것이니 도독은 평생의 힘을 다하여 내 뒤를 따라 떨어지지 마시오.\" 하고 칼을 휘두르며 쳐부수어 가운데를 헤치고 짓쳐 들어가니, 동쪽을 치는 듯 서쪽 장수를 베고 남쪽을 향하는 듯 북쪽 진을 쳐부수었다. 그 날램과 무용은 가히 한 시대의 명장이요, 천신이 나는 용을 타고 구름과 안개를 헤치는 듯하였다. 칼날이 번개같이 날리는 곳마다 적진의 장졸이 넋을 잃고 물 끓듯 하여 사방으로 달아났다. [?]","sp":[[57,59,"P","황제"],[89,91,"P","김희경"],[153,155,"P","김희경"],[220,222,"P","황제"],[251,253,"P","김희경"],[274,276,"P","황제"],[323,325,"P","김희경"],[458,460,"P","도인"]]},{"c":2,"sub":"","t":"원수가 말을 채찍질하여 산 아래에 다다르니, 천자가 한 무리 군사를 거느리시고 한 언덕에 의지하여 겨우 진 하나를 이루셨는데 그 위태로움이 경각에 달려 있었다. 원수는 놀라고 당황한 가운데 슬픔을 이기지 못하여 도독과 함께 급히 나아가 엎드려 죄를 청하였다. 이때 황상은 원수와 도독을 변방에 보낸 뒤 뜻밖의 변란을 당하시어 문무 신하와 군사를 거느리고 친히 싸우시다가 적의 형세를 당하지 못하시어 겹겹이 포위되셨으니, 원나라의 흥망이 아침저녁에 달려 있었다. 그런데 문득 적진이 크게 어지러워지며 일시에 무너져 사방으로 흩어지는 것을 보시고 더욱 놀라 어찌할 줄 모르시고 방황하셨으며, 여러 신하도 어찌할 바를 몰라 몸을 피할 방책을 궁리하고 있었다. 멀리 바라보니 한 대장이 칼을 춤추듯 휘두르며 겹겹이 쌓인 수많은 적병을 쳐부수어 지나가는 곳마다 적진 장졸이 물결 갈라지듯 하고, 그 장수 뒤에 또 한 용장이 힘을 합하여 그 많은 적병을 무찔러 적진을 헤치고 황제의 자리 앞에 이르러 말에서 내려 머리를 조아려 절하며 아뢰었다. \"신하 되어 멀리 있어 황상의 위태하심을 모르고 이제야 이르렀으니 죄를 달게 받겠사옵니다.\" [?]","sp":[[25,27,"P","황제"],[118,120,"P","김희경"],[148,150,"P","황제"],[156,158,"P","김희경"],[484,486,"P","황제"],[536,538,"P","황제"]]},{"c":2,"sub":"","t":"황상이 보시니 다른 사람이 아니라 바로 대원수 장수정과 대도독 김희경이었다. 황상이 크게 놀라고 기뻐하시어 급히 두 사람의 손을 잡으시고 반기며 말씀하셨다. \"이렇게 된 것은 다 짐의 덕이 없는 탓이니 어찌 경들의 죄이겠느냐.\" 하시고 자리를 정하신 뒤 패한 사연을 말씀하시며 남경왕의 용맹을 일컬어 말씀하셨다. \"늙은 도적이 세 번 싸우는 동안 대국의 장수 아홉을 죽이고 짐도 이곳에 갇혀 위태로움이 경각에 달렸는데, 경들이 이미 위국을 깨뜨리고 이제 와서 위급함을 구하니 그 충성을 말로 다 못하겠다. 그러나 남경의 늙은 도적은 용맹이 남보다 뛰어나니 경들은 가볍게 대적하지 마라. 내 그것을 근심하노라.\" 원수가 기꺼이 머리를 조아리며 대답하였다. \"이 도적을 위국에서 위왕과 함께 죽이지 못한 것이 한스러울 뿐, 어찌 개돼지 같은 무리를 근심하겠사옵니까.\" 황상이 위국에서 죽이지 못하였다는 말을 모르시어 그 까닭을 물으시니, 원수가 대답하여 남경왕이 위왕과 함께 모반한 이야기며, 위왕을 사로잡고 그 가속을 가두고 남경으로 들어가 그 성을 지키던 장수의 항복을 받아 그로 하여금 지키게 하고, 왕의 가속을 다 죽이고 바로 황성으로 올라온 까닭을 낱낱이 아뢰었다. 황상이 크게 칭찬하시며 말씀하셨다. \"경들의 재주가 이러하니 짐이 어찌 변방을 근심하리오.\"","sp":[[0,2,"P","황제"],[26,29,"P","장설빙"],[32,34,"P","김희경"],[35,38,"P","김희경"],[43,45,"P","황제"],[155,158,"P","남경왕"],[378,380,"P","유협"],[428,430,"P","황제"],[476,479,"P","남경왕"],[481,483,"P","유협"],[498,500,"P","유협"],[600,602,"P","황제"]]},{"c":2,"sub":"","t":"이때 군사가 보고하였다. \"남경왕이 철기를 거느리고 진 앞에 나와 싸움을 돋우옵니다.\" 원수가 분을 참지 못하여 칼을 들고 일어서며 말하였다. \"황상께서는 신의 재주를 보옵소서.\" 하고 나는 듯이 말에 올라 나가니, 황상이 가볍게 대적하지 말라 당부하셨으나 원수는 대답하지 않고 내달아 크게 외쳤다. \"반적은 나를 속이고 이곳에 와서 천자를 범하였으나 내 어찌 네 꾀를 모르겠느냐. 내가 이미 위왕을 사로잡고 또 너의 나라를 함락하고 네 가속을 다 베고 왔으니 빨리 목을 늘여 내 칼을 받아라.\" 남경왕이 장 원수가 온 것을 보고 속으로 크게 놀랐으나 또한 분을 이기지 못하여 긴 창을 휘두르며 급히 달려들어 서로 맞붙어 승부를 다투었다. 원수가 크게 소리 질렀다. \"너 같은 도적을 한 번에 베지 못하면 어찌 장수라 하겠느냐.\" 말을 마치고 칼을 들어 남경왕을 치니, 한 줄기 무지개가 서며 남경왕의 머리가 칼빛을 따라 땅에 떨어졌다. 그 머리를 칼끝에 꿰어 들고 좌충우돌하며 춤을 추며 본진으로 돌아오니, 황상이 도독과 함께 장대에 올라 바라보시다가 몇 합이 되기도 전에 남경왕을 벤 것을 보시고 크게 기뻐하고 칭찬하셨다. \"장수정은 참으로 천신이로다.\" 도독도 그 칭찬을 이어 위국에서 천병만마를 헤치고 자기를 구하던 이야기를 아뢰니 황상이 못내 칭찬하셨다.","sp":[[15,18,"P","남경왕"],[56,58,"P","소세필"],[81,83,"P","황제"],[121,123,"P","황제"],[187,189,"P","황제"],[220,222,"P","유협"],[278,281,"P","남경왕"],[283,287,"P","장설빙"],[422,425,"P","남경왕"],[444,447,"P","남경왕"],[509,511,"P","황제"],[513,515,"P","김희경"],[546,549,"P","남경왕"],[576,579,"P","장설빙"],[585,587,"P","도인"],[593,595,"P","김희경"],[638,640,"P","황제"]]},{"c":2,"sub":"","t":"원수가 장대에 나아가 남경왕의 머리를 올리니 황상이 크게 기뻐하시어 원수의 손을 잡으시고 칭찬을 그치지 않으시며 말씀하셨다. \"경의 재주는 참으로 만고에 둘도 없도다. 짐이 어찌 변방을 근심하리오. 이제 두 나라를 깨뜨려 경의 공이 적지 않고 국가의 큰 다행이니 무엇으로 경의 공을 갚으리오. 짐이 환궁한 뒤 천하를 반으로 나누리라.\" 원수가 황공하여 머리를 조아리며 아뢰었다. \"이는 다 폐하의 큰 복이요 여러 장수의 힘이지 신의 공이 아니옵니다.\"","sp":[[12,15,"P","남경왕"],[25,27,"P","황제"]]},{"c":2,"sub":"","t":"이때 남경 군졸이 자기 왕이 죽은 것을 보고 놀라 서로 전하였다. \"장 원수의 용맹은 만 명의 장부라도 당하지 못할 것이요, 두 나라가 이미 함락되었으니 우리도 속히 항복하여 목숨을 도모하는 것이 좋은 방책이다.\" 하고 일시에 항복하였다. 황상이 불러 보시고 각각 상을 내리신 뒤 놓아 보내시며 고향에 돌아가 부모와 처자를 봉양하라 하시니, 모든 장졸이 서로 즐거워하며 성덕을 축수하여 만세를 부르는 소리가 천지를 울렸다.","sp":[[38,42,"P","장설빙"],[134,136,"P","황제"]]},{"c":2,"sub":"","t":"이에 황상이 군사를 돌려 황성에 환궁하신 뒤 출전하였던 장졸을 위로하셨다. 장 학사를 청주후에 봉하시고, 이부상서 장자영을 추증하여 위국왕에 봉하시고 금은보화를 많이 내리시며 조서를 내려 말씀하셨다. \"청주후 장수정은 위국왕의 외로운 혼을 위로하라.\" 예관에게 명하시어 제문과 제물을 내리시고, 김 한림은 일품 상서로 삼으시고 평장사를 승상으로 높이시며 금은보화를 많이 내리셨다. 나머지 장수들도 차례로 벼슬을 높이시고 사졸들에게는 돈과 베를 많이 내리시니 모든 장졸이 성은을 축수하였다. 이때 후군장이 위왕을 잡아 대령하니, 황상이 분하셨으나 특별히 인륜의 정을 돌아보시어 곤장 오십 대를 무겁게 치시고 본국으로 보내시되, 위국의 십만 호를 깎아 본국(원나라)에 붙이셨다. 그리고 큰 잔치를 베풀어 즐기시는데 황상이 친히 잔을 잡아 원수와 도독에게 권하며 칭찬하시니, 두 사람이 어주를 받들어 머리를 조아리며 사은하였다. \"이 모두 폐하의 넓으신 덕이요 여러 장수의 충성이니 어찌 신들의 공이 되겠사옵니까.\" 황상이 위로하여 말씀하셨다. \"경들이 아니었으면 원나라의 사직과 짐의 목숨이 어찌 오늘처럼 있겠느냐.\" 두 사람이 머리를 조아려 사은하고 물러 나왔다. [?]","sp":[[3,5,"P","황제"],[42,46,"P","장설빙"],[48,51,"P","장설빙"],[64,67,"P","장자영"],[113,116,"P","장설빙"],[117,120,"P","장설빙"],[165,169,"P","김희경"],[183,186,"P","김평"],[282,284,"P","유협"],[295,297,"P","황제"],[398,400,"P","황제"],[415,417,"P","김희경"],[510,512,"P","황제"]]},{"c":2,"sub":"","t":"김 상서가 집에 돌아오니 부모와 친척과 최씨가 맞아 반기며 기뻐하여 온 집안이 떠들썩하였다. 학사도 만 리 위험한 땅에 가서 반년 만에 공을 세우고 무사히 돌아왔으나, 부모의 영화와 반겨 줄 이가 없으니 슬픔을 금치 못하여 사당에 들어가 한바탕 통곡한 뒤 곧 소 부인께 뵈었다. 부인이 오래 그리던 정으로 못내 반겼고, 설낭과 영춘도 오래 그리며 조심하다가 공을 이루고 무사히 돌아오니 반기며 즐거운 가운데 옛 주인을 추모하여 한편 기쁘고 한편 슬퍼하였다. [?]","sp":[[0,4,"P","김희경"],[22,24,"P","최씨"],[179,181,"P","설낭"],[183,185,"P","영춘"]]},{"c":2,"sub":"","t":"이후로는 천하가 태평하고 나라에 일이 없었다. 상서는 청주후와 함께 조회를 마치면 날마다 서당에 모여 시와 술로 소일하였다. 이럭저럭 이듬해 가을이 되어 국화가 만발하고 단풍이 더욱 아름다웠다. 마음이 심심하고 즐겁지 않아 강호의 풍경을 생각하고 상서가 학사를 청하여 말하였다. \"이제 우리가 바야흐로 중양절을 맞으니 강호의 경치가 볼 만할 것이오. 변방의 티끌이 고요하고 조정에 일이 없으니 예전에 보던 풍경을 다시 찾아가는 것이 어떠하오?\" 학사도 그런 뜻이 있었기에 기꺼이 응낙하고 가려 하였다. 그런데 문득 황상이 학사와 상서를 부르시니, 두 사람이 무슨 일인지 모르고 곧 조복을 갖추고 함께 대궐에 나아갔다. 황상이 보시고 말씀하셨다. \"요사이 경들을 자주 보지 못하여 불렀노라.\" 하시고 연왕을 부르시니, 연왕이 들어와 황상께 뵙고 다음으로 학사와 상서에게 예를 갖추어 뵈었다. 두 사람이 황공함을 이기지 못하여 공경히 답례하니 황상이 웃으며 말씀하셨다. \"연왕이 비록 짐의 친아들이나 경들의 제자이니 어찌 불안해하느냐.\" 두 사람이 머리를 조아려 감당할 수 없다고 아뢰었다.","sp":[[30,33,"P","장설빙"],[288,290,"P","황제"],[346,348,"P","황제"],[391,393,"P","연왕"],[401,403,"P","연왕"],[409,411,"P","황제"],[470,472,"P","황제"],[486,488,"P","연왕"]]},{"c":2,"sub":"","t":"황상이 명을 내리시어 어주를 내어 두 사람에게 권하시니, 두 사람이 황공함을 이기지 못하여 성은이 융숭함을 축수하고 종일토록 모시고 이야기하였다. 밤이 깊은 뒤 여러 신하를 물리시고 상서와 학사를 가까이 오라 하여 두 사람의 손을 잡으시고 은근히 아끼시다가, 용안에 웃음을 띠고 말씀하셨다. \"짐이 경들에게 부탁할 말이 있으니 기꺼이 허락하겠느냐?\" 두 사람이 성의를 깨닫지 못하여 엎드려 아뢰었다. \"무슨 칙교이신지 듣고자 하옵니다.\" 황상이 기뻐하시며 말씀하셨다. \"짐이 늘그막에 딸 둘을 두었는데, 맏딸은 일월공주요 둘째는 명월공주라. 연왕의 동기로 궁중에서 자라 비록 견문은 얕으나 덕행은 오히려 태임과 태사에 뒤지지 않아 군자의 수건과 빗을 받들 만하다. 그러므로 군자를 가려 뽑고자 하였는데 여러 신하 가운데 오직 경들 두 사람뿐이라. 이로써 진정을 펴니 경들은 부디 미루지 말고 쾌히 허락하여, 신하이자 친척의 정분을 겸하여 짐의 사위가 되면 국가의 부귀를 함께 누릴까 하노라.\" 두 사람이 천만뜻밖에 이런 분부를 받으니 마음이 어지러워 대답할 말이 없다가, 이윽고 상서가 머리를 조아려 아뢰었다. \"분부가 이렇게 미천한 신에게 미치시니 황공하기 그지없어 아뢸 말씀이 없사오나, 신들이 어찌 폐하의 성덕을 미루겠사옵니까. 다만 신은 승상 최후의 딸에게 장가들어 인륜을 정하였사오니 하해 같은 성덕을 받들지 못할까 하옵니다.\"","sp":[[0,2,"P","황제"],[245,247,"P","황제"],[286,290,"P","일월공주"],[296,300,"P","명월공주"],[303,305,"P","연왕"],[644,646,"P","최후"]]},{"c":2,"sub":"","t":"황상이 또 말씀하셨다. \"짐이 이 일을 모르는 것이 아니다. 조강지처를 위엄으로 폐하는 법은 없게 할 것이니 경은 조금도 염려하지 마라. 최씨를 정실로 삼고 일월공주를 둘째로 삼아 백년을 편안히 누리면 이 또한 좋은 일이라. 후세 사람이 짐의 약함을 비웃겠지만, 이는 약한 것이 아니라 경의 재주를 사랑하여서이며, 위세로 인륜을 흩뜨리지 않으려는 것이니 경은 털끝만큼도 의심하지 말고 쾌히 따르라.\" 상서가 다시 아뢰었다. \"폐하의 성덕이 이러하시니 천은이 망극하오나, 예로부터 사사로운 정 때문에 국법을 폐한 일이 없사오니, 비록 성은을 내리시더라도 어찌 공주를 욕되게 하겠사옵니까. 엎드려 바라옵건대 폐하께서는 어진 군자를 골라 부마를 정하옵소서.\" 황상이 기꺼이 대답하셨다. \"경의 말이 매우 외람되도다. 하늘이 이미 경과 수정을 내셨으니 세상에 또 어찌 군자가 있겠느냐. 짐이 이미 마음에 정하였으니 일월공주는 경에게 시집보내고 명월공주는 장수정에게 시집보낼 것이니 부디 사양하지 마라.\" 말씀이 부드러우시나 위풍이 늠름하시니 다시 드릴 말씀이 없어 다만 사은할 뿐이었다.","sp":[[0,2,"P","황제"],[77,79,"P","최씨"],[88,92,"P","일월공주"],[312,314,"P","일월공주"],[354,356,"P","김희경"],[366,368,"P","황제"],[408,410,"P","장설빙"],[452,456,"P","일월공주"],[468,472,"P","명월공주"],[474,477,"P","장설빙"]]},{"c":2,"sub":"","t":"황상이 또 학사에게 말씀하셨다. \"경들의 어짊과 재주를 사랑하여 평생의 친분을 정하고자 하노니, 짐의 두터운 정을 생각하여 조금도 거리끼지 마라.\" 학사는 비록 소진의 말재주와 강직한 기운을 지녔으나, 이 말씀을 당하자 마음이 떨려 속으로 생각하였다. '희경은 비록 조강지처가 있어도 할 말이 없어 사양하지 못하는데, 하물며 나는 부모가 아니 계시니 내 마음대로 할 수 있는 처지요, 또 부모의 가르침을 들은 바도 없다 할 것이니 무슨 말로 황상의 뜻을 막겠는가.' 이러하니 끝내 사양할 말이 없어 다만 엎드려 사은할 뿐이었다. 황상이 다시 묻지 않으시고 말씀하셨다. \"밤이 이미 깊었으니 경들은 물러가 쉬어라.\"","sp":[[0,2,"P","황제"],[142,144,"P","김희경"],[247,249,"P","황제"],[296,298,"P","황제"]]},{"c":2,"sub":"","t":"두 사람이 사은하고 물러 나와 대궐 문밖에서 각각 돌아가려 할 때, 상서가 학사에게 말하였다. \"나는 이미 아내를 얻은 사람이라 기쁠 것이 없소. 공주가 시집온 뒤 만일 불편해하여 조강지처를 용납하지 못하게 하면 이는 남에게 원한을 끼치는 것이라 이것이 깊은 근심이오. 그러나 형은 아직 혼인을 이룬 바가 없으니 근심할 일이 아니라, 앞으로 궁중의 온전한 부귀를 누릴 것인데 어찌 사양하겠소.\" 학사가 말하였다. \"형의 말이 그르도다. 봉은 황을 따르고 까마귀는 까마귀를 따르는 법이니, 황천(皇天)의 딸을 맞는 것이 무엇이 좋겠소. 게다가 내가 일찍이 이 참정의 기르신 은혜를 입었는데, 참정이 임종할 때 그 딸을 나에게 의탁하기로 정하였으니 비록 혼례는 올리지 않았으나 서로 언약이 완전하오. 이제 공주를 맞는다면 이는 은혜를 배반하고 의리를 잊는 것이니 남자로서 차마 못할 일이라, 결단코 황명을 따르지 않을 것이오. 그러나 성덕을 배반하는 것은 어질지 못하고 충성스럽지 못한 일이라 다만 물러 나왔으나 형세가 난처하오.\" [?]","sp":[[82,84,"P","일월공주"],[310,314,"P","이영찬"],[330,332,"P","이영찬"],[393,395,"P","일월공주"]]},{"c":2,"sub":"","t":"상서가 크게 놀라 말하였다. \"그렇다면 형은 어찌 진정을 아뢰지 않았소?\" 학사가 웃으며 말하였다. \"형이 아내가 있는 것도 꺼리지 않으시는데 내가 정혼한 것을 드러내겠소. 그래서 말하지 못하였거니와, 이제 집에 돌아가 내일 표를 올려 죽기로 거절하고자 하오.\" 상서가 말하였다. \"그렇지 않소. 이 참정의 언약도 어렵고 황상의 두터운 은혜도 저버리지 못할 것이니, 어쨌든 임금의 명을 따른 뒤에 다시 아뢰어 이 참정의 유언을 따르면 이는 충과 의를 모두 온전히 하는 것이오. 잘 생각하여 후회를 남기지 마시오.\" 학사는 목이 메어 대답하지 않고 각각 집으로 돌아갔다.","sp":[[166,170,"P","이영찬"],[180,182,"P","황제"],[229,233,"P","이영찬"]]},{"c":2,"sub":"","t":"김 상서가 부모께 나라의 명을 아뢰니 평장과 부인이 크게 놀라 한참 말이 없다가 최씨를 향해 말하였다. \"공교롭게도 공주가 시집오면 지존의 혈맥이라, 만일 어질지 못하면 어진 며느리가 참혹하게 될 터이니 어찌하리오.\" 하며 마음이 편치 않아 마지않았다. 그러나 최씨는 조금도 두려워하는 빛이 없이 얼굴빛을 태연히 하고 말을 온화하게 하여 말하였다. \"이는 다 하늘의 명이요 남자의 좋은 일이니 어찌 미리 근심하겠사옵니까. 공주가 시집오면 조강지처를 폐하는 것이 떳떳한 국법이온데, 황상의 은덕이 지중하시어 부녀의 정을 헤아려 주시니 하해 같은 덕을 참으로 감축할 일이라 어찌 근심하겠사옵니까. 바라건대 시부모님께서는 달리 염려하지 마소서. 순순히 황명을 따라 후환을 면한다면 이는 화가 바뀌어 복이 되는 것이오니, 다시 생각하시어 하늘의 뜻을 거스르지 마소서.\" 최씨 부인의 말이 법도가 있고 기색이 부드러워 조금도 근심하는 빛이 없으니 온 집안사람이 모두 칭찬하였다. 평장도 낯빛을 고치며 말하였다. \"착하도다. 네 말은 희경이 미칠 바가 아니로다. 공주의 어진 마음이 만일 이와 같다면 어찌 근심하리오.\" 하며 감탄해 마지않았고, 상서는 더욱 그 바른 마음에 탄복하였다.","sp":[[0,4,"P","김희경"],[21,23,"P","김평"],[45,47,"P","최씨"],[65,67,"P","일월공주"],[146,148,"P","최씨"],[236,238,"P","일월공주"],[269,271,"P","황제"],[427,429,"P","최씨"],[487,489,"P","김평"],[517,519,"P","김희경"],[533,535,"P","일월공주"]]},{"c":2,"sub":"","t":"이튿날 태사관이 황명을 받들어 길일을 가려 두 집에 알리니, 불과 며칠 뒤였다. 이때 장 학사는 집에 돌아와 조복을 벗고 시름없이 책상에 비스듬히 앉아 천만 가지로 헤아려도 황명을 면할 길이 없으니, 가슴이 막혀 울적한 마음을 진정하지 못하였다. 그런데 문득 태사관이 길일을 전하니 더욱 크게 놀라 어찌할 줄 모르고, 허둥지둥 먹고 마시기를 모두 끊고 근심과 시름에 잠겨 하염없이 눈물이 떨어져 옷깃을 적셨다. 설낭과 영춘이 그 기미는 모르고 행여 나라에 무슨 일이 있는가 하여 학사에게 나아가 말하였다. \"소저께서 평소 좋은 일이든 궂은 일이든 소비들을 남처럼 대하신 적이 없었는데, 오늘은 어찌 홀로 여느 때와 달리 시름이 첩첩하시니 무슨 일이옵니까?\"","sp":[[48,52,"P","장설빙"],[230,232,"P","설낭"],[234,236,"P","영춘"]]},{"c":2,"sub":"","t":"학사가 대답하였다. \"세상에서 사람이 천지를 속이고 남녀를 가리면 참으로 재앙이 없을 수 없구나. 이제 황상께서 나를 부마로 삼고자 하시니, 비록 남자라도 즐겁지 않을 터인데 하물며 나는 근본이 규중의 여자라. 지금 황명을 거역하기도 어렵고, 따르자니 나중에 처리할 방도가 아득하구나. 장차 어찌하면 모든 일이 평안하겠느냐. 너희는 비록 여자이나 생각해 보아라. 내가 비록 여자이나 세상에 나서 온갖 풍상을 겪고, 이제 급제하여 벼슬이 공후에 이르니 조정이 다 내 지혜를 따르고 황상께서도 내 말씀을 따르시니, 변방에 나가서도 두려운 것이 없었다. 그런데 오늘 이 일을 당하니 가슴이 아득하고 정신이 어지러워 이리저리 생각해도 계교가 없고 형세가 둘 다 어려우니 이 일이 작은 일이 아니다. 너희는 식견이 넓으니 혹 깊은 식견이 있는가 묻노니, 어찌하면 좋겠느냐. 황상의 뜻을 따르면서 내 몸이 평안할 수 있는 길을 생각해 보아라.\"","sp":[[58,60,"P","황제"],[66,68,"P","김희경"],[268,270,"P","황제"],[428,430,"P","황제"]]},{"c":2,"sub":"","t":"영춘이 이 말을 듣고 놀라 낯빛을 잃고 한참 생각하다가 말하였다. \"이는 반드시 하늘이 시키시는 것이요 사람의 힘이 아닌 줄을 어찌 모르십니까. 하늘이 사람을 내시매 남녀를 분간하여 인륜을 정하셨거늘, 소저께서 하늘의 뜻을 거슬러 칠 년을 남자로 지내며 음양의 도리를 폐하였으니, 사람은 무심히 속는다 해도 하늘이 어찌 무심하시겠사옵니까. 그러므로 이제 공주의 몸을 빌려 소저의 여자의 도리를 회복하게 하시려는 것입니다. 이 일이 아니면 누가 능히 소저의 뜻을 돌이켜 깨닫게 하겠사옵니까.\"","sp":[[0,2,"P","영춘"],[198,200,"P","일월공주"]]},{"c":2,"sub":"","t":"\"소저께서 이제 나이 스물로 꽃다운 때를 넘기셨으니, 김 상서를 속인 것도 오래되었고, 또 나이가 차도록 수염이 나지 않고 장가를 들지 않으시면 세상 사람들이 다 의심할 것입니다. 그때를 당하면 소저께서 비록 소진의 말재주와 제갈량의 지혜가 있다 해도 어찌 세상 사람의 입을 막겠사옵니까. 이때를 타서 황상께 사정을 아뢰지 않고 지금 황명을 따른다면 나중에 처리하기 어려울 것입니다. 남의 의심을 따라 일이 탄로 나면 곤궁하게 남의 웃음을 면치 못할 뿐 아니라 당대에 용납되지 못할 죄인이 될 것이니, 그때 신의를 잃은 웃음거리를 어찌하겠사옵니까. 옛글에 하늘을 따르는 자는 번창하고 하늘을 거스르는 자는 망한다 하였사오니, 소저께서 이제 하늘이 시키시는 일을 따르지 않으시면 나중을 어찌하려 하시옵니까. 소저께서는 깊이 살피시어 이런 때를 타서 진정을 아뢰고, 사모를 화관으로 바꾸고 옥띠를 붉은 치마로 갈아입어, 옥 가마와 비단 휘장 가운데 아름다운 학사의 숙녀가 되신다면 이는 여자의 기특한 스스로의 밝음이라 후세의 칭찬을 받을 것입니다. 그렇지 않으면 천고의 비웃음을 면치 못할 것이니, 소저께서는 세 번 생각하시어 뒷날에 거리낌이 없게 하옵소서.\" 하며 누누이 간하였다. [?]","sp":[[30,34,"P","김희경"],[169,171,"P","황제"]]},{"c":2,"sub":"","t":"학사가 다 듣고 나서 얼굴빛이 태연하고 기운도 차분해져 곰곰이 생각해 보니, 그 말이 당당하고 이치에 맞았다. 홀연 깨닫고 말하였다. \"착하도다. 네 소견이 밝고 밝으니 내가 어찌 미치겠느냐. 애석하다, 나의 일이여. 조정의 모든 관원과 천하의 백성이 내 이름을 들으면 두려워하지 않는 이가 없었는데, 하루아침에 하늘과 땅이 바뀌어 옥당의 대신이 깊은 규중의 여자가 되니 어찌 한심하지 않으리오. 칠 년의 공업이 속절없이 그림자의 넋이 되는구나.\" 하며 흐느끼고 허탈하여 길게 탄식해 마지않았다. 영춘이 타일렀다. \"소저의 말씀은 하나만 알고 둘은 모르시는 것입니다. 예로부터 공명은 화의 근본이라, 누추한 줄 모르고 물러가지 않으면 나중에 재앙이 미칩니다. 그러므로 도연명이 두목지를 부끄러워하여 비단 휘장을 불사르고 갓끈을 문에 걸었으며, 장한(張翰)은 강동을 잊지 못하여 가을 꿈에 돌아갔으니, 옛사람의 빛나는 이름이 만세에 전해지는 것입니다. 어찌 세상의 부귀공명을 길이 탐하겠사옵니까.\" 학사는 다만 길게 탄식할 뿐이더니, 문득 붓과 벼루를 내어 표를 지어 소매에 넣고 문밖에 나가 달 아래를 한참 거닐다가 밤 깊은 뒤 들어와 뒤척이며 잠을 이루지 못하였다. [?]","sp":[[278,280,"P","영춘"]]},{"c":2,"sub":"","t":"동녘이 밝자 표를 올렸는데 표에 이렇게 쓰여 있었다. \"태학사 병부상서 연왕 태부 청주후 장수정은 삼가 백 번 절하고 머리를 조아려 진정표를 올리옵니다. 신첩은 죄악이 무거워 본래 깊은 규중의 약한 몸으로 운명이 기박하여, 열 살 전에 어머니를 여의고 아비의 남은 목숨을 따라 겨우 부지하였습니다. 남은 액운이 다하지 않아 아비가 소인의 참소를 입어 북해로 귀양 가니 신첩 한 몸이 의지할 곳이 없었습니다. 아비가 이 일로 크게 근심하였으나 황명이 지중하여 머무르지 못하고, 어찌할 수 없어 유모와 시비에게 신첩 한 몸을 부탁하고 떠나갔으니, 그때 부녀의 망극한 정은 다시 아뢸 말씀이 없사옵니다. 한번 이별이 북해로 망극하게 되니 두 번 만날 기약이 아득하였습니다.","sp":[[40,42,"P","연왕"],[46,49,"P","장설빙"],[50,53,"P","장설빙"],[275,277,"P","설낭"]]},{"c":2,"sub":"","t":"죽어서 모든 일을 잊고자 하였으나 부모의 혈육이 신첩 한 몸뿐이라 차마 아비의 바람을 끊지 못하여 남은 목숨을 부지하였사옵니다. 그러나 혈혈단신으로 의탁할 데가 없고 규중의 처신에 인심이 두려워, 어미의 외사촌인 정 시랑 아저씨를 찾아가던 중 탁주 땅에 이르렀는데, 지금의 이부상서 김희경이 마침 지나가다가 신첩이 그리로 간다는 것을 듣고 예로써 혼인을 구하였습니다. 신첩은 아비의 부탁을 받아 앞날을 유모의 주장에 맡겼으므로, 유모가 희경의 사람됨에 감탄하여 곧 허락하고 뒷날 정 시랑을 찾아 혼례를 이루기로 언약하였습니다. 신첩의 단심으로는 아비가 귀양지에서 원한을 풀기 전에는 스스로 혼처를 정하여 사람을 따르는 것이 옳지 않으므로, 아비가 성은을 입어 돌아오기를 기다려 혼례를 올리기로 정하였습니다. 희경도 예를 폐하지 못하여 신첩의 소원을 따랐으나 세상일을 정하지 못하는 까닭에 옛일을 본받아, 희경의 백옥 서진과 신첩의 가락지를 바꾸어 뒷날을 정한 뒤 각각 길을 떠났사옵니다. [?]","sp":[[119,123,"P","정 시랑"],[158,161,"P","김희경"],[225,227,"P","설낭"],[240,242,"P","설낭"],[244,246,"P","김희경"],[268,272,"P","정 시랑"],[396,398,"P","김희경"],[450,452,"P","김희경"]]},{"c":2,"sub":"","t":"신첩이 탁주의 정 아저씨를 찾아 천신만고 끝에 가니 죄악이 갈수록 심하여, 정 시랑은 이미 죽고 자식이 없어 아주머니는 그 외조카를 찾아 먼 곳으로 가고 없었습니다. 혈혈단신으로 멀고 험한 길을 걸어갔다가 바라던 바가 끊어지니 의지할 곳이 없어 형세가 아득하였습니다. 사람이 위급한 지경을 당하니 천지가 망극한 가운데 아비를 보고 싶은 마음을 걷잡지 못하여 국법을 잊고 외람된 생각을 내어 북해로 가려 하였으나, 만 리 먼 길에 여자의 홑몸으로 다다르기 어려웠사옵니다.","sp":[[8,13,"P","정 시랑"],[18,20,"P","도인"],[42,46,"P","정 시랑"]]},{"c":2,"sub":"","t":"부득이 천지를 속여 남녀를 바꾸어 시비와 함께 남복으로 갈아입고 멀고 험한 길을 걸어 겨우 다다르니, 하늘의 재앙이 다하지 않아 아비가 병이 깊어져 이미 세상을 떠난 지 석 달이었습니다. 그 망극함은 온 세상에 신첩 한 사람뿐이라 천지가 아득한 가운데, 전 참지정사 소세필이 아비와 옛 정이 있어 터를 잡아 시신을 감장하였으나 아비의 혼은 구천에 막혔으니 간담이 부서지고 온몸이 가루가 되는 듯하였습니다. 곧 목숨을 버려 아비의 외로운 혼을 위로하고자 하였으나, 아비의 백골이 만 리 객지에서 썩는 것이 더욱 망극하여 남은 목숨을 겨우 부지하여 아비의 유골을 옮겨 선산에 안장하고 삼 년을 지냈습니다. 그래도 세상에 뜻이 없어 목숨을 버리고자 하였으나 부모의 영혼을 위로할 사람이 없는 까닭에 남은 목숨을 부지하였사옵니다. 그러나 주관할 이도 의지할 데도 없어 강도의 욕을 볼까 겁이 나서, 묘 아래를 떠나 동서로 떠돌 때 여자의 도리를 지키고자 하였으나 의지할 데 없는 몸이라 처신이 어려워 남복을 벗지 못하고 떠돌며 빌어먹으며 세월을 보냈사옵니다.","sp":[[144,146,"P","소세필"],[149,152,"P","소세필"]]},{"c":2,"sub":"","t":"유모와 시비 등이 희경을 생각하고 찾아가 의지하고자 갔더니 희경도 고향을 떠나 종적이 아득하였사옵니다. 갈 곳이 없으니 이 지경에 이르러서는 백 번 죽어 마땅한 몸이 세상에 머물러 조금도 이로울 것이 없어, 병진년 칠월 보름에 유모와 시비 세 사람이 벽해수에 몸을 던졌사옵니다. 주인과 종 세 사람의 혼백이 푸른 물결을 따라 떠돌던 중, 하늘이 살피시어 마침 전 참지정사 이영찬이 뱃놀이를 하다가 사람의 시신이 물결에 뜬 것을 보고 가엾게 여겨 건져 내었습니다. 이미 죽은 것을 약을 써서 세 사람을 살려 내니 은혜가 망극한 가운데, 신첩이 의지할 데 없는 것을 불쌍히 여기고 아비와 죽마고우였다 하며 더욱 측은히 여겨 주인과 종 세 사람을 제 집으로 데려가 길러 주었습니다. 여러 해가 되어 정의가 자못 깊었는데, 하루는 영찬이 신첩의 어리석음을 생각지 못하고 딸이 하나 있다며 혼약을 맺고자 하니 무슨 핑계로 그 뜻을 막겠사옵니까. 참으로 민망하였사옵니다. [?]","sp":[[0,2,"P","설낭"],[10,12,"P","김희경"],[33,35,"P","김희경"],[127,129,"P","설낭"],[203,205,"P","소세필"],[208,211,"P","이영찬"]]},{"c":2,"sub":"","t":"마침 과거 소식을 듣고 잠깐 피하여 나중을 도모하고자 서울로 왔다가, 전해 들으니 김희경이 이미 최후의 딸을 아내로 맞았다 하였습니다. 신첩이 비록 찾아가고자 하였으나 희경은 신의 있는 사람이라 반드시 신첩의 종적을 알면 결단코 버리지 않을 것이요, 그리되면 최후의 딸이 자연히 불안할 것이니, 남의 금슬을 흩뜨린다 하여 생각을 접었사옵니다. 그런데 외람된 마음이 스스로 일어나, 차라리 급제하여 높은 벼슬에 오르면 아비의 원한을 씻고 조상의 제사를 받들 수 있겠다 하여 감히 하늘의 총명을 가리고 과거장에 참여하였사옵니다. 성은을 입어 요행히 급제하고 이제 벼슬이 공후에 이르니 부귀영화가 한 몸에 극진하였사옵니다. 밤낮으로 조심하고 두려워하며 충성을 다하여 성덕을 만분의 일이나마 갚고 세상을 하직하고자 바랐는데, 갈수록 천은이 망극하시어 이제 공주를 신첩에게 시집보내려 하시니, 신첩이 황공하기 그지없어 분부를 받들 말씀이 없었기에 물러 나와 한 장의 표로 진정을 아뢰옵니다. 칠 년 동안 성총을 가렸으니 죄가 죽어도 아깝지 않거늘 어찌 방자한 뜻을 두어 근본을 숨기겠사옵니까. 전날 변방에 나아가 천병만마를 당하여도 조금도 두렵지 않았는데, 분부가 이러하신 뒤로는 넋이 날아가고 우레와 벼락이 머리를 누르는 듯하오니, 신첩의 임금을 속이고 윗사람을 업신여긴 죄를 다스리시어 뒷사람을 경계하옵소서.\"","sp":[[46,49,"P","김희경"],[54,56,"P","최후"],[94,96,"P","김희경"],[145,147,"P","최후"],[419,421,"P","일월공주"]]},{"c":2,"sub":"","t":"황상이 다 보시고 크게 놀라 한참 말씀이 없으시다가 다시 두세 번 그 표를 보시고 용상을 치시며 크게 칭찬하셨다. \"착하고 아름답도다. 어찌 만고에 이런 일이 있으리오. 기특하다, 장수정이여. 세상의 여자로서 어찌 이런 큰 지략이 있었는고. 문필은 말할 것도 없고 무예 또한 이같이 장하니 참으로 기이하도다.\" 하시며 감탄을 그치지 않으셨다. 이때 연왕과 제왕이며 좌우의 여러 신하가 모두 놀라지 않는 이가 없었다. [?]","sp":[[0,2,"P","황제"],[101,104,"P","장설빙"],[195,197,"P","연왕"]]},{"c":2,"sub":"","t":"황상이 다시 길게 탄식하셨다. \"애석하다. 짐이 믿던 바는 수정과 희경뿐이었는데 수정이 이제 조정을 하직하니 참으로 짐의 한 팔을 잃었도다. 어찌 아깝지 않으리오.\" 하시고 비답을 내리셨다. \"천만뜻밖에 경의 상소를 보니 한편 놀랍고 한편 아름다움을 이루 다 말할 수 없도다. 짐이 경의 재주를 사랑하여 두터운 인연을 맺고자 하였더니 뜻을 이루지 못하고 도리어 나라의 기둥 같은 신하를 잃으니, 짐이 오른손을 잃은 듯하여 뉘우쳐도 소용없도다. 짐이 경들을 얻은 뒤로는 태자와 연왕, 제왕은 두어 달을 못 보아도 그립지 않았으나 오직 경들은 하루만 못 보아도 그리움이 끝이 없었는데, 이제 이를 당하니 어찌 슬프지 않으리오. 경의 진정이 이러하나 짐이 경의 공을 저버리는 것 또한 덕이 없는 일이 아니겠느냐. 그러므로 대사마는 여자에게 맞지 않으니 인수를 거두되, 태학사는 본래의 직책이니 그대로 두어 경의 공을 표하노라. 한 달에 두 차례씩 조회를 폐하지 말고 짐의 뜻을 저버리지 마라.\"","sp":[[0,2,"P","황제"],[33,35,"P","장설빙"],[37,39,"P","김희경"],[45,47,"P","장설빙"],[266,268,"P","연왕"]]},{"c":2,"sub":"","t":"학사가 분부를 받들어 감축함을 이기지 못하여 감당할 수 없다고 사양하였으나 황상이 윤허하지 않으시니, 학사가 마지못하여 엎드려 사은하고 집에 돌아왔다. 바로 부모님 사당에 나아가 두 번 절하고 통곡하며 남자에서 여자로 돌아가는 뜻을 고하고 옷을 갈아입으니, 정정한 남자가 문득 변하여 아리따운 여자가 되었다. 학사가 슬픔을 금치 못하여 한바탕 통곡을 그치지 않으니, 설낭과 영춘이 갖은 말로 달래어 그치게 하였다.","sp":[[42,44,"P","황제"],[205,207,"P","설낭"],[209,211,"P","영춘"]]},{"c":2,"sub":"","t":"이날 황상이 장수정의 행적을 못내 감탄하시어 그 표를 조정에 내려 여러 신하에게 보이시니, 모든 관원이 보고 칭찬하지 않는 이가 없었다. 이때 상서 김희경도 그 표를 보고 놀라움과 감탄을 이기지 못하여 한참 말이 없었으나, 눈썹 위에 기쁜 기운이 가득하여 은은히 기뻐하였다. 이에 그 표를 소매에 넣고 집에 돌아오니, 평장과 부인이 최씨와 함께 여러 사람과 이야기하고 있었다. 상서가 들어가 자리에 앉은 뒤 소매에서 한 장의 표를 꺼내 자리에 놓고 장 학사의 일을 갖추어 말하니, 평장이 그 표를 보고 크게 놀라 탄식하였다. \"그 스스로의 밝음이 이러하며 또 충성이 어찌 이렇게 장하리오.\" 하며 감탄해 마지않으니 모든 사람이 탄복하지 않는 이가 없었다.","sp":[[3,5,"P","황제"],[7,10,"P","장설빙"],[83,86,"P","김희경"],[178,180,"P","김평"],[186,188,"P","최씨"],[251,255,"P","장설빙"],[269,271,"P","김평"]]},{"c":2,"sub":"","t":"평장이 상서에게 말하였다. \"그가 이미 근본을 스스로 밝혀 벼슬을 내놓고 규중에 들었으며, 표에서 혼약을 맺은 일과 절개를 지킨 일을 펼쳐 보였으니 이는 오로지 너의 근심이다. 너는 지금 최씨가 있고 또 공주와 혼인하게 되었으니 장씨를 마음대로 하지 못할 터인데, 네 생각은 어떠하냐?\" 상서가 대답하였다. \"그 또한 어렵지 않사옵니다. 황상께서 학사를 중히 여기시던 터요, 소자와 혼약을 맺은 것도 아실 것이니, 공주를 위하여 그를 저버려 홀로 깊은 규중에서 늙게 하시거나 다른 가문으로 가라 하실 리 없을 것입니다. 성상께서는 어지신 덕이 있으시니 어찌 신하의 인륜을 살피지 않으시겠사옵니까.\" 하고 마침내 대궐 아래에 나아가 상소를 올렸다.","sp":[[0,2,"P","김평"],[105,107,"P","최씨"],[114,116,"P","일월공주"],[189,191,"P","황제"],[232,234,"P","일월공주"]]},{"c":2,"sub":"","t":"그 상소에 이렇게 쓰여 있었다. \"이부상서 겸 제왕사 춘방한림 김희경은 삼가 뒤늦게 깨달은 바를 아뢰옵니다. 신이 처음에 장수정과 혼약을 맺었는데 세상일이 그릇되어 수정이 신의 종적을 찾지 못하여 외람되이 남복으로 갈아입고 사방을 떠돌다가 형세가 절박하여 벽해수에 빠졌습니다. 그 뒤 이영찬이 구한 줄을 모르고, 또 부모님께서 믿으시는 바가 소신뿐이라 후사가 늦어 가니 이는 종사의 큰일이라 부득이 최씨를 아내로 맞았사옵니다. 그러나 수정을 위하여 사당을 세우고 사철 제사를 끊지 않았사옵니다.","sp":[[35,38,"P","김희경"],[68,71,"P","장설빙"],[92,94,"P","장설빙"],[159,162,"P","이영찬"],[223,225,"P","최씨"],[243,245,"P","장설빙"]]},{"c":2,"sub":"","t":"\"지난해 수정과 같은 방에 급제하였을 때 다만 수정이라 하므로 그의 오라비인가 하고 변복하였으리라고는 생각하지 못하였는데, 천만뜻밖에 수정의 상소를 보니, 남녀를 바꾸어 성상을 속이고 다음으로 소신을 속인 것이 심하오니 이는 다 소신이 어리석은 탓이옵니다. 이제 근본을 안 뒤에 어찌 언약을 저버려 신의 없고 의롭지 못한 일을 하겠사옵니까마는, 두렵건대 폐하께서 성덕을 내리시어 최씨를 폐하지 않으신 것도 소신의 방자함이 지극한 일이온데 어찌 장씨를 마음대로 처리하겠사옵니까. 인륜에 관계되기에 진정과 소회를 아뢰오니 신하의 인륜을 살피소서.\"","sp":[[5,7,"P","장설빙"],[26,28,"P","장설빙"],[75,77,"P","장설빙"],[212,214,"P","최씨"]]},{"c":2,"sub":"","t":"황상이 다 보시고 웃으시며 비답을 내리셨다. \"장수정의 표를 보아 경이 굳게 언약한 것은 이미 알았으니, 짐이 어찌 공주 하나를 위하여 경의 의리를 잃게 하며, 또 수정을 청춘에 홀로 늙게 하리오. 수정이 처음에 여자가 변하여 남자가 된 것과 이제 남자가 변하여 여자가 된 것이 다 하늘의 운수라, 경이 일찍 만나지 못하고 최씨와의 인연을 이루게 한 것이니 어찌 사람의 힘이 미칠 바이겠느냐. 태후(대신)가 세 부인을 얻는 것은 떳떳한 일이니 어찌 꺼릴 것이 있겠느냐. 전날 태사가 가린 길일이 가까우니 그날 함께 예를 이루어 백년을 편안히 누리라.\" 상서가 분부를 받들어 사은하고 집에 돌아와 부모께 아뢰니, 평장과 부인이 기뻐하였으나 너무 번잡해지는 것을 근심하였다. [?]","sp":[[0,2,"P","황제"],[26,29,"P","장설빙"],[65,67,"P","일월공주"],[92,94,"P","장설빙"],[111,113,"P","장설빙"],[181,183,"P","최씨"],[342,344,"P","김평"]]},{"c":2,"sub":"","t":"상서는 속으로 크게 기뻐하여 친히 나아가 장 학사를 보고자 하였으나, 학사가 이미 조정을 버리고 깊은 규중을 지키고 있으니 비록 빛나는 언약이 있더라도 혼례 전에 얼굴을 마주하는 것은 반드시 구차하게 여길 것이었다. 보고 싶은 마음을 겨우 진정하고 붓과 벼루를 내어 편지 한 통을 써 보내며 황명을 전하였다.","sp":[[23,27,"P","장설빙"]]},{"c":2,"sub":"","t":"이때 학사는 여자의 도리를 행하며 옛일을 추모하여 마음을 진정하지 못하고 있었는데, 문득 시비가 편지 한 통을 드리므로 받아 보니 김 상서의 편지였다. 마음속으로 부끄러워 한참 생각하다가 뜯어 보니 그 편지에 이렇게 쓰여 있었다. \"한림 김희경은 장 부인께 글을 부치노라. 천만뜻밖에 군후의 표를 보고 한편 기쁘고 한편 슬퍼 혼백이 날아가니 어찌 다 글로 적으리오. 지난날 이 사람이 군후와 함께 형초 객관에 머물 때 서로 언약을 굳게 정하였으니, 서진과 금가락지가 각각 임자를 떠나 서로의 신물이 분명하도다. 이 사람이 타고난 성품이 시원스럽지 못하고, 또 군후가 버린 신의를 홀로 지켜 천하를 두루 다니며 종적을 찾다가 벽해수에 다다랐는데, 군후의 필적이 이 사람의 바람을 끊어 버렸도다. 그때 곧 죽어 군후의 뒤를 따르고자 하였으나 부모님이 계신 까닭에 차마 결행하지 못하고 길게 탄식할 뿐이었는데, 오늘 보니 군후의 신의를 모르고 목숨을 버렸더라면 짝 없는 혼백이 속절없이 벽해의 외로운 혼이 되었겠구나. 옛일을 돌이켜 생각하니 한탄스럽도다.","sp":[[73,77,"P","김희경"],[133,136,"P","김희경"],[138,142,"P","장설빙"]]},{"c":2,"sub":"","t":"군후가 처음에 남녀를 바꾼 것은 형세가 부득이하였거니와, 나중에 이 사람을 버린 것은 군후의 여자다운 행실이 아니라 하겠으나, 곰곰이 생각하니 이 사람이 몸 둘 바를 모르겠도다. 이제 군후의 정성스러운 마음을 무엇이라 하리오. 군후는 붓 아래 문장과 칼 아래 영웅으로 온 세상을 울리다가 하루아침에 천지가 변하여 대장부가 아녀자가 되었으니 마음속으로 슬퍼하겠거니와, 하늘이 어찌 늘 무심하시겠는가. 사람의 뜻으로 어찌할 수 없는 것이라. 처음에 서로 만나지 못한 것은 군후의 다하지 않은 액운이요, 또 남녀를 바꾸어 과거에 오른 것은 하늘이 군후의 정성에 감동하시어 충효를 모두 온전히 하고 빛나는 이름을 원근에 떨치게 하신 것이요, 이제 근본이 드러나 여자의 모습을 회복하는 것은 이 사람과의 인연이로다. 하늘의 도리가 저절로 이러함이 있도다.","sp":[]},{"c":2,"sub":"","t":"그러나 속으로 생각하니, 군후가 세상을 종횡하며 한신과 팽월의 웅재와 소하와 조참의 영웅다움을 겸하여 천하 사람을 지휘하였고 이 사람도 그 수하가 되었었도다. 이제 비록 칼을 버리고 벼슬을 내놓았으나 영웅의 뜻과 여자의 마음은 변치 않았을 것이니, 어찌 조그마한 맹세를 따라 몸을 굽혀 이 사람의 수하가 되어 여자의 일을 달게 여기겠는가. 이리 기별하는 것이 몹시 외람되나, 위로는 황명이 계시고 다음으로 부모님의 분부를 받들어 미루지 못하여 이 뜻을 전하노라. 깊이 생각하고 뒷날을 헤아려 위엄을 감추고 전날의 언약을 찾아 신의를 완전히 한다면 충효와 절행을 겸하여 후세에 아름다운 이름을 전할 것이니, 부디 고집하여 사양하지 마시오. 태사가 가린 길일이 이 사람의 영화의 날이라, 친히 나아가 대면하여 말할 일이로되 이미 예법을 정하였으니 길일 전에 대면하는 것은 아마 불편할 듯하여 억지로 참고 글월을 부치노라. 바라건대 세 번 생각하여 후회를 남기지 말고 한 번 답장을 아끼지 마시오.\"","sp":[]},{"c":2,"sub":"","t":"학사가 다 보고 나서 옥 같은 손으로 책상을 치며 살짝 웃었다. \"이런 조롱이 있을 줄은 알았으나 내 어찌 이토록 신의가 없겠는가.\" 하고 답장을 써서 보냈다. 학사는 길일이 공주와 같은 날이라 속으로 기뻐하지 않았으나, 설낭과 영춘은 기쁨이 끝이 없으니 그 주인을 위하는 정성은 가히 알 만하였다.","sp":[[98,100,"P","일월공주"],[124,126,"P","설낭"],[128,130,"P","영춘"]]},{"c":2,"sub":"","t":"이때 상서는 장 학사에게 글월을 보내고 답장을 기다리고 있었는데, 문득 시비가 편지 한 통을 드리므로 받아 읽어 보니 그 편지에 이렇게 쓰여 있었다. \"벼슬을 내놓은 청주인 태학사 장씨 설빙은 부끄러움을 무릅쓰고 답장을 부치나이다. 오호라, 하늘이 사람을 내실 때 반드시 길흉을 정하셨으나, 첩은 일찍이 운명이 기박하고 형세가 궁하여 천지를 속이고 해와 달을 가렸더니, 이제 와서 영화가 변하여 재앙이 되었으니 부끄러워 죽고 싶어도 몸 둘 곳이 없습니다. 어찌 한심하지 않으리오. 옛일을 돌이켜 생각하니 새삼 원망스럽습니다. 이제 허물을 스스로 꾸짖고 규방에 잠겨 세상을 모르고자 하였는데, 군자의 친필 편지를 보니 부끄럽고 송구함이 또한 끝이 없습니다. 군자는 첩과 함께 한때 높은 벼슬에 올라 일찍이 임금의 정사를 돕고 변방에 나가 몇 해를 함께 고생하였으니, 간담이 서로 비치어 지기를 허락하였습니다. 군자인들 어찌 신의를 저버리며 첩인들 신의를 잊겠습니까. 관우와 장비는 삼국 시대의 영웅이라도 생사를 함께하였으니 도원의 맹세가 굳은 것이요, 백이와 숙제는 주나라 때의 열사로서 수양산에서 굶어 죽었으니 이는 천고의 으뜸입니다. 어찌 열사와 영웅을 신의 없고 의리 없다 하겠습니까.","sp":[[7,11,"P","장설빙"],[104,106,"P","장설빙"]]},{"c":2,"sub":"","t":"첩이 처음에 몸을 나라에 바친 것은 아버님의 원한을 씻고자 함이요, 칼을 잡고 싸움터에 나아간 것은 임금을 위하여 반적을 소멸하기 위함이었습니다. 이제 성덕이 높아져 티끌이 고요하고 천하가 태평하니, 첩이 스스로 허물을 뉘우쳐 붓을 던지고 아침 햇살을 대하여 눈썹을 그리는 것은 군자를 위하여 신의를 돌아보는 것입니다. 첩의 일생이 군자에게 매였으니 어찌 조롱하겠습니까. 첩은 본래 죄악이 지중하여 일찍 부모를 여의고 초야에서 자라 부녀의 행실이 전혀 없고 다만 익히 아는 것은 진법과 검술뿐입니다. 혹 난세에는 쓸 만하겠으나 여자의 도리에는 맞지 않으니, 군자께서 첩을 얻어 무엇에 쓰시겠습니까. 군자께서는 이미 조강지처가 있고 또 머지않아 공주가 들어오실 것이니, 마땅히 부모님의 은덕을 봉양하여 여자의 도리를 세우는 것이 좋을 것입니다. 바라건대 군자께서는 깊이 생각하시어 쓸모없는 첩을 마음에 두지 마소서.\"","sp":[[360,362,"P","일월공주"]]},{"c":2,"sub":"","t":"상서가 다 보고 크게 웃고, 그 글을 가지고 안채에 들어가 부모께 드리니, 평장과 부인이 보고 웃으며 기뻐하였으나 너무 활달한 것을 근심하였다.","sp":[[42,44,"P","김평"]]},{"c":2,"sub":"","t":"이럭저럭 길일이 다가오니 상서가 예복을 갖추고 조용히 때를 기다리는데, 태감이 들어와 황명을 전하였다. \"하늘이 인륜을 정함에 반드시 차례가 있으니, 위엄을 자랑하고 형세를 믿어 선후를 바꾸면 이는 가르침을 버리는 것이다. 수정이 비록 신하이나 그 언약을 먼저 이루었고, 공주는 비록 짐의 딸이나 언약한 것이 나중이라. 먼저 맺은 약속을 먼저 하고 뒤의 약속을 뒤에 정하는 것이 떳떳한 예이니, 먼저 수정과 예를 이루고 다음에 공주를 맞이하는 것이 무방하니라.\" 좌우가 모두 놀라며 성덕을 축수하였고, 평장과 상서는 황공함을 이기지 못하여 감당할 수 없다고 아뢰었으나 황상이 듣지 않으셨다.","sp":[[125,127,"P","장설빙"],[152,154,"P","일월공주"],[224,226,"P","장설빙"],[239,241,"P","일월공주"],[281,283,"P","김평"],[318,320,"P","황제"]]},{"c":2,"sub":"","t":"날이 늦어지자 상서가 마지못하여 황명을 받들어 길을 나섰다. 옥 같은 얼굴과 영웅다운 풍채에 혼례복을 갖추고 금 안장 백마로 학사의 집에 이르러 전안례를 마친 뒤 안채에 들어가 맞절을 하는데, 상서가 눈을 들어 보니 장 소저가 머리에 화관을 숙여 쓰고 몸에 붉은 치마를 입었다. 푸른 눈썹과 맑은 광채는 햇빛을 희롱하고, 가는 버들 같은 허리와 가벼운 기상은 단정하고 연약하여 옷을 이기지 못할 듯하니, 어찌 전날 천병만마를 거느리고 창검을 잡아 적장을 베며 화살과 돌 가운데를 휘젓던 호걸이라 하겠는가. 상서가 반가운 마음을 금치 못하여 금빛 부채로 옥 같은 얼굴을 가리고 천천히 웃으며 말하였다. \"평소 조정에서 소매를 잇대어 지내고 위국 싸움터에 나가 베개를 함께하여 은근한 정이 끝이 없었으나, 옛날에는 이같이 반가운 뜻이 없었는데, 오늘은 자리가 넓고 동서로 멀리 떨어졌어도 오늘같이 보는 것이 정의가 가장 깊구려. 형초 객점에서 보던 얼굴이 어렴풋하도다. 모르겠구려, 군후가 신선 세계를 얻어 이 희경의 눈을 어둡게 한 것이로다.\" 말을 마치자 번화한 마음을 머금어 붉은 입술을 다물 줄 모르니 좌우의 빈객들이 크게 웃었다. 학사도 눈썹을 숙이고 눈길을 낮추어 웃음을 띠니, 그 화려한 기상이 옛날 군중에 있을 때 없던 얼굴과 비하면 배나 빛났다. 모두 그 조화에 탄복하였다. [?]","sp":[[121,125,"P","장설빙"],[508,510,"P","김희경"]]},{"c":2,"sub":"","t":"맞절을 마친 뒤 상서는 곧 바깥채로 나와 혼례복을 고치고 위의를 갖추어 공주궁으로 향하니 모든 사람이 칭찬하지 않는 이가 없었다. 궁에 다다라 전안례를 마친 뒤 안채에 들어가 맞절을 하는데 무수한 시녀가 좌우에 늘어서 있었다. 눈길을 흘려 공주를 바라보니 금 가지에 옥 잎 같은 귀한 몸이라, 옥 같은 얼굴과 맑은 눈에 정기가 어려 해와 달의 광채가 빛나니 참으로 세 부인이 차등이 없었고, 윤택하고 시원한 거동이 장 학사와 조금 비슷하였다. 상서가 속으로 생각하였다. '내 나이 겨우 스물에 벼슬이 공후에 이르고 두 부인과 공주를 얻었으니 어찌 즐겁지 않으리오.' 날이 저물자 신방에 나아가 쉬려다가 문득 생각하였다. '황상께서 이미 장 학사와 먼저 혼인을 이루라 허락하셨으니 오늘 밤은 학사의 집에 가서 쉬리라.' 하고 곧 중당에 나아가 의관을 갖추고 홀로 말을 타고 나가니, 궁중의 늙은이와 젊은이가 그 까닭을 모르고 바삐 들어가 공주께 아뢰었다.","sp":[[40,42,"P","일월공주"],[134,136,"P","일월공주"],[232,236,"P","장설빙"],[294,296,"P","일월공주"],[348,350,"P","황제"],[356,360,"P","장설빙"],[468,470,"P","일월공주"]]},{"c":2,"sub":"","t":"공주는 듣기만 하였으나 유모 정씨가 발끈하여 말하였다. \"부마가 어찌 이렇게 무례하오. 장씨를 위하여 공주의 위엄을 업신여기니 마땅히 성상께 아뢰어 장씨를 폐하고 후환을 덜어야 옳겠습니다.\" 공주가 낯빛을 바꾸며 말하였다. \"유모는 어찌 이런 말을 하는가. 장씨는 옛 은정이 있고 나는 새사람이라. 하물며 차례가 분명하고 성상의 칙교가 있으니 그를 먼저 찾는 것이 어찌 아름답지 않으리오. 만일 부마가 이곳에 머문다면 이는 위엄을 두려워하여 신의를 잊는 것이니 어찌 나라의 사람이 할 일이겠는가. 나는 부마의 행실에 법도가 있음에 탄복하노라. 유모는 이상한 말을 내어 나에게 허물을 끼치지 말라.\" 유모가 무안하여 대답하였다. \"공주의 말씀이 과연 마땅하시나, 부마가 옛 정을 찾으려면 떳떳이 말하고 갈 것이거늘 깊은 밤에 몰래 드나드시니 이는 공주를 업신여기는 것이라 어찌 애달프지 않겠사옵니까.\" 공주가 크게 웃으며 말하였다. \"유모는 나이 오십이 넘었으나 세상일을 모르니 참으로 한심하도다. 대장부가 세상에 살면 사해에 집이 있고 팔방에 가모(家母)가 있다 하니, 어찌 드나드는 것을 여자에게 아뢰겠는가. 참으로 유모 말과 같다면 부마는 세상에 하찮은 사람이 될 것이니 어찌 가소롭지 않으리오.\" 말을 마치고 옥 같은 이를 반쯤 드러내며 낭랑하게 웃으니, 유모가 할 말이 없어 잠자코 물러났다.","sp":[[0,2,"P","일월공주"],[13,15,"P","설낭"],[16,18,"P","정씨"],[32,34,"P","김희경"],[57,59,"P","일월공주"],[107,109,"P","일월공주"],[126,128,"P","설낭"],[221,223,"P","김희경"],[281,283,"P","김희경"],[304,306,"P","설낭"],[335,337,"P","설낭"],[352,354,"P","일월공주"],[370,372,"P","김희경"],[417,419,"P","일월공주"],[448,450,"P","일월공주"],[466,468,"P","설낭"],[570,572,"P","설낭"],[580,582,"P","김희경"],[650,652,"P","설낭"]]},{"c":2,"sub":"","t":"이때 학사는 상서를 공주궁으로 보내고 설낭, 영춘과 함께 촛불을 대하여 옛일을 이야기하며 서로 마음을 위로하고 있었다. 문득 시비가 들어와 상서가 오신다고 아뢰니, 학사가 크게 놀라 피하려 하였으나 상서가 벌써 중당에 오르므로 어찌할 수 없어 일어나 맞아 자리를 정하였다. 상서가 그가 허둥대는 것을 보고 의아하여 자리에 앉은 뒤 웃으며 말하였다. \"군후는 어찌 이 사람을 남처럼 대하시오? 하람과 연주로, 벽해의 먼 길을 돌아 희경을 찾으려 할 때는 무슨 뜻이었으며, 이제 성은을 입어 서로 만나니 백년도 오히려 부족하거늘 문득 나의 자취를 보고 황망히 피하려 함은 무슨 뜻이오?\" 학사가 옷깃을 여미고 대답하였다. \"첩이 굳이 군자를 남처럼 대하여 피하는 것이 아닙니다. 오늘은 황도(皇都)의 길일이라 바로 부마가 공주와 백년가약을 이루는 날입니다. 첩이 비록 성은을 입어 태사가 가린 날에 군자의 혼례를 맞은 것도 황공한데, 어찌 공주의 가약을 거스르겠습니까. 이는 임금과 아버지를 위하지 않고 공주를 업신여기는 것이니 어찌 군자를 남처럼 대하는 것이겠습니까. 청컨대 궁중으로 가시어 길일을 헛되이 하지 마소서.\" 말을 마치자 묵묵히 단정하게 앉으니, 그 씩씩하고 정대함이 북풍한설이요 차가운 달이 가을 강에 비친 것 같았다. [?]","sp":[[11,13,"P","일월공주"],[21,23,"P","설낭"],[25,27,"P","영춘"],[240,242,"P","김희경"],[398,400,"P","김희경"],[402,404,"P","일월공주"],[468,470,"P","일월공주"],[504,506,"P","일월공주"]]},{"c":2,"sub":"","t":"상서가 말하였다. \"이 사람이 오늘 여기 온 것은 사사로운 행동이 아니라 황명을 따른 것이니 군후는 조금도 염려하지 마시오.\" 말을 마치고 띠를 풀고 이부자리로 나아가 비단 휘장을 드리우고 촛불을 물리니, 학사가 불안하였으나 어찌할 수 없어 이부자리에 나아가 원앙의 즐거움을 이루었다. 학사는 여자의 몸이 구차해진 것을 속으로 한탄하였으나, 상서가 그 외로움을 위로하여 정답게 아끼는 정이 비할 데 없었다.","sp":[]},{"c":2,"sub":"","t":"이튿날 집에 돌아가 부모께 뵈니 평장과 부인이 장씨와 공주의 어짊을 아직 모르나 못내 기뻐하였다. 상서가 최씨의 침소에 가니 최씨가 황망히 일어나 맞았다. 자리를 정한 뒤 최씨가 기꺼이 물었다. \"장 형의 굳은 절개는 들었거니와, 공주는 범인이 아닌 까닭에 속으로 염려하옵니다.\" 말씀이 정직하고 거동이 온화하고 공손하여 조금도 겉치레의 말이 아니요 진정에서 나온 것이었다. 상서가 속으로 그 어진 마음에 탄복하였으나 내색하지 않고 대답하였다. \"부인은 어찌 이렇게 나를 조롱하시오? 예로부터 첩이나 다른 아내를 반기는 이가 없거늘, 이제 억지로 마음을 꾸며 내 마음을 시험하려 하시니 참말이 아닌가 하오.\" 최씨가 발끈 낯빛을 바꾸며 말하였다. \"군자께서는 어찌 이런 말씀을 하십니까. 첩이 감히 조금이라도 꺼리며 군자를 어찌 조롱하겠습니까. 하룻밤 부부라도 그 마음을 안다 하거늘 하물며 두 해가 지나도록 첩의 뜻을 모르시니 속으로 한심하옵니다.\" 상서가 사례하며 말하였다. \"부인의 바른 마음을 어찌 모르리오마는 봄 정취에 겨워 잠깐 농담을 한 것이니 부디 마음에 두지 마시오.\" 최씨는 아무 대답도 하지 않았다. [?]","sp":[[18,20,"P","김평"],[30,32,"P","일월공주"],[59,61,"P","최씨"],[70,72,"P","최씨"],[96,98,"P","최씨"],[129,131,"P","일월공주"],[341,343,"P","최씨"],[552,554,"P","최씨"]]},{"c":2,"sub":"","t":"상서가 이어 공주궁에 이르니 공주가 마침 촛불을 대하여 옛글을 보고 있다가 부마가 들어오는 것을 보고 일어나 맞았다. 동서로 나누어 앉은 뒤 눈을 들어 공주를 보니 미색이 맑고 기색이 태연하여 까닭 없이 다른 데 갔던 것을 꺼리는 빛이 없었다. 상서가 속으로 감탄해 마지않으며 목소리를 낮추어 말하였다. \"이 사람이 장씨와 미천할 때 굳게 혼약을 맺었는데, 그사이 사고가 많아 만나지 못하고 같은 방에 급제하여 변방까지 다녀왔으나, 이 사람이 어리석어 변복한 줄을 모르고 다만 처남으로만 알고 서로 지기를 맺고 지냈습니다. 이제 그 종적을 안 뒤로는 서로 버리지 못할 터이나 성은도 저버리지 못하던 차에, 천은이 지중하시고 공주의 어진 마음을 힘입어 이 사람이 신의를 지키게 되었으니 공주의 깊은 마음에 탄복합니다. 그러나 황상께서 선후를 정하여 예가 아닌 일을 행하지 말라 하시니 의혹할 뿐 아니라, 황명을 따라 공주께서 빈 방에 외로우실 것을 생각하지 않고 옛사람을 먼저 찾았으니, 이 사람이 무례함을 스스로 부끄러워하옵니다.\" [?]","sp":[[7,9,"P","일월공주"],[16,18,"P","일월공주"],[42,44,"P","김희경"],[85,87,"P","일월공주"],[349,351,"P","일월공주"],[383,385,"P","일월공주"],[405,407,"P","황제"],[456,458,"P","일월공주"]]},{"c":2,"sub":"","t":"공주가 옷깃을 여미고 대답하였다. \"군자께서는 어찌 이런 말씀을 하십니까. 부마 댁에는 장 학사뿐 아니라 또 최씨가 계시니 백 년 동안 첩이 빈 방을 지키는 일이 없게 하시면 되는 것이요, 선후가 분명한 것은 떳떳한 큰 의리인데, 어찌 여자의 마음을 엿보아 하찮은 일에 구구히 마음을 허비하십니까. 첩이 믿던 바가 아니니 속으로 한심하옵니다. 군자께서 이렇게 모르시니 반드시 첩의 마음을 조롱하시는 것입니다. 그렇지 않다면 장부가 신의를 지키는 떳떳하고 정대한 일을 어찌 말씀하시겠습니까. 성인의 가르침에 군자는 무슨 일이 있어도 마음을 조심하여 그릇된 일을 생각하지 말라 하였으니, 군자께서 어찌 마음을 꾸며 여자의 뜻을 시험하십니까. 참으로 공맹을 저버리는 것이라 첩이 속으로 군자를 위하여 부끄러워하옵니다.\" 말씨가 부드러워 다시 이야기를 잇기 어려웠다. 부마는 도리어 무안해하면서도 속으로 크게 칭찬하였다. 이렇게 밤이 깊자 촛불을 물리고 이부자리에 나아가 부부의 의를 이루니 그 정다움이 비할 데 없었다.","sp":[[0,2,"P","일월공주"],[42,44,"P","김희경"],[49,53,"P","장설빙"],[61,63,"P","최씨"],[426,428,"P","김희경"]]},{"c":2,"sub":"","t":"이럭저럭 세월이 빨라 이듬해 봄이 되었다. 평장의 생신이 하루 앞으로 다가와 중당에 자리를 깔고 장 학사와 공주의 신부 인사 예식을 치르려 하니, 석 부인이 최씨와 친척을 거느리고 신부를 기다렸다. 이때 장 학사는 차림을 꾸미지 않고 비취 삼(衫)에 화관을 쓰고 패옥 소리를 쟁쟁히 울리며 설낭, 영춘과 시비 몇 사람만 데리고 상서의 집에 이르렀다. 이어 공주의 행차가 이르니 함께 안채에 들어가 시부모께 폐백 예를 마쳤다. 석 부인이 최씨를 가리키며 말하였다. \"이는 희경의 아내이니 두 어진 며느리는 서로 예를 잃지 마라.\" 학사와 공주가 명을 받들어 나아가 서로 예를 마치고 자리를 정하려 하였다. [?]","sp":[[24,26,"P","김평"],[54,58,"P","장설빙"],[60,62,"P","일월공주"],[82,86,"P","석 부인"],[88,90,"P","최씨"],[114,118,"P","장설빙"],[162,164,"P","설낭"],[166,168,"P","영춘"],[199,201,"P","일월공주"],[238,242,"P","석 부인"],[244,246,"P","최씨"],[263,265,"P","김희경"],[300,302,"P","일월공주"]]},{"c":2,"sub":"","t":"최씨가 피하며 말하였다. \"학사는 미천할 때 혼약을 맺으신 분이요, 공주는 지존의 혈맥이시고 황상께서 사랑하시는 따님이십니다. 첩이 비록 먼저 이 가문에 의탁하였으나 대의와 신의를 생각하지 않고 어찌 감히 윗자리를 차지하겠사옵니까.\" 하며 마침내 끝자리에 앉으니, 학사와 공주도 옷깃을 여미고 말하였다. \"저희는 끝자리에 앉는 것도 분에 넘치는데 어찌 윗자리를 바라겠습니까.\" 최씨가 굳이 사양하였다. \"첩이 김씨 문하를 떠나지 않게 된 것은 공주의 성덕이니, 마땅히 공주의 수건을 받들어 은혜를 갚고자 합니다. 첩이 같은 반열이 되는 것도 몹시 외람된데 하물며 어찌 윗자리를 차지하겠사옵니까. 바라건대 공주와 학사께서는 첩의 마음을 살피소서.\" 서로 자리를 정하지 못하여 끝내 앉지 못하니, 날이 다하도록 차례를 정하지 못하여 자리에 있던 모든 이가 불안해하였다.","sp":[[0,2,"P","최씨"],[38,40,"P","일월공주"],[52,54,"P","황제"],[152,154,"P","일월공주"],[211,213,"P","최씨"],[248,250,"P","일월공주"],[262,264,"P","일월공주"],[338,340,"P","일월공주"]]},{"c":2,"sub":"","t":"그때 문득 시비가 아뢰었다. \"황후마마께서 사자를 보내셨나이다.\" 자리에 있던 이들이 모두 놀랐고 평장과 부마는 자리를 피하여 바깥채로 나갔다. 궁녀가 들어와 대청 위에 오르며 눈을 들어 보니, 공주와 두 부인이 끝자리에 서 있고 좌우의 여러 사람도 자리를 떠나 서 있으므로 매우 이상히 여겼다. 석 부인이 물었다. \"궁인은 무슨 까닭으로 누추한 곳에 오셨소?\" 궁녀가 대답하였다. \"황후마마께서 첩을 보내시어 편지를 올리게 하시고, 황상께서도 귀댁에 분부를 내리시어 최, 장 두 부인께 직첩을 드리라 하시기에 명을 받들어 왔사옵니다.\" 말을 마치고 직첩을 드렸다.","sp":[[55,57,"P","김평"],[59,61,"P","김희경"],[109,111,"P","일월공주"],[166,170,"P","석 부인"],[243,245,"P","황제"]]},{"c":2,"sub":"","t":"황망히 일어나 받들어 향촉을 벌여 놓고 북쪽을 향해 사은한 뒤 뜯어 보니 분부에 이렇게 쓰여 있었다. \"짐이 바빠서 미처 깨닫지 못하였는데, 들으니 오늘 장씨와 공주가 함께 시부모께 인사하고 같은 자리에 앉는다 하니, 최씨의 어짊은 알지 못하거니와 장씨는 소년에 조정에 들어와 짐의 기둥 같은 신하가 되었으므로 그 사람됨을 잘 알고, 공주는 짐의 골육이라 비록 배운 바가 적으나 예의에서 벗어나는 행실은 없을 것이다. 생각건대 오늘 세 사람이 한 방에 모이면 결코 자리를 정하지 못할 것이라, 그러므로 차례를 정하여 직첩을 내리노니 삼가 명을 어기지 마라. 장씨는 비록 나중에 만났으나 그 언약을 먼저 정하였으니 장씨를 정실로 봉하고, 최씨를 정렬부인으로 봉하며, 공주를 끝자리로 삼노니, 모두 정성스러운 마음으로 의를 맺어 백년을 편안히 누리라.\" 평장과 부인이 황감하여 이에 공주와 장, 최 두 사람을 불러 말하였다. \"황상께서 이제 직첩을 내리시어 차례를 정하셨으니 자리를 정하소서.\" 하고 분부를 세 사람에게 전하니 비로소 자리를 정하였다. 공주는 속으로 기뻐하였으나 장, 최 두 사람은 불안해하였다. [?]","sp":[[90,92,"P","일월공주"],[122,124,"P","최씨"],[187,189,"P","일월공주"],[356,358,"P","최씨"],[360,364,"P","최씨"],[372,374,"P","일월공주"],[420,422,"P","김평"],[436,438,"P","일월공주"],[461,463,"P","황제"],[531,533,"P","일월공주"]]},{"c":2,"sub":"","t":"이에 자리가 조용해지자 최씨가 비로소 눈을 들어 공주와 장씨를 살펴보니, 꽃 같은 허리와 달 같은 자태, 봉황 같은 눈과 구름 같은 머리가 시원하고 씩씩하여 사람의 마음을 놀라게 하였고, 봉황의 풍채에 학의 골격이며 난초 같은 마음에 혜초 같은 바탕이 단아하고 깨끗하여 조금도 티끌이 없었다. 그러나 찬란한 용모와 광채는 장씨가 오히려 더 빼어났다. 최씨가 속으로 생각하였다. '세상에 나의 적수가 없을까 하였더니 이 두 사람을 보니 참으로 만고의 절색이라 내 어찌 부끄럽지 않으리오. 그런데 학사가 저런 미색으로 두건과 도포를 입고 천하를 누볐으나 조정의 모든 관원이 한 사람도 의심하지 않았으니 어찌 신기하지 않으리오.' 공주도 좌우를 살펴보니 최, 장 두 사람의 골격이 은은하고 빼어나 막상막하였으나, 단정하고 윤택함은 학사가 더 빼어나니 속으로 감탄해 마지않았다. 학사는 뜻밖에 윗자리를 받아 자연히 불안하였으나 사양하지 못할 일이라 순순히 자리를 정하고, 눈을 들어 두 부인을 보니 옥 같은 얼굴과 빼어난 모습이 여러 사람 가운데 뛰어나 강산의 정기를 미간에 감추었으니 참으로 만고의 절색이었다. 속으로 생각하였다. '내 비록 여자이나 거의 온 세상을 보았으나 이 같은 미색은 보지 못하였으니 참으로 처음 보는 것이로다.' 하며 감탄해 마지않았다. 좌우의 여러 사람이 석 부인께 세 사람이 아름다운 것을 치하하였다. [?]","sp":[[13,15,"P","최씨"],[27,29,"P","일월공주"],[196,198,"P","최씨"],[350,352,"P","일월공주"],[659,663,"P","석 부인"]]},{"c":2,"sub":"","t":"평장도 빈객을 모아 바깥채에서 즐기는데, 술이 반쯤 취하자 최 승상이 부마의 손을 잡고 평장을 향해 웃으며 말하였다. \"하람에 초운이라는 명창이 있어 얼굴과 재주가 당대에 으뜸이라던데 명공은 아시오?\" 평장은 그 뜻을 모르므로 무심히 대답하였다. \"하람은 본래 땅이 좁고 인물이 적어 재주를 가진 여자는 없을 뿐 아니라, 초운이라는 기생은 일찍이 듣지 못하였소.\" 승상이 크게 웃으며 말하였다. \"명공이 하람에 계시면서 이런 명창을 모르시니 천 리 밖에 있는 나만도 못하구려. 초운의 자는 초연이니 본래 하람의 명창이라. 내가 지난해 석 태위의 천거로 그 재주를 보고 지금까지 잊지 못하오. 그래서 물었는데 명공은 모른다 하시니 도리어 무안하구려.\" 평장이 말하였다. \"명공이 틀림없이 석 태위에게 속으셨소. 하람에는 본래 그런 기생이 없으니 어찌 숨길 일이 있겠소.\" 하고 석 태위를 돌아보며 말하였다. \"형은 이런 기생을 하람 사람이라 거짓으로 꾸며 승상을 속이셨소?\"","sp":[[0,2,"P","김평"],[33,37,"P","최후"],[39,41,"P","김희경"],[49,51,"P","김평"],[113,115,"P","김평"],[299,303,"P","석 태위"],[364,366,"P","김평"],[384,388,"P","석 태위"],[434,438,"P","석 태위"]]},{"c":2,"sub":"","t":"태위가 웃으며 대답하였다. \"지난해 한 명창이 청주에서 왔기에 내가 그 사람됨을 아껴 집에 머물게 하였는데, 마침 승상의 생신을 맞아 달리 바칠 것이 없어 초운을 불러 한번 웃음을 드린 것이오.\" 좌우의 여러 사람이 일시에 말하였다. \"까맣게 잊었더니 태위의 말씀에 생각이 납니다. 과연 그때 우리도 함께 잔치에 참여하였는데 태위가 천거한 것을 알았지요.\" 그리고 이어 말하였다. \"그 사람은 하람 기생이었습니다.\" 평장이 의아하여 물었다. \"그렇다면 그 기생은 어디 있소?\" 미처 대답하지 못하는데 태위가 웃으며 말하였다. \"승상이 전날 초운의 자색을 그리워하여 상사병이 났으니 어찌 초운 하나를 아끼겠소. 쾌히 허락하여 승상의 소원을 들어 드렸소. 그 뒤에 들으니 승상이 초운의 자색을 남이 엿볼까 두려워 곧 깊은 규방에 감추고 자취를 문밖에 내지 않는다 하더니, 오늘 평장의 잔치를 맞아 틀림없이 그 자색을 자랑하려는 것이니, 평장과 여러 손님은 승상께 청하여 보시오.\" [?]","sp":[[0,2,"P","석 태위"],[141,143,"P","석 태위"],[182,184,"P","석 태위"],[233,235,"P","김평"],[280,282,"P","석 태위"],[433,435,"P","김평"],[466,468,"P","김평"]]},{"c":2,"sub":"","t":"평장이 곧이듣고 승상께 청하였다. \"나는 하람에서 자랐으나 초운이라는 기생은 보지 못하였으니, 승상은 한번 불러 구경을 시켜 주시오.\" 여러 손님도 청하였다. \"우리도 그때 초운이라는 말만 듣고 자세히 보지 못하고 떠나 지금까지 잊지 못하던 차에, 이제 승상께서 집에 두셨다 하오니 한번 다시 보기를 청하옵니다.\" 승상이 달리 막을 말이 없어 크게 웃으며 말하였다. \"내가 잠시 평장을 놀리려다가 도리어 태위의 조롱을 받고, 또 태위는 나로 하여금 평장과 여러 빈객의 꾸지람을 받게 하니 세상에 어찌 이런 기이한 이야기가 있으리오.\" 하고 마침내 부마가 기생으로 변복하여 자기 딸의 마음을 탐지하던 사연을 갖추어 이야기하고, 손으로 태위를 가리키며 말하였다. \"이는 다 석공의 짓이라.\" 태위와 부마가 크게 웃고 평장과 모든 빈객이 손뼉을 치며 크게 웃었다. [?]","sp":[[0,2,"P","김평"],[212,214,"P","김평"],[226,228,"P","석 태위"],[240,242,"P","석 태위"],[251,253,"P","김평"],[306,308,"P","김희경"],[354,356,"P","석 태위"],[375,377,"P","석 태위"],[385,387,"P","석 태위"],[389,391,"P","김희경"],[399,401,"P","김평"]]},{"c":2,"sub":"","t":"이에 술상을 내어 종일 즐기다가 해가 기울어 빈객이 다 흩어진 뒤, 평장이 태위와 부마를 데리고 안채로 들어왔다. 이때 석 부인이 세 며느리와 집안 부녀들을 데리고 즐기다가 평장과 태위와 부마가 들어오는 것을 보고 서로 맞아 자리를 정하였다. 태위가 공주의 자색을 보고 아름다움을 칭찬하고, 또 장 학사를 돌아보며 기쁘게 웃었다. \"학사가 전날 황상의 기둥 같은 신하가 되어 연왕을 아침저녁으로 가르치고 위풍이 변방에 가득하여 온 백성이 우러러보더니, 이제 하늘과 땅이 바뀌어 묘당의 대신이 깊은 규중의 여자가 되어 희경의 수하가 되었으니 세상일을 참으로 헤아리지 못하겠구나.\" 학사가 부끄러워하며 말하였다. \"천지간에 용납되지 못할 비웃음을 얻어 여러 손님께 부끄럽기 그지없었는데, 오늘 숙부의 과찬을 들으니 더욱 몸 둘 곳이 없사옵니다.\" 태위가 웃으며 말하였다. \"군사를 부린 일과 환난 속에 몸을 감춘 일이 여자 가운데 호걸이니 어찌 부끄러울 것이 있겠느냐.\" 평장도 칭찬해 마지않으니 학사는 앉아서 고개를 숙이고 대답하지 않았다. 태위가 또 최씨를 향해, 상서가 전날 기생으로 변복한 일로 승상과 서로 다투던 이야기를 하니 자리에 있던 이들이 크게 웃으며 서로의 재주를 치하하였다. 최씨는 살짝 웃으며 대답하지 않았고 상서는 빙그레 웃을 뿐이었다. 이어 사흘 동안 큰 잔치를 열고 마치니 원근의 백성이 칭찬하지 않는 이가 없었다. [?]","sp":[[38,40,"P","김평"],[42,44,"P","석 태위"],[46,48,"P","김희경"],[67,71,"P","석 부인"],[97,99,"P","김평"],[101,103,"P","석 태위"],[105,107,"P","김희경"],[136,138,"P","석 태위"],[140,142,"P","일월공주"],[165,169,"P","장설빙"],[193,195,"P","황제"],[210,212,"P","연왕"],[289,291,"P","김희경"],[416,418,"P","석 태위"],[486,488,"P","김평"],[526,528,"P","석 태위"],[532,534,"P","최씨"],[611,613,"P","최씨"]]},{"c":2,"sub":"","t":"이에 공주궁을 평장의 집과 이어서 짓고 이름을 창수궁이라 하였다. 공주가 장씨, 최씨와 함께 한 궁에 지내는데, 학사는 명월당에, 최씨는 벽화정에, 공주는 양춘각에 거처하였다. 세 사람이 화목하여 날마다 시부모께 문안한 뒤에는 서당에 모여 풍월과 한담으로 세월을 보내니 날 가는 줄을 몰랐다.","sp":[[3,5,"P","일월공주"],[8,10,"P","김평"],[37,39,"P","일월공주"],[45,47,"P","최씨"],[73,75,"P","최씨"],[83,85,"P","일월공주"]]},{"c":2,"sub":"","t":"이럭저럭 삼 년이 지났다. 하루는 학사가 옛일을 생각하니 자연히 마음이 울적하여 밤 깊도록 잠을 이루지 못하였다. 영춘을 데리고 중헌에 나와 난간에 기대어 달빛을 구경하는데, 바로 삼경이라 온갖 소리가 고요한 가운데 밝은 달은 황성을 이끌어 옥경에 올리는 듯하고 맑은 바람은 향기를 몰아 난간으로 들어오니 처마 끝의 경치가 매우 아름다웠다. 시흥을 참지 못하여 절구 한 수를 지어 읊고는 영춘을 불러 벽화당에 가서 최 부인을 모셔 오라 하였다. 영춘이 명을 받들어 벽화당에 가니 최 부인이 마침 촛불을 밝히고 옛글을 보다가 영춘을 보고 물었다. \"무슨 일로 왔느냐?\" 영춘이 학사의 말을 전하니 최씨가 사양하지 않고 기꺼이 일어나 시비 춘빙만 데리고 갔다.","sp":[[64,66,"P","영춘"],[195,197,"P","소세필"],[217,219,"P","영춘"],[232,236,"P","최씨"],[249,251,"P","영춘"],[268,272,"P","최씨"],[293,295,"P","영춘"],[318,320,"P","영춘"],[333,335,"P","최씨"],[356,358,"P","춘빙"]]},{"c":2,"sub":"","t":"이때 부마는 공주와 함께 밤 깊도록 예의를 의논하다가 막 잠자리에 들려 하는데, 창밖에 촛불 빛이 비치며 사람의 발소리가 들렸다. 부마가 시비에게 물어보라 하니 \"최 부인이 시비와 함께 명월당으로 가시더이다.\" 하고 아뢰었다. 부마는 듣기만 하고 다시 묻지 않았는데 공주가 웃으며 말하였다. \"오늘 밤 달빛이 밝고 경치가 아름다우니, 짐작건대 상원 부인께서 시흥을 참지 못하여 작은 자리를 벌이고 최 부인을 청하신 것이로군요.\" 부마가 웃으며 말하였다. \"그렇다면 공주도 참여하고 싶으나 청함이 없어서 못 가시는 것이오?\" 공주가 크게 웃으며 말하였다. \"그래서 가기를 청하지 않는 것이옵니다.\" 부마가 말하였다. \"두 부인과 온 궁의 늙은이와 젊은이가 다 공주의 총명하고 슬기로움에 탄복하는데 오늘은 어찌 생각이 이러하여, 청하지 않은 것을 꺼려 가지 않으려 하시오? 오늘 밤 이 사람이 여기 머무는 줄은 궁중이 다 아는데 어찌 두 부인이 모르겠소. 그래서 공주를 청하지 않은 것이니, 지금 공주께서 가시면 두 부인이 반드시 반길 것이오. 어찌 청하지 않은 것을 꺼리겠소.\" 공주가 웃으며 말하였다. \"그러면 부마의 기척을 물을 터인데 무슨 말로 대답하겠습니까?\" 부마가 말하였다. \"그것은 어렵지 않소. 숙부께서 초저녁에 사람을 불러 데려갔다 하시오.\" 공주가 살짝 웃으며 대답하지 않았으나 부마가 두세 번 권하니, 공주가 비로소 시비 몇 사람을 데리고 천천히 나가며 말하였다. \"이리 가는 것은 부마의 권유요 첩이 스스로 가는 것이 아니오니 속으로 방자하다 여기지 마소서.\" 부마는 웃을 뿐 대답하지 않았다. 부마는 학사의 울적함을 짐작하고 그 외로움을 가엾게 여겨 이렇게 한 것이었다. [?]","sp":[[3,5,"P","김희경"],[7,9,"P","일월공주"],[73,75,"P","김희경"],[91,95,"P","최씨"],[127,129,"P","김희경"],[149,151,"P","일월공주"],[192,197,"P","장설빙"],[204,206,"P","소세필"],[222,226,"P","최씨"],[240,242,"P","김희경"],[260,262,"P","일월공주"],[293,295,"P","일월공주"],[334,336,"P","김희경"],[368,370,"P","일월공주"],[481,483,"P","일월공주"],[500,502,"P","일월공주"],[547,549,"P","일월공주"],[566,568,"P","김희경"],[597,599,"P","김희경"],[648,650,"P","일월공주"],[669,671,"P","김희경"],[683,685,"P","일월공주"],[728,730,"P","김희경"],[773,775,"P","김희경"],[792,794,"P","김희경"]]},{"c":2,"sub":"","t":"이때 최씨가 바로 명월당에 다다르니 학사가 홀로 난간에 기대어 풍월을 읊다가 최씨를 보고 몸을 일으켜 예를 마치고 자리를 정한 뒤 말하였다. \"이 몸이 일찍 풍상을 겪은 탓에 저절로 잠이 없어, 달빛이 밝고 경치가 고요하기에 멀리 바라보다가 도리어 외로움을 참지 못하여 외람됨을 잊고 감히 청하였는데, 꺼리지 않으시고 이렇게 와 주시니 감사함을 이기지 못하겠습니다.\" 최씨가 옷깃을 여미고 대답하였다. \"부인께서는 어찌 이렇게 겸손하십니까. 물불이라도 오히려 피하지 못할 터인데 하물며 부인을 모시고 아름다운 달빛을 즐기는 일을 어찌 사양하겠습니까.\" 말을 마치고 촛불을 내어 놓고 풍경을 두고 화답하였다. 최씨가 말하였다. \"오늘 같은 달빛을 공주께서 홀로 보지 못하시니 몹시 아쉽습니다.\" 학사가 대답하였다. \"제 마음도 그러하나 부마가 반드시 그곳에 계실 것이니 공주께서 무슨 말씀으로 그 몸을 빼어 나오시겠습니까. 그래서 모일 뜻이 없어 생각하지 못하였습니다.\" [?]","sp":[[3,5,"P","최씨"],[43,45,"P","최씨"],[144,146,"P","소세필"],[206,208,"P","최씨"],[340,342,"P","최씨"],[361,363,"P","일월공주"],[411,413,"P","김희경"],[430,432,"P","일월공주"]]},{"c":2,"sub":"","t":"그때 문득 한 쌍의 촛불이 난간에 오르므로 바라보니 바로 공주였다. 서로 반가움을 금치 못하여 황망히 일어나니 공주가 웃으며 말하였다. \"제가 비록 어리석으나 상원과 최 부인을 소홀히 대한 적이 없는데, 이제 경치를 대하여 한가로이 즐기시면서 저를 부르지 않으신 것은 무슨 까닭입니까?\" 학사가 웃으며 말하였다. \"마침 밝은 달이 비치고 일이 없기에 최 부인을 청하였는데, 공주의 고운 모습이 없는 것이 몹시 섭섭하여 몸소 모시러 가고자 하였으나 부마의 그림자가 반드시 향춘각에 계실 것이라 감히 드러내지 못하였습니다. 뜻밖에 공주께서 오시니 이는 반드시 저희가 그리워하는 정에 감동하여 서로 만나게 한 것이로군요. 어찌 즐겁지 않으리오. 그런데 저희가 여기 모인 것을 어찌 아셨으며, 부마는 무슨 꾀로 속이고 오셨습니까?\" 공주가 웃으며 말하였다. \"부마께서 계시다면 무슨 까닭으로 속이겠습니까. 초저녁에 숙부께서 무슨 의논할 일이 있다 하시며 불러 가셨기에, 제가 홀로 한가하여 밤 깊도록 앉아 있었는데 시비가 최 부인께서 이리로 가시더라 아뢰기에 틀림없이 모임이 있는 줄 짐작하고 왔습니다.\" 학사와 최씨가 크게 기뻐하며 말하였다. \"부마께서 아니 계시고 공주께서 한가하신 것이 참으로 저희의 다행입니다. 밤이 다하도록 즐기사이다.\"","sp":[[32,34,"P","일월공주"],[62,64,"P","일월공주"],[93,97,"P","최씨"],[196,200,"P","최씨"],[209,211,"P","일월공주"],[250,252,"P","김희경"],[295,297,"P","일월공주"],[384,386,"P","김희경"],[406,408,"P","일월공주"],[421,423,"P","김희경"],[512,516,"P","최씨"],[563,565,"P","최씨"],[582,584,"P","김희경"],[594,596,"P","일월공주"]]},{"c":2,"sub":"","t":"마침내 술과 안주를 내어 즐기는데 공주가 잔을 잡고 두 부인을 대하여 말하였다. \"우리 세 사람이 한마음으로 의를 맺어 한 사람을 섬기니 그 정분이 어찌 동기보다 못하겠습니까. 이렇게 기이한 이야기를 하오니 두 부인께서는 이상하다 마소서. 짐작건대 제 말과 맞는 것이, 최 부인은 부마의 거문고에 속으신 분이요, 장 부인은 오늘이 벽해수에 빠질 때 바위에 글을 써 표하던 날이 아닙니까. 세 사람의 혼백이 풍랑을 따라 황천으로 향하다가 하늘이 감동하시어 용녀를 보내 환혼주를 주어 살아났고, 이것은 다 이영찬이 장 부인의 풍도를 흠모하여 혼인을 구하기에 과거를 핑계로 부마를 찾았으나, 이미 최씨와 혼인하였으므로 어찌할 수 없어 남복으로 높은 벼슬에 올라 급제하여 벼슬이 공후에 이른 것이니, 이 또한 참정의 은혜요 최 부인의 현명하신 덕입니다.\" 두 부인이 다 듣고 슬픔을 금치 못하여 어찌 그리 분명히 아느냐고 물으니, 공주가 슬픔을 머금고 대답하였다. \"지난날 표를 올리셨을 때 조정의 모든 관원이 누가 모르겠습니까.\" [?]","sp":[[19,21,"P","일월공주"],[151,155,"P","최씨"],[157,159,"P","김희경"],[175,179,"P","장설빙"],[281,284,"P","이영찬"],[286,290,"P","장설빙"],[318,320,"P","김희경"],[331,333,"P","최씨"],[393,395,"P","이영찬"],[401,405,"P","최씨"],[461,463,"P","일월공주"]]},{"c":2,"sub":"","t":"학사는 늘 이 참정의 은혜를 생각하여 부마에게 권하여 이 소저를 천거하였다. 부마가 말하였다. \"한 집에 세 부인도 오히려 지나친데 또 어찌 이 소저를 맞겠소.\" 학사가 말하였다. \"이분은 바로 첩의 은인입니다. 첩이 미천할 때 주인과 종 세 사람을 구하였으니, 영찬이 아니었다면 다시 세상을 알지 못하고 황천의 외로운 혼이 되었을 것입니다. 어찌 오늘 세상을 다시 보겠습니까. 바라건대 부마께서는 첩의 얼굴을 보아 버리지 마옵소서. 첩이 또한 두건과 도포 차림으로 있을 때 외람된 뜻을 두어 이 소저와 정혼하였는데, 지금까지 이 소저는 신의를 믿고 청춘 홍안으로 깊은 규중을 지키고 있을 터이니 어찌 모른 체하겠습니까. 그때 참정의 권유와 사랑을 물리치지 못하여 소저와 서로 얼굴을 대하여 언약한 일이 있사옵니다. 첩이 남의 은혜를 배반하면 주인과 종 세 사람이 하늘의 재앙을 면치 못할 것이요, 세상에 남녀를 막론하고 은혜를 모르면 배은망덕이라는 말이 있고 그 재앙이 자손에게 내린다 하오니, 참정의 은혜를 만분의 일이나마 갚게 해 주시면 도리어 영화가 될까 하옵니다.\" 부마가 억지로 허락하고 부모님께 사연을 아뢰니 평장 부부가 기뻐하였다. 곧 혼인을 청하고 날을 받아 이씨 댁에 보냈다. [?]","sp":[[6,10,"P","이영찬"],[21,23,"P","김희경"],[30,34,"P","이 소저"],[43,45,"P","김희경"],[79,83,"P","이 소저"],[217,219,"P","김희경"],[276,280,"P","이 소저"],[295,299,"P","이 소저"],[351,353,"P","이영찬"],[502,504,"P","이영찬"],[546,548,"P","김희경"],[572,574,"P","김평"]]},{"c":2,"sub":"","t":"이때 [□] 참정 부인은 딸의 혼사가 늦어 가고 학사의 소식을 몰라 밤낮으로 염려하였는데, 뜻밖에 부마가 혼인을 청한다는 말을 듣고 또 택일한 글이 오니 한편 놀라며 뜯어 보았다. 장 학사의 편지였는데 이렇게 쓰여 있었다. \"학사 설빙은 머리를 조아려 두 번 절하고 참정 부인 합하께 올리나이다. 첩이 팔자가 기박하여 여자가 남자로 변하여 세상을 속이고 높은 벼슬에 올라 공후에 이르렀는데, 조물이 시기하고 하늘이 미워하시어 성상께서 부마로 삼으려 하시기에 어찌할 수 없어 벼슬을 내놓고 깊은 규중에 들었습니다. 그런데 지금의 부마 김희경과 언약이 있었기에 성상께서 혼인을 주관하시어 혼례는 올렸으나, 소저의 일생을 생각하니 가슴이 찢어지는 듯하였습니다. 또 생각하니 소저는 다른 가문을 섬기지 않을 것이라, 함께 살 뜻을 두어 부마에게 이러한 사연으로 혼인을 구하였더니, 부마는 큰 사람이요 군자라 어찌 아녀자의 애석함을 모르겠습니까. 곧 허락하기에 날을 받아 보내오니, 어찌 알지 못하는 일이라 마시고 혼례를 이루게 하옵소서.\" 참정 부인이 다 보고 크게 놀라 말하였다. \"여자가 어찌 이다지 활달한가. 일이 이러하니 이는 다 하늘의 명이라 어찌 사람의 힘으로 하겠는가.\" 곧 답장을 보내고 혼수를 차려 길일을 기다렸다.","sp":[[7,12,"P","이 참정 부인"],[55,57,"P","김희경"],[101,105,"P","장설빙"],[129,131,"P","장설빙"],[149,154,"P","이 참정 부인"],[243,245,"P","김희경"],[295,297,"P","김희경"],[298,301,"P","김희경"],[408,410,"P","김희경"],[433,435,"P","김희경"],[522,527,"P","이 참정 부인"]]},{"c":2,"sub":"","t":"한편, 평장이 부마를 불러 말하였다. \"좋은 일에는 탈이 많다 하니 너를 보면 복이 줄어들까 두렵구나.\" 부마가 자리를 피하며 대답하였다. \"소자가 어찌 조심하지 않겠사옵니까.\" 이럭저럭 길일이 되자 위의를 갖추어 여남 이씨 댁에 이르니, 채색 꽃과 비단 창, 구슬 발로 꾸미고 화려한 대청에 빈객이 가득하였다. 부마가 전안례를 마친 뒤 소저와 맞절을 하는데, 소저는 붉은 치마와 비취 적삼에 향기로운 바람이 촛불을 날리고, 먼 산 같은 눈썹은 고운 뺨을 이끌며, 붉은 입술과 흰 이는 두 뺨에 어리어 연꽃을 머금은 듯하였다. 가는 버들은 봄바람에 나부끼고 곱고 단정한 자태는 서왕모의 요지연에 복숭아를 바치는 듯하니, 부마가 한번 보고 마음이 황홀하여 속으로 기뻐하였다. 이럭저럭 해가 서산에 지자 손님들이 각각 집으로 돌아간 뒤 저녁을 먹고 밤이 이미 삼경이라 잠자리에 들었다. 이튿날 부마가 소저와 함께 참정 부인께 뵈니 부인이 기뻐하며 말하였다. \"부마께서 수고로움을 꺼리지 않으시고 누추한 집을 빛내시니 이는 장 부인의 덕이옵니다.\" 부마가 말하였다. \"부인께서 외로이 계시는데 이 사람을 데려가면 부인께서 더욱 적적하실 터이니, 꺼리지 않으시면 서울에 올라가 사람과 말을 보내 모셔 가겠습니다. 올라오시면 좋을까 하옵니다.\" 부인이 대답하였다. \"부마께서 버리지 않으시면 분부대로 하겠습니다.\" 이튿날 행장을 차려 소저와 함께 부인께 하직하고 떠나니 그간의 정회에 서운해하였다.","sp":[[4,6,"P","김평"],[8,10,"P","김희경"],[59,61,"P","김희경"],[175,177,"P","김희경"],[347,349,"P","김희경"],[442,444,"P","김희경"],[453,458,"P","이 참정 부인"],[479,481,"P","김희경"],[514,518,"P","장설빙"],[528,530,"P","김희경"],[648,650,"P","김희경"]]},{"c":2,"sub":"","t":"한편, 부마와 소저가 서울에 이르러 부모께 뵈니 평장과 부인이 못내 기뻐하였고, 다음으로 세 부인께 예를 행하니 장 부인의 기쁨은 헤아릴 수 없었고 온 집안에 칭찬하는 소리가 가득하였다. 부마가 참정 부인이 외로이 지내는 것을 부모께 아뢰니, 평장이 듣고 곧 사람과 말을 보내라고 재촉하였다. 부마가 기뻐하여 장 부인께 그 일을 전하니 부인이 그 두터운 덕에 감축하며 곧 사람과 말을 차려 여남으로 보냈다. 장 부인은 참정 부인이 오신다는 말을 듣고 반나절 거리의 정자까지 나아가 맞았다. 참정 부인이 장 부인의 손을 잡고 반기며 말하였다. \"미천한 몸이 딸 하나를 데리고 세월을 보내다가 뜻밖에 이렇게 된 것은 부인의 은덕이옵니다.\" 장 부인은 지난 일을 생각하여 한편 반갑고 한편 부끄러웠다. 서로 맞아 집에 돌아와 평장 부인께 뵈니, 그 외로움을 헤아려 동기같이 한 집에 머물게 하니 세월 가는 줄을 몰랐다. 공주와 최 부인도 참정 부인을 친어머니같이 섬기니, 그 집안의 영화롭고 귀하며 화목함은 고금에 드물었다.","sp":[[4,6,"P","김희경"],[27,29,"P","김평"],[63,67,"P","장설빙"],[105,107,"P","김희경"],[109,114,"P","이 참정 부인"],[136,138,"P","김평"],[164,166,"P","김희경"],[173,177,"P","장설빙"],[228,232,"P","장설빙"],[234,239,"P","이 참정 부인"],[274,279,"P","이 참정 부인"],[281,285,"P","장설빙"],[356,360,"P","장설빙"],[404,408,"P","장설빙"],[456,458,"P","일월공주"],[460,464,"P","최씨"],[466,471,"P","이 참정 부인"]]},{"c":2,"sub":"","t":"이때 부마는 네 부인을 맞아 세월 가는 줄 모르고 지냈다. 그러나 즐거움이 다하면 슬픔이 오고 고생 끝에 낙이 온다 하더니, 평장 부부가 갑자기 병을 얻어 세상을 버렸다. 예로써 선산에 안장하고 삼년상을 지냈는데, 또 참정 부인이 세상을 버리니 소저와 장 부인이 애통해하며 우는 모습은 차마 볼 수 없었다. 예로써 선산에 합장하고 삼 년을 지냈다. 장 부인은 아들 넷을 두고, 최 부인은 삼남 일녀를 낳고, 공주는 아들 셋을 두고, 이 부인은 사남 이녀를 낳으니 자손이 번성하고 부귀영화가 천하에 으뜸이었다. 맏아들의 이름은 영봉이요, 둘째는 경봉이요, 셋째는 영봉이요, 넷째는 춘봉이요, 다섯째는 성봉이요, 여섯째는 추봉이요, 일곱째는 황봉이요, 여덟째는 석봉이요, 아홉째는 창봉이요, 열째는 인봉이요, 열한째는 화봉이요, 열두째는 양봉이요, 열셋째는 채봉이요, 열넷째는 호봉이었다. 맏딸의 이름은 봉번이요, 둘째 딸은 봉영이요, 셋째 딸은 봉월이었다. 열네 아들과 세 딸을 두었는데 모두 아버지의 풍채와 어머니의 모습을 닮아 범 같고 용 같았다. 각각 젊은 나이에 급제하여 한림학사며 내각과 옥당의 청환 요직이며 높은 벼슬로 김씨 집안이 혁혁하였다.","sp":[[3,5,"P","김희경"],[70,72,"P","김평"],[122,127,"P","이 참정 부인"],[141,145,"P","장설빙"],[195,199,"P","장설빙"],[211,215,"P","최씨"],[228,230,"P","일월공주"],[242,246,"P","이 소저"]]},{"c":2,"sub":"","t":"한편, 이때는 마침 가을 팔월 보름께였다. 하루는 후원에서 달구경 모임을 열고 부마가 네 부인과 함께 달빛을 감상하다가 좋은 술과 안주를 내어 바람을 읊고 달을 노래하며 즐겼다. 그런데 하늘에서 옥피리 소리가 나더니 한 선관이 내려와 부마를 향해 말하였다. \"이별한 뒤 평안하셨습니까?\" 하며 읍하므로 부마가 답례하며 말하였다. \"존사를 한 번도 뵌 적이 없는데 이별이라니 무슨 말씀이십니까?\" 선관이 살짝 웃으며 말하였다. \"삼청에서 그대가 네 선녀와 눈짓을 나눈 죄로 인간 세상에 귀양 왔는데, 옥황상제께서 감동하시어 죄를 특별히 용서하시고 나로 하여금 그대와 네 부인을 데려오라 하시기에 왔으니, 지체하지 말고 길을 떠나사이다.\" 부마가 생각하니 달리 도리가 없는 줄 알고 여러 자녀를 불러, 충효와 절의 밖의 행동은 하지 말라고 잠깐 경계하였다. 말을 마치자 옥피리 소리가 다시 나더니 부마가 여러 부인과 함께 선관을 따라 삼청 세계로 올라갔다. 그 여러 자녀가 하늘을 바라보며 애통해하고 서러워하였다.","sp":[[44,46,"P","김희경"],[123,125,"P","선관"],[131,133,"P","김희경"],[169,171,"P","김희경"],[221,223,"P","선관"],[280,282,"P","황제"],[356,358,"P","김희경"],[444,446,"P","김희경"],[458,460,"P","선관"]]},{"c":2,"sub":"","t":"옛글에 이르기를, 착한 나무에 착한 열매가 열리고 악한 나무에 악한 열매가 열린다 하더니, 장씨와 김씨 두 사람을 가리켜 한 말인 듯하다. 읽는 이들이여, 김희경과 장수정의 충효와 절의, 그리고 여러 동렬의 화목하던 행적을 열심히 본받을지어다. [끝]","sp":[[87,90,"P","김희경"],[92,95,"P","장설빙"]]}]});
